import { PoetData, SeasonType } from './poetsData';

export const TILE_SIZE = 16;
export const EXTERIOR_COLS = 36;
export const EXTERIOR_ROWS = 28;
export const HARBOR_COLS = EXTERIOR_COLS;
export const HARBOR_ROWS = EXTERIOR_ROWS;
export const VIEWPORT_COLS = 16;
export const VIEWPORT_ROWS = 12;
export const VIEWPORT_WIDTH = 256;
export const VIEWPORT_HEIGHT = 192;

// Screen Grid bounds in pixels: 576 x 448
export const MAP_PIXEL_WIDTH = EXTERIOR_COLS * TILE_SIZE; // 576
export const MAP_PIXEL_HEIGHT = EXTERIOR_ROWS * TILE_SIZE; // 448

// Camera clamping max offsets: [0, 576 - 256] = [0, 320], [0, 448 - 192] = [0, 256]
export const MAX_CAM_X = MAP_PIXEL_WIDTH - VIEWPORT_WIDTH; // 320
export const MAX_CAM_Y = MAP_PIXEL_HEIGHT - VIEWPORT_HEIGHT; // 256

export function findNearestWalkableTile(
  screenData: HarborScreenData,
  targetX: number,
  targetY: number,
  cols = EXTERIOR_COLS,
  rows = EXTERIOR_ROWS
): { x: number; y: number } {
  if (
    targetX >= 0 &&
    targetX < cols &&
    targetY >= 0 &&
    targetY < rows &&
    !screenData.solid[targetY]?.[targetX]
  ) {
    return { x: targetX, y: targetY };
  }
  for (let rad = 1; rad <= 16; rad++) {
    for (let dy = -rad; dy <= rad; dy++) {
      for (let dx = -rad; dx <= rad; dx++) {
        if (Math.abs(dx) === rad || Math.abs(dy) === rad) {
          const cx = targetX + dx;
          const cy = targetY + dy;
          if (cx >= 0 && cx < cols && cy >= 0 && cy < rows && !screenData.solid[cy]?.[cx]) {
            return { x: cx, y: cy };
          }
        }
      }
    }
  }
  return { x: targetX, y: targetY };
}

export type FacingDirection = 'UP' | 'DOWN' | 'LEFT' | 'RIGHT';
export type OverworldScreenId = 'HARBOR' | 'TOWN' | 'CLIFFS' | 'RUINS' | 'TREELINE' | 'SUMMIT' | 'NIGHTINGALE' | 'LUNCH_COUNTER' | 'FORGE' | 'BLUE_HOUSE' | 'MOUNTAIN_GOAT' | 'LIBRARY' | 'KITCHEN' | 'GRAVEYARD' | 'WHITE_HOUSE' | 'HERMITAGE' | 'RENTED_ROOM' | 'LYRIC_SANCTUARY' | 'ROOM_BOATHOUSE' | 'BOATHOUSE' | 'CAFE_DE_FLORE' | 'ROOM_CAFE_DE_FLORE' | 'SHAKESPEARE_CO' | 'ROOM_SHAKESPEARE_CO';
