export interface NPCPatrolState {
  type: 'LINEAR_2PT';
  p1: { x: number; y: number };
  p2: { x: number; y: number };
  state: 'IDLE_P1' | 'WALKING_TO_P2' | 'IDLE_P2' | 'WALKING_TO_P1';
  pauseTimer: number;
  pauseDuration: number;
  walkSpeed: number;
  currentStepProgress: number;
  stepFrom: { x: number; y: number };
  stepTo: { x: number; y: number };
  idleFacingP1: FacingDirection;
  idleFacingP2: FacingDirection;
}

export interface NPCMovementTurn {
  type: 'TURN';
  directions: FacingDirection[];
  interval: number;
  timer?: number;
  currentIndex?: number;
}

export interface NPCMovementPath {
  type: 'PATH';
  waypoints: { x: number; y: number; pause?: number; facing?: FacingDirection }[];
  speed: number;
  pauseAtStart: number;
  currentWaypointIndex?: number;
  pauseTimer?: number;
  timer?: number;
  stepProgress?: number;
  stepFrom?: { x: number; y: number };
  stepTo?: { x: number; y: number };
  dedicatedPassableTiles?: { x: number; y: number }[];
}

export type CavafyPhase =
  | 'STROLL_WEST'
  | 'PAUSE_WEST'
  | 'STROLL_EAST'
  | 'PAUSE_EAST'
  | 'THRESHOLD_PAUSE'
  | 'ENTERING_DOOR'
  | 'INSIDE'
  | 'EXITING_DOOR'
  | 'POST_EXIT_GAZE';

export interface CavafyRoutineState {
  phase: CavafyPhase;
  timer: number;
  startX: number;
  startY: number;
  targetX: number;
  targetY: number;
  progress: number;
  speed: number;
  pauseDuration?: number;
}

export type MaryOliverPhase =
  | 'STROLL_EAST'
  | 'STROLL_WEST'
  | 'PAUSE'
  | 'FEED_REACH'
  | 'FEED_TOSS'
  | 'WATCH_FEED';

export type WalcottPhase =
  | 'STROLL_WEST'
  | 'PAUSE_WEST'
  | 'STROLL_EAST'
  | 'PAUSE_EAST';

export interface WalcottRoutineState {
  phase: WalcottPhase;
  timer: number;
  startX: number;
  startY: number;
  targetX: number;
  targetY: number;
  progress: number;
  speed: number;
  pauseDuration?: number;
}

export interface PondCrumbParticle {
  x: number;
  y: number;
  startX: number;
  startY: number;
  targetX: number;
  targetY: number;
  progress: number;
  arcHeight: number;
  landed: boolean;
  rippleTimer: number;
  eaten: boolean;
}

export interface MaryOliverRoutineState {
  phase: MaryOliverPhase;
  timer: number;
  feedCooldown: number;
  speed: number;
  tossProgress?: number;
  crumbs?: PondCrumbParticle[];
}

export type NPCMovement =
  | { type: 'STILL' }
  | NPCMovementTurn
  | NPCMovementPath;

export interface HarborNPC {
  id: string;
  name: string;
  poetId?: string;
  x: number;
  y: number;
  pxX?: number;
  pxY?: number;
  facing: FacingDirection;
  introLine?: string;
  greeting?: string;
  gateLine?: string;
  postFightGreeting?: string;
  postEncounterGreeting?: string;
  menuOptions?: string[];
  rematchGreeting?: string;
  duelLine?: string;
  normalLines?: string[];
  recruitLines?: string[];
  talkLines?: string[];
  dialogueLines: string[];
  currentDialogueIndex: number;
  hasSeenIntro?: boolean;
  hasFoughtBefore?: boolean;
  greeted?: boolean;
  talkIndex?: number;
  isFightable: boolean;
  isDuelist?: boolean;
  isStarterRecruit?: boolean;
  isRecruited?: boolean;
  isDissolving?: boolean;
  dissolveTimer?: number;
  dissolveDuration?: number;
  spriteKey: string;
  isActive: boolean;
  isMoving?: boolean;
  walkStep?: number;
  isInteracting?: boolean;
  patrol?: NPCPatrolState;
  movement?: NPCMovement;
  cavafyRoutine?: CavafyRoutineState;
  maryOliverRoutine?: MaryOliverRoutineState;
  walcottRoutine?: WalcottRoutineState;
  opacity?: number;
  showEmote?: boolean;
}

