export function createFreshHarborNpcs(): HarborNPC[] {
  return JSON.parse(JSON.stringify(INITIAL_HARBOR_NPCS));
}

export function createFreshTownNpcs(): HarborNPC[] {
  return JSON.parse(JSON.stringify(INITIAL_TOWN_NPCS));
}

export function createFreshNightingaleNpcs(): HarborNPC[] {
  return JSON.parse(JSON.stringify(INITIAL_NIGHTINGALE_NPCS));
}

export function createFreshLunchNpcs(): HarborNPC[] {
  const npcs: HarborNPC[] = JSON.parse(JSON.stringify(INITIAL_LUNCH_NPCS));
  return npcs.map((n) => {
    if (n.id === 'npc_lunch_ohara' && n.movement?.type === 'PATH') {
      return {
        ...n,
        greeted: false,
        talkIndex: 0,
        movement: {
          ...n.movement,
          pauseTimer: 2.0 + Math.random() * 1.5, // 2.0 - 3.5s initial pause
        },
      };
    }
    if (n.id === 'npc_lunch_stevens' && n.movement?.type === 'PATH') {
      return {
        ...n,
        greeted: false,
        talkIndex: 0,
        movement: {
          ...n.movement,
          pauseTimer: 5.0 + Math.random() * 2.5, // 5.0 - 7.5s initial pause
        },
      };
    }
    if (n.id === 'npc_lunch_wcw' && n.movement?.type === 'PATH') {
      return {
        ...n,
        greeted: false,
        talkIndex: 0,
        movement: {
          ...n.movement,
          pauseTimer: 7.0 + Math.random() * 2.0, // 7.0 - 9.0s initial pause
        },
      };
    }
    return {
      ...n,
      greeted: false,
      talkIndex: 0,
    };
  });
}

export function createFreshCliffsNpcs(): HarborNPC[] {
  return JSON.parse(JSON.stringify(INITIAL_CLIFFS_NPCS));
}

