  // Floor: Rich warm cedar / pine timber plank flooring (#854c25, #9c5c2e, #6e3e1c, knots: #4d260e)
  // Walls: Weathered mountain stone masonry (#605850, #786e64, #4c443c) with dark hewn cedar crossbeams (#4a2812, #5e3318)
  // Hearth: Fieldstone fireplace with crackling logs, warm embers, and hanging cast-iron tea kettle with rising steam
  // Bar: Live-edge cedar bar with clay flagons, celadon cups, and hanging dried mountain herbs
  // Sign: Carved wooden mountain goat tavern sign
  // Window: Open stone mountain archway showing distant misty mountain peaks and temple ruins
  // Relics: Omar Khayyám's flagon, bread & scroll; Li Bai's celadon wine cup & moon flask; Bashō's bamboo hat, staff & sandals
  // ==========================================================================
  const C_CEDAR_BASE = '#854c25';
  const C_CEDAR_LT = '#9c5c2e';
  const C_CEDAR_DK = '#6e3e1c';
  const C_CEDAR_HI = '#b46e38';
  const C_CEDAR_SEAM = '#48250f';
  const C_CEDAR_KNOT = '#3d1d0a';

  const C_MSTONE_BASE = '#686058';
  const C_MSTONE_LT = '#80766c';
  const C_MSTONE_DK = '#504840';
  const C_MSTONE_MORTAR = '#3a342e';
  const C_BEAM_WOOD = '#4a2812';
  const C_BEAM_LT = '#683a1b';
  const C_BEAM_DK = '#321908';

  // --- ROW 33: TIMBER FLOOR, STONE & BEAM WALLS, ENTRANCE DOOR ---
  // 1. GOAT_INT_FLOOR (tx: 0, ty: 33) - Rich, warm cedar/pine timber plank flooring
  rect(0, 33, 0, 0, 16, 16, C_CEDAR_BASE);
  rect(0, 33, 0, 0, 16, 1, C_CEDAR_HI);
  rect(0, 33, 0, 15, 16, 1, C_CEDAR_SEAM);
  for (let y = 0; y < 16; y += 4) {
    rect(0, 33, 0, y, 16, 1, C_CEDAR_SEAM);
    rect(0, 33, 0, y + 1, 16, 1, C_CEDAR_LT);
    px(0, 33, 3, y + 2, C_CEDAR_KNOT, 1, 1); // Square hand-forged wood peg
    px(0, 33, 12, y + 2, C_CEDAR_KNOT, 1, 1);
  }
  px(0, 33, 5, 6, C_CEDAR_DK, 4, 1); // Subtle wood grain
  px(0, 33, 8, 10, C_CEDAR_DK, 5, 1);

  // 2. GOAT_INT_FLOOR_ALT (tx: 1, ty: 33) - Timber plank with subtle grain & knots
  rect(1, 33, 0, 0, 16, 16, C_CEDAR_LT);
  rect(1, 33, 0, 0, 16, 1, C_CEDAR_HI);
  for (let y = 0; y < 16; y += 4) {
    rect(1, 33, 0, y, 16, 1, C_CEDAR_SEAM);
    rect(1, 33, 0, y + 1, 16, 1, C_CEDAR_BASE);
  }
  // Characteristic wood knot
  rect(1, 33, 6, 5, 3, 3, C_CEDAR_KNOT);
  px(1, 33, 7, 6, '#261105', 1, 1);
  px(1, 33, 5, 6, C_CEDAR_DK, 5, 1);
  px(1, 33, 2, 10, C_CEDAR_DK, 6, 1);

  // 3. GOAT_INT_FLOOR_DARK (tx: 2, ty: 33) - Shaded cedar plank
  rect(2, 33, 0, 0, 16, 16, C_CEDAR_DK);
  for (let y = 0; y < 16; y += 4) {
    rect(2, 33, 0, y, 16, 1, C_CEDAR_SEAM);
    rect(2, 33, 0, y + 1, 16, 1, C_CEDAR_BASE);
  }
  px(2, 33, 4, 6, C_CEDAR_KNOT, 4, 1);

  // 4. GOAT_INT_WALL_TOP (tx: 3, ty: 33) - Weathered mountain stone masonry with dark hewn cedar beam (Y: 0)
