  rect(3, 33, 0, 0, 16, 3, C_DARK_OUTLINE);
  rect(3, 33, 0, 3, 16, 13, C_MSTONE_BASE);
  rect(3, 33, 0, 3, 16, 2, C_MSTONE_LT);
  // Hewn cedar horizontal crossbeam
  rect(3, 33, 0, 8, 16, 4, C_DARK_OUTLINE);
  rect(3, 33, 0, 9, 16, 2, C_BEAM_WOOD);
  rect(3, 33, 0, 9, 16, 1, C_BEAM_LT);
  px(3, 33, 5, 10, C_BEAM_DK, 1, 1);

  // 5. GOAT_INT_WALL_FACE (tx: 4, ty: 33) - Weathered mountain stone masonry with dark hewn cedar crossbeams (Y: 1)
