  px(4, 33, 12, 5, C_MSTONE_MORTAR, 1, 6);
  px(4, 33, 2, 2, C_MSTONE_LT, 4, 1);
  px(4, 33, 8, 8, C_MSTONE_LT, 4, 1);
  // Hewn cedar wall beam & timber joints
