  rect(4, 33, 0, 12, 16, 3, C_BEAM_WOOD);
  rect(4, 33, 0, 12, 16, 1, C_BEAM_LT);
  px(4, 33, 4, 13, C_BEAM_DK, 2, 1); // Timber peg
