  rect(5, 33, 3, 0, 13, 16, C_MSTONE_BASE);
  rect(5, 33, 3, 0, 3, 16, C_BEAM_WOOD); // Massive vertical cedar upright timber post
  rect(5, 33, 4, 0, 1, 16, C_BEAM_LT);
  rect(5, 33, 6, 0, 10, 16, C_MSTONE_BASE);
  px(5, 33, 6, 5, C_MSTONE_MORTAR, 10, 1);
  px(5, 33, 6, 11, C_MSTONE_MORTAR, 10, 1);

  // 7. GOAT_INT_WALL_SIDE_R (tx: 6, ty: 33) - Right stone & cedar wall
