  const C_LIB_MARBLE_SEAM = '#38342e';

  const C_LIB_CARPET_BASE = '#741620';
  const C_LIB_CARPET_LT = '#911f2c';
  const C_LIB_CARPET_DK = '#541018';
  const C_LIB_CARPET_GOLD = '#d97706';
  const C_LIB_CARPET_GOLD_HI = '#fbbf24';

  const C_LIB_STONE_BASE = '#59534a';
  const C_LIB_STONE_LT = '#736b60';
  const C_LIB_STONE_DK = '#423d36';
  const C_LIB_STONE_SEAM = '#2c2824';

  const C_LIB_OAK_WOOD = '#3b2012';
  const C_LIB_OAK_LT = '#59321d';
  const C_LIB_OAK_DK = '#26140a';

  const C_BANKER_GREEN = '#15803d';
  const C_BANKER_GREEN_HI = '#4ade80';

  // --- ROW 36: FLOORS (SMOOTH DARK OAK PLANKS, RUSSET LEAVES) & CLERESTORY ---
