  rect(0, 36, 0, 0, 16, 16, '#2c1b12');
  // Top horizontal plank (y: 0..7)
  rect(0, 36, 0, 0, 16, 1, '#342116');
  rect(0, 36, 0, 7, 16, 1, '#22150e');
  px(0, 36, 7, 0, '#22150e', 1, 7); // Gentle subtle vertical join
  // Bottom horizontal plank (y: 8..15)
  rect(0, 36, 0, 8, 16, 1, '#342116');
  rect(0, 36, 0, 15, 16, 1, '#22150e');

  // 2. LIBRARY_INT_FLOOR_ALT (tx: 1, ty: 36) - Smooth dark oak floorboard alt (gentle staggered join)
