  // ==========================================================================
  // ROW 70, 71, 72, 73: SCREEN 4 (THE RUINS) OVERHAUL - CLASSICAL LIBRARY, STREAM & BRIDGES, FORECOURT, TREES
  // ==========================================================================
  const C_MARBLE_WHITE = '#ffffff';
  const C_MARBLE_IVORY = '#f8fafc';
  const C_MARBLE_LIGHT = '#e2e8f0';
  const C_MARBLE_MID   = '#cbd5e1';
  const C_MARBLE_SHADE = '#94a3b8';
  const C_MARBLE_DEEP  = '#64748b';
  const C_MARBLE_DARK  = '#475569';
  const C_MARBLE_SEAM  = '#334155';

  const C_IVY_STEM  = '#283618';
  const C_IVY_DEEP  = '#365314';
  const C_IVY_MID   = '#4d7c0f';
  const C_IVY_LIGHT = '#65a30d';
  const C_IVY_RED_DK = '#7f1d1d';
  const C_IVY_RED_MID = '#991b1b';
  const C_IVY_RED_LT = '#dc2626';

  // --- ROW 70: CLASSICAL FACADE UPPER TIERS (PEDIMENT, FRIEZE, CAPITALS, COLONNADE) ---
  // Palette: Warm aged limestone / recessed cream-stone & travertine ivory
  // Shaded temple portico wall: authentic warm aged limestone (#c8bda8) with architectural shadow (#9e927d)
  const C_TRAVERTINE_WHITE = '#faf8f2';
  const C_TRAVERTINE_IVORY = '#f3ede0';
  const C_TRAVERTINE_LIGHT = '#e8decb';
  const C_TRAVERTINE_MID   = '#d8ccb6';
  const C_TRAVERTINE_SHADE = '#b8a890';
  const C_TRAVERTINE_DEEP  = '#8c7a62';
  const C_TRAVERTINE_DARK  = '#5c4e3e';
  const C_PORTICO_BACKWALL = '#c8bda8'; // Authentic warm aged limestone / recessed cream-stone
  const C_PORTICO_SHADOW   = '#9e927d'; // Subtle architectural shadow
  const C_PORTICO_DEEP     = '#7d7260';
  const C_INSCRIPTION_DARK = '#3a3328'; // Sharp carved dark charcoal / antique bronze

  // 1. FACADE_PEDIMENT_1 (tx: 0, ty: 70) [c = 16] - Symmetrical Left Pediment Corner, Raking Cornice & Acroterion
  rect(0, 70, 0, 0, 16, 16, 'transparent');
  // Horizontal base cornice at y: 13..15
  rect(0, 70, 0, 13, 16, 3, C_DARK_OUTLINE);
  rect(0, 70, 0, 13, 16, 2, C_TRAVERTINE_IVORY);
  px(0, 70, 0, 13, C_TRAVERTINE_WHITE, 16, 1);
  // Raking cornice rising from y = 12 on left (x = 1) to y = 8 on right (x = 15)
  for (let x = 1; x < 16; x++) {
    const topY = Math.round(12 - (x - 1) * 0.28);
    rect(0, 70, x, topY, 1, 13 - topY, C_TRAVERTINE_LIGHT); // Tympanum stone
    px(0, 70, x, topY, C_DARK_OUTLINE, 1, 1);
    px(0, 70, x, topY + 1, C_TRAVERTINE_WHITE, 1, 1); // Raking cornice highlight
    px(0, 70, x, topY + 2, C_TRAVERTINE_MID, 1, 1);
  }
  // Left acroterion scroll on outer corner (x: 0..3, y: 8..12)
  rect(0, 70, 0, 8, 3, 5, C_DARK_OUTLINE);
  rect(0, 70, 1, 9, 2, 4, C_TRAVERTINE_WHITE);
  px(0, 70, 0, 8, C_TRAVERTINE_IVORY, 2, 2);
  // Trailing crimson autumn ivy
  px(0, 70, 2, 9, C_IVY_RED_MID, 2, 5);
  px(0, 70, 1, 11, C_IVY_RED_LT, 2, 3);

  // 2. FACADE_PEDIMENT_2 (tx: 1, ty: 70) [c = 17] - Symmetrical Left Slope Rising
  rect(1, 70, 0, 0, 16, 16, 'transparent');
  rect(1, 70, 0, 13, 16, 3, C_DARK_OUTLINE);
  rect(1, 70, 0, 13, 16, 2, C_TRAVERTINE_IVORY);
  px(1, 70, 0, 13, C_TRAVERTINE_WHITE, 16, 1);
  // Raking cornice rising from y = 8 to y = 4
  for (let x = 0; x < 16; x++) {
    const topY = Math.round(8 - x * 0.25);
    rect(1, 70, x, topY, 1, 13 - topY, C_TRAVERTINE_LIGHT);
    px(1, 70, x, topY, C_DARK_OUTLINE, 1, 1);
    px(1, 70, x, topY + 1, C_TRAVERTINE_WHITE, 1, 1);
    px(1, 70, x, topY + 2, C_TRAVERTINE_MID, 1, 1);
  }
  // Tympanum carved bas-relief acanthus scrollwork
  px(1, 70, 5, 8, C_TRAVERTINE_DEEP, 5, 2);
  px(1, 70, 6, 8, C_TRAVERTINE_WHITE, 3, 1);

  // 3. FACADE_PEDIMENT_3 (tx: 2, ty: 70) [c = 18] - Symmetrical Left Slope to Peak
  rect(2, 70, 0, 0, 16, 16, 'transparent');
  rect(2, 70, 0, 13, 16, 3, C_DARK_OUTLINE);
  rect(2, 70, 0, 13, 16, 2, C_TRAVERTINE_IVORY);
  px(2, 70, 0, 13, C_TRAVERTINE_WHITE, 16, 1);
  // Raking cornice rising from y = 4 to apex y = 0
  for (let x = 0; x < 16; x++) {
    const topY = Math.round(4 - x * 0.25);
    rect(2, 70, x, topY, 1, 13 - topY, C_TRAVERTINE_LIGHT);
    px(2, 70, x, topY, C_DARK_OUTLINE, 1, 1);
    px(2, 70, x, topY + 1, C_TRAVERTINE_WHITE, 1, 1);
    px(2, 70, x, topY + 2, C_TRAVERTINE_MID, 1, 1);
  }
  // Tympanum carved bas-relief laurel garland
  px(2, 70, 6, 7, C_TRAVERTINE_DEEP, 6, 3);
  px(2, 70, 7, 7, C_TRAVERTINE_WHITE, 4, 1);

  // 4. FACADE_PEDIMENT_4 (tx: 3, ty: 70) [c = 19] - Symmetrical Right Peak with Apex Finial & Slope Falling
  rect(3, 70, 0, 0, 16, 16, 'transparent');
  // Apex palmette finial in center between 18 and 19 (at x: 0..3, y: 0..3)
  rect(3, 70, 0, 0, 3, 4, C_DARK_OUTLINE);
  rect(3, 70, 0, 0, 2, 3, C_TRAVERTINE_WHITE);
  px(3, 70, 2, 1, C_TRAVERTINE_MID, 1, 2);
  rect(3, 70, 0, 13, 16, 3, C_DARK_OUTLINE);
  rect(3, 70, 0, 13, 16, 2, C_TRAVERTINE_IVORY);
  px(3, 70, 0, 13, C_TRAVERTINE_WHITE, 16, 1);
  // Raking cornice falling from apex y = 0 to y = 4
  for (let x = 0; x < 16; x++) {
    const topY = Math.round(0 + x * 0.25);
    rect(3, 70, x, topY, 1, 13 - topY, C_TRAVERTINE_LIGHT);
    px(3, 70, x, topY, C_DARK_OUTLINE, 1, 1);
    px(3, 70, x, topY + 1, C_TRAVERTINE_WHITE, 1, 1);
    px(3, 70, x, topY + 2, C_TRAVERTINE_MID, 1, 1);
  }
  // Tympanum carved bas-relief laurel garland
  px(3, 70, 4, 7, C_TRAVERTINE_DEEP, 6, 3);
  px(3, 70, 5, 7, C_TRAVERTINE_WHITE, 4, 1);

  // 5. FACADE_PEDIMENT_5 (tx: 4, ty: 70) [c = 20] - Symmetrical Right Slope Falling
  rect(4, 70, 0, 0, 16, 16, 'transparent');
  rect(4, 70, 0, 13, 16, 3, C_DARK_OUTLINE);
  rect(4, 70, 0, 13, 16, 2, C_TRAVERTINE_IVORY);
  px(4, 70, 0, 13, C_TRAVERTINE_WHITE, 16, 1);
  // Raking cornice falling from y = 4 to y = 8
  for (let x = 0; x < 16; x++) {
    const topY = Math.round(4 + x * 0.25);
    rect(4, 70, x, topY, 1, 13 - topY, C_TRAVERTINE_LIGHT);
    px(4, 70, x, topY, C_DARK_OUTLINE, 1, 1);
    px(4, 70, x, topY + 1, C_TRAVERTINE_WHITE, 1, 1);
    px(4, 70, x, topY + 2, C_TRAVERTINE_MID, 1, 1);
  }
  // Tympanum carved bas-relief acanthus scrollwork
  px(4, 70, 5, 8, C_TRAVERTINE_DEEP, 5, 2);
  px(4, 70, 6, 8, C_TRAVERTINE_WHITE, 3, 1);

  // 6. FACADE_PEDIMENT_6 (tx: 5, ty: 70) [c = 21] - Symmetrical Right Pediment Corner & Acroterion
  rect(5, 70, 0, 0, 16, 16, 'transparent');
  rect(5, 70, 0, 13, 16, 3, C_DARK_OUTLINE);
  rect(5, 70, 0, 13, 16, 2, C_TRAVERTINE_IVORY);
  px(5, 70, 0, 13, C_TRAVERTINE_WHITE, 16, 1);
  // Raking cornice falling from y = 8 to y = 12 on right (x = 14)
  for (let x = 0; x < 15; x++) {
    const topY = Math.round(8 + x * 0.28);
    rect(5, 70, x, topY, 1, 13 - topY, C_TRAVERTINE_LIGHT);
    px(5, 70, x, topY, C_DARK_OUTLINE, 1, 1);
    px(5, 70, x, topY + 1, C_TRAVERTINE_WHITE, 1, 1);
    px(5, 70, x, topY + 2, C_TRAVERTINE_MID, 1, 1);
  }
  // Right acroterion scroll on outer corner (x: 13..15, y: 8..12)
  rect(5, 70, 13, 8, 3, 5, C_DARK_OUTLINE);
  rect(5, 70, 13, 9, 2, 4, C_TRAVERTINE_WHITE);
  px(5, 70, 14, 8, C_TRAVERTINE_IVORY, 2, 2);
  // Trailing crimson ivy
  px(5, 70, 12, 9, C_IVY_RED_MID, 2, 5);
  px(5, 70, 13, 11, C_IVY_RED_LT, 2, 3);

  // --- ARCHITRAVE & "BIBLIOTHECA" ROMAN INSCRIPTION (tx: 6..11) ---
  // Helper to draw clean continuous marble architrave base on tile
  function drawArchitraveBase(tx: number) {
    rect(tx, 70, 0, 0, 16, 16, C_TRAVERTINE_LIGHT);
    rect(tx, 70, 0, 0, 16, 1, C_TRAVERTINE_WHITE); // Top molding highlight
    rect(tx, 70, 0, 1, 16, 1, C_TRAVERTINE_IVORY);
    rect(tx, 70, 0, 2, 16, 1, C_TRAVERTINE_SHADE); // Upper fillet shadow
    rect(tx, 70, 0, 13, 16, 1, C_TRAVERTINE_WHITE); // Lower fillet highlight
    rect(tx, 70, 0, 14, 16, 1, C_TRAVERTINE_MID);
    rect(tx, 70, 0, 15, 16, 1, C_PORTICO_SHADOW); // Underside architectural shadow
  }

  // Helper to draw clean Greek key / meander relief pattern segment
  function drawMeanderSegment(tx: number, startX: number, count: number) {
    for (let i = 0; i < count; i++) {
      const mx = startX + i * 5;
      if (mx + 4 > 16) break;
      // Meander border rails
      px(tx, mx, 4, C_TRAVERTINE_SHADE, 5, 1);
      px(tx, mx, 11, C_TRAVERTINE_SHADE, 5, 1);
      // Fret lines
      px(tx, mx, 5, C_TRAVERTINE_DARK, 1, 5);
      px(tx, mx + 1, 5, C_TRAVERTINE_DARK, 3, 1);
      px(tx, mx + 3, 6, C_TRAVERTINE_DARK, 1, 3);
      px(tx, mx + 2, 8, C_TRAVERTINE_DARK, 2, 1);
      px(tx, mx + 1, 9, C_TRAVERTINE_WHITE, 3, 1); // 3D relief bevel
    }
  }

  // 7. FACADE_FRIEZE_1 (tx: 6, ty: 70) [c = 16] - Architrave Left: Classical Greek Key / Meander Relief Pattern '[==='
  drawArchitraveBase(6);
  // Classical Greek key meander fretwork filling the left side
  drawMeanderSegment(6, 1, 3);
  px(6, 0, 3, C_IVY_MID, 2, 4); // Subtle touch of climbing ivy

  // 8. FACADE_FRIEZE_2 (tx: 7, ty: 70) [c = 17] - Architrave: Meander Transition & Roman Inscription "BIB"
  drawArchitraveBase(7);
  // Meander transition ending
  drawMeanderSegment(7, 0, 1);
  // Inscription text: 'B I B'
  // Letter 'B' at x: 5..8 (y: 5..10, height = 6)
  rect(7, 70, 5, 5, 1, 6, C_INSCRIPTION_DARK); // Stem
  px(7, 5, 5, C_INSCRIPTION_DARK, 4, 1);       // Top bar
  px(7, 5, 7, C_INSCRIPTION_DARK, 3, 1);       // Mid bar
  px(7, 5, 10, C_INSCRIPTION_DARK, 4, 1);      // Bot bar
  px(7, 8, 6, C_INSCRIPTION_DARK, 1, 1);       // Upper loop
  px(7, 8, 8, C_INSCRIPTION_DARK, 1, 2);       // Lower loop
  px(7, 5, 11, C_TRAVERTINE_WHITE, 4, 1);      // V-cut chiseled bottom highlight

  // Letter 'I' at x: 10..11 (y: 5..10)
  rect(7, 70, 10, 5, 1, 6, C_INSCRIPTION_DARK); // Stem
  px(7, 9, 5, C_INSCRIPTION_DARK, 3, 1);        // Top serif
  px(7, 9, 10, C_INSCRIPTION_DARK, 3, 1);       // Bottom serif
  px(7, 9, 11, C_TRAVERTINE_WHITE, 3, 1);

  // Letter 'B' at x: 13..15 (y: 5..10)
  rect(7, 70, 13, 5, 1, 6, C_INSCRIPTION_DARK);
  px(7, 13, 5, C_INSCRIPTION_DARK, 3, 1);
  px(7, 13, 7, C_INSCRIPTION_DARK, 3, 1);
  px(7, 13, 10, C_INSCRIPTION_DARK, 3, 1);
  px(7, 15, 6, C_INSCRIPTION_DARK, 1, 1);
  px(7, 15, 8, C_INSCRIPTION_DARK, 1, 2);
  px(7, 13, 11, C_TRAVERTINE_WHITE, 3, 1);

  // 9. FACADE_FRIEZE_3 (tx: 8, ty: 70) [c = 18] - Architrave: Roman Inscription "LIO"
  drawArchitraveBase(8);
  // Letter 'L' at x: 1..4 (y: 5..10)
  rect(8, 70, 1, 5, 1, 6, C_INSCRIPTION_DARK); // Stem
  px(8, 1, 5, C_INSCRIPTION_DARK, 2, 1);        // Top serif
  px(8, 1, 10, C_INSCRIPTION_DARK, 4, 1);       // Bottom foot
  px(8, 1, 11, C_TRAVERTINE_WHITE, 4, 1);

  // Letter 'I' at x: 6..7 (y: 5..10)
  rect(8, 70, 6, 5, 1, 6, C_INSCRIPTION_DARK);
  px(8, 5, 5, C_INSCRIPTION_DARK, 3, 1);
  px(8, 5, 10, C_INSCRIPTION_DARK, 3, 1);
  px(8, 5, 11, C_TRAVERTINE_WHITE, 3, 1);

  // Letter 'O' at x: 9..14 (y: 5..10)
  rect(8, 70, 10, 5, 4, 1, C_INSCRIPTION_DARK); // Top curve
  rect(8, 70, 10, 10, 4, 1, C_INSCRIPTION_DARK); // Bot curve
  rect(8, 70, 9, 6, 1, 4, C_INSCRIPTION_DARK);  // Left curve
  rect(8, 70, 14, 6, 1, 4, C_INSCRIPTION_DARK); // Right curve
  px(8, 10, 11, C_TRAVERTINE_WHITE, 4, 1);

  // 10. FACADE_FRIEZE_4 (tx: 9, ty: 70) [c = 19] - Architrave: Roman Inscription "THE"
  drawArchitraveBase(9);
  // Letter 'T' at x: 1..5 (y: 5..10)
  rect(9, 70, 1, 5, 5, 1, C_INSCRIPTION_DARK); // Top crossbar
  rect(9, 70, 3, 5, 1, 6, C_INSCRIPTION_DARK); // Stem
  px(9, 2, 10, C_INSCRIPTION_DARK, 3, 1);       // Base serif
  px(9, 2, 11, C_TRAVERTINE_WHITE, 3, 1);

  // Letter 'H' at x: 7..10 (y: 5..10)
  rect(9, 70, 7, 5, 1, 6, C_INSCRIPTION_DARK);  // Left stem
  rect(9, 70, 10, 5, 1, 6, C_INSCRIPTION_DARK); // Right stem
  rect(9, 70, 7, 7, 4, 1, C_INSCRIPTION_DARK);  // Mid crossbar
  px(9, 6, 5, C_INSCRIPTION_DARK, 2, 1);
  px(9, 10, 5, C_INSCRIPTION_DARK, 2, 1);
  px(9, 6, 10, C_INSCRIPTION_DARK, 2, 1);
  px(9, 10, 10, C_INSCRIPTION_DARK, 2, 1);
  px(9, 6, 11, C_TRAVERTINE_WHITE, 6, 1);

  // Letter 'E' at x: 12..15 (y: 5..10)
  rect(9, 70, 12, 5, 1, 6, C_INSCRIPTION_DARK); // Stem
  px(9, 12, 5, C_INSCRIPTION_DARK, 4, 1);        // Top bar
  px(9, 12, 7, C_INSCRIPTION_DARK, 3, 1);        // Mid bar
  px(9, 12, 10, C_INSCRIPTION_DARK, 4, 1);       // Bot bar
  px(9, 12, 11, C_TRAVERTINE_WHITE, 4, 1);

  // 11. FACADE_FRIEZE_5 (tx: 10, ty: 70) [c = 20] - Architrave: Roman Inscription "CA" & Meander Transition
  drawArchitraveBase(10);
  // Letter 'C' at x: 0..4 (y: 5..10)
  rect(10, 70, 1, 5, 4, 1, C_INSCRIPTION_DARK); // Top curve
  rect(10, 70, 1, 10, 4, 1, C_INSCRIPTION_DARK); // Bot curve
  rect(10, 70, 0, 6, 1, 4, C_INSCRIPTION_DARK);  // Left curve
  px(10, 4, 6, C_INSCRIPTION_DARK, 1, 1);        // Top serif
  px(10, 4, 9, C_INSCRIPTION_DARK, 1, 1);        // Bot serif
  px(10, 1, 11, C_TRAVERTINE_WHITE, 4, 1);

  // Letter 'A' at x: 6..10 (y: 5..10)
  rect(10, 70, 6, 7, 1, 4, C_INSCRIPTION_DARK);  // Left leg
  rect(10, 70, 10, 7, 1, 4, C_INSCRIPTION_DARK); // Right leg
  rect(10, 70, 7, 5, 3, 2, C_INSCRIPTION_DARK);  // Apex peak
  rect(10, 70, 7, 8, 3, 1, C_INSCRIPTION_DARK);  // Crossbar
  px(10, 5, 10, C_INSCRIPTION_DARK, 2, 1);       // Left foot serif
  px(10, 10, 10, C_INSCRIPTION_DARK, 2, 1);      // Right foot serif
  px(10, 5, 11, C_TRAVERTINE_WHITE, 7, 1);

  // Meander lead-in on right
  drawMeanderSegment(10, 12, 1);

  // 12. FACADE_FRIEZE_6 (tx: 11, ty: 70) [c = 21] - Architrave Right: Classical Greek Key / Meander Relief Pattern '===]'
  drawArchitraveBase(11);
  drawMeanderSegment(11, 1, 3);
  px(11, 14, 3, C_IVY_RED_MID, 2, 5); // Subtle touch of climbing ivy on right edge

  // 13. FACADE_CAPITAL_L (tx: 12, ty: 70) [c = 16] - Corinthian capital over Pillar 1 with warm aged limestone back wall
  rect(12, 70, 0, 0, 16, 16, C_PORTICO_BACKWALL);
  px(12, 70, 0, 0, C_PORTICO_SHADOW, 16, 3); // Subtle architectural shadow
  // Capital abacus slab (y: 1..3, x: 2..13)
  rect(12, 70, 2, 1, 12, 3, C_DARK_OUTLINE);
  rect(12, 70, 3, 2, 10, 2, C_TRAVERTINE_WHITE);
  // Carved acanthus leaves & volutes
  rect(12, 70, 3, 4, 10, 9, C_DARK_OUTLINE);
  rect(12, 70, 4, 4, 8, 8, C_TRAVERTINE_IVORY);
  px(12, 70, 2, 4, C_TRAVERTINE_WHITE, 2, 2); // Left volute
  px(12, 70, 12, 4, C_TRAVERTINE_WHITE, 2, 2); // Right volute
  px(12, 70, 5, 6, C_TRAVERTINE_LIGHT, 6, 2);
  px(12, 70, 4, 8, C_TRAVERTINE_DEEP, 8, 1);
  px(12, 70, 5, 9, C_TRAVERTINE_WHITE, 6, 2);
  // Astragal necking ring at y: 13..15
  rect(12, 70, 4, 13, 8, 3, C_DARK_OUTLINE);
  rect(12, 70, 5, 14, 6, 1, C_TRAVERTINE_WHITE);

  // 14. FACADE_CAPITAL_M (tx: 13, ty: 70) [c = 17, 20] - Inner Corinthian capital over Pillars 2 & 3
  rect(13, 70, 0, 0, 16, 16, C_PORTICO_BACKWALL);
  px(13, 70, 0, 0, C_PORTICO_SHADOW, 16, 3);
  rect(13, 70, 2, 1, 12, 3, C_DARK_OUTLINE);
  rect(13, 70, 3, 2, 10, 2, C_TRAVERTINE_WHITE);
  rect(13, 70, 3, 4, 10, 9, C_DARK_OUTLINE);
  rect(13, 70, 4, 4, 8, 8, C_TRAVERTINE_IVORY);
  px(13, 70, 2, 4, C_TRAVERTINE_WHITE, 2, 2);
  px(13, 70, 12, 4, C_TRAVERTINE_WHITE, 2, 2);
  px(13, 70, 5, 6, C_TRAVERTINE_LIGHT, 6, 2);
  px(13, 70, 4, 8, C_TRAVERTINE_DEEP, 8, 1);
  px(13, 70, 5, 9, C_TRAVERTINE_WHITE, 6, 2);
  rect(13, 70, 4, 13, 8, 3, C_DARK_OUTLINE);
  rect(13, 70, 5, 14, 6, 1, C_TRAVERTINE_WHITE);

  // 15. FACADE_PORTAL_HEAD_L (tx: 14, ty: 70) [c = 18] - Central portal header entablature left
  rect(14, 70, 0, 0, 16, 16, C_PORTICO_BACKWALL);
  px(14, 70, 0, 0, C_PORTICO_SHADOW, 16, 3);
  // Upper molding & carved laurel garland relief
  rect(14, 70, 0, 3, 16, 8, C_DARK_OUTLINE);
  rect(14, 70, 0, 4, 16, 6, C_TRAVERTINE_LIGHT);
  rect(14, 70, 0, 4, 16, 1, C_TRAVERTINE_WHITE);
  px(14, 70, 3, 6, C_TRAVERTINE_DEEP, 10, 2); // Garland relief carving
  px(14, 70, 4, 6, C_TRAVERTINE_WHITE, 8, 1);
  // Lower architrave cornice
  rect(14, 70, 0, 11, 16, 3, C_TRAVERTINE_IVORY);
  px(14, 70, 0, 11, C_TRAVERTINE_WHITE, 16, 1);
  px(14, 70, 0, 13, C_PORTICO_SHADOW, 16, 1);

  // 16. FACADE_PORTAL_HEAD_R (tx: 15, ty: 70) [c = 19] - Central portal header entablature right
  rect(15, 70, 0, 0, 16, 16, C_PORTICO_BACKWALL);
  px(15, 70, 0, 0, C_PORTICO_SHADOW, 16, 3);
  rect(15, 70, 0, 3, 16, 8, C_DARK_OUTLINE);
  rect(15, 70, 0, 4, 16, 6, C_TRAVERTINE_LIGHT);
  rect(15, 70, 0, 4, 16, 1, C_TRAVERTINE_WHITE);
  px(15, 70, 3, 6, C_TRAVERTINE_DEEP, 10, 2);
  px(15, 70, 4, 6, C_TRAVERTINE_WHITE, 8, 1);
  rect(15, 70, 0, 11, 16, 3, C_TRAVERTINE_IVORY);
  px(15, 70, 0, 11, C_TRAVERTINE_WHITE, 16, 1);
  px(15, 70, 0, 13, C_PORTICO_SHADOW, 16, 1);

  // 17. FACADE_CAPITAL_R (tx: 16, ty: 70) [c = 21] - Corinthian capital over Pillar 4 with ivy
  rect(16, 70, 0, 0, 16, 16, C_PORTICO_BACKWALL);
  px(16, 70, 0, 0, C_PORTICO_SHADOW, 16, 3);
  rect(16, 70, 2, 1, 12, 3, C_DARK_OUTLINE);
  rect(16, 70, 3, 2, 10, 2, C_TRAVERTINE_WHITE);
  rect(16, 70, 3, 4, 10, 9, C_DARK_OUTLINE);
  rect(16, 70, 4, 4, 8, 8, C_TRAVERTINE_IVORY);
  px(16, 70, 2, 4, C_TRAVERTINE_WHITE, 2, 2);
  px(16, 70, 12, 4, C_TRAVERTINE_WHITE, 2, 2);
  px(16, 70, 5, 6, C_TRAVERTINE_LIGHT, 6, 2);
  px(16, 70, 5, 9, C_TRAVERTINE_WHITE, 6, 2);
  rect(16, 70, 4, 13, 8, 3, C_DARK_OUTLINE);
  rect(16, 70, 5, 14, 6, 1, C_TRAVERTINE_WHITE);
  px(16, 70, 11, 4, C_IVY_RED_LT, 3, 4);

  // 18. FACADE_COLONNADE_WALL (tx: 17, ty: 70) [c = 16, 17, 20, 21] - Fluted Pillar Shaft with authentic warm limestone back wall
  rect(17, 70, 0, 0, 16, 16, C_PORTICO_BACKWALL); // Warm aged limestone portico wall (#c8bda8)
  px(17, 70, 0, 0, C_PORTICO_SHADOW, 4, 16);     // Left architectural shadow behind pillar
  px(17, 70, 12, 0, C_PORTICO_SHADOW, 4, 16);    // Right architectural shadow behind pillar
  // Fluted travertine marble column shaft in foreground (x: 4..11)
  rect(17, 70, 4, 0, 8, 16, C_DARK_OUTLINE);
  rect(17, 70, 5, 0, 6, 16, C_TRAVERTINE_IVORY);
  px(17, 70, 5, 0, C_TRAVERTINE_WHITE, 1, 16); // Sunlit flute ridge
  px(17, 70, 6, 0, C_TRAVERTINE_SHADE, 1, 16); // Flute groove shadow
  px(17, 70, 7, 0, C_TRAVERTINE_WHITE, 1, 16);
  px(17, 70, 8, 0, C_TRAVERTINE_SHADE, 1, 16);
  px(17, 70, 9, 0, C_TRAVERTINE_WHITE, 1, 16);
  px(17, 70, 10, 0, C_TRAVERTINE_DEEP, 1, 16);

  // 19. FACADE_ARCH_UPPER_L (tx: 18, ty: 70) [c = 18] - Upper Arch of Centered Grand Entrance Portal (Left)
  rect(18, 70, 0, 0, 16, 16, C_PORTICO_BACKWALL);
  px(18, 70, 0, 0, C_PORTICO_SHADOW, 16, 3);
  // Curved travertine voussoir arch ring (springing from x = 0 to center keystone at x = 15)
  // Inside the arch opening: deep vaulted interior opening (#0f172a, #050811)
  for (let x = 0; x < 16; x++) {
    const archY = Math.round(11 - Math.sqrt(Math.max(0, 14 * 14 - (15 - x) * (15 - x))) * 0.55);
    // Dark vaulted portal interior under arch
    rect(18, 70, x, archY + 3, 1, 16 - (archY + 3), '#0f172a');
    px(18, 70, x, archY + 4, '#050811', 1, 12);
    // Stone arch voussoirs
    rect(18, 70, x, archY, 1, 3, C_TRAVERTINE_IVORY);
    px(18, 70, x, archY, C_DARK_OUTLINE, 1, 1);
    px(18, 70, x, archY + 1, C_TRAVERTINE_WHITE, 1, 1); // Arch highlight
    px(18, 70, x, archY + 2, C_TRAVERTINE_MID, 1, 1);
  }
  // Keystone left half at x: 13..15, y: 1..6
  rect(18, 70, 13, 1, 3, 6, C_DARK_OUTLINE);
  rect(18, 70, 14, 2, 2, 5, C_TRAVERTINE_WHITE);

  // 20. FACADE_ARCH_UPPER_R (tx: 19, ty: 70) [c = 19] - Upper Arch of Centered Grand Entrance Portal (Right)
  rect(19, 70, 0, 0, 16, 16, C_PORTICO_BACKWALL);
  px(19, 70, 0, 0, C_PORTICO_SHADOW, 16, 3);
  // Symmetrical arch voussoir curve
  for (let x = 0; x < 16; x++) {
    const archY = Math.round(11 - Math.sqrt(Math.max(0, 14 * 14 - x * x)) * 0.55);
    rect(19, 70, x, archY + 3, 1, 16 - (archY + 3), '#0f172a');
    px(19, 70, x, archY + 4, '#050811', 1, 12);
    rect(19, 70, x, archY, 1, 3, C_TRAVERTINE_IVORY);
    px(19, 70, x, archY, C_DARK_OUTLINE, 1, 1);
    px(19, 70, x, archY + 1, C_TRAVERTINE_WHITE, 1, 1);
    px(19, 70, x, archY + 2, C_TRAVERTINE_MID, 1, 1);
  }
  // Keystone right half at x: 0..2, y: 1..6
  rect(19, 70, 0, 1, 3, 6, C_DARK_OUTLINE);
  rect(19, 70, 0, 2, 2, 5, C_TRAVERTINE_WHITE);

  // 21. FACADE_PORTICO_BG (tx: 20, ty: 70) - Authentic shaded portico wall behind colonnade (Zero dark brown!)
  rect(20, 70, 0, 0, 16, 16, C_PORTICO_BACKWALL); // Warm aged limestone (#c8bda8)
  px(20, 70, 0, 0, C_PORTICO_SHADOW, 16, 4);     // Subtle architectural shadow at top (#9e927d)
  px(20, 70, 0, 15, C_PORTICO_SHADOW, 16, 1);    // Subtle shadow at bottom
  px(20, 70, 4, 7, '#b8a890', 8, 1);             // Stone ashlar joint line

  // --- ROW 71: CENTERED GRAND ENTRANCE DOORWAY, BASES, FALLEN DRUMS & FORECOURT ---
  // 14. FACADE_ARCH_DOOR_L (tx: 0, ty: 71) [c = 18] - Centered Grand Entrance Door Left Half (Walkable Door Trigger)
  rect(0, 71, 0, 0, 16, 16, '#0f172a'); // Vaulted dark interior opening
  rect(0, 71, 3, 0, 13, 14, '#050811');
  // Left carved travertine arch jamb (x: 0..3)
  rect(0, 71, 0, 0, 4, 16, C_DARK_OUTLINE);
  rect(0, 71, 1, 0, 3, 15, C_TRAVERTINE_IVORY);
  px(0, 71, 1, 0, C_TRAVERTINE_WHITE, 1, 15); // Sunlit marble molding highlight
  px(0, 71, 3, 0, C_TRAVERTINE_DEEP, 1, 15);  // Jamb shadow
  // Smooth antique travertine threshold step at bottom (y: 13..15)
  rect(0, 71, 0, 13, 16, 3, C_DARK_OUTLINE);
  rect(0, 71, 0, 13, 16, 2, C_TRAVERTINE_LIGHT);
  px(0, 71, 0, 13, C_TRAVERTINE_WHITE, 16, 1); // Step nosing highlight

  // 15. FACADE_ARCH_DOOR_R (tx: 1, ty: 71) [c = 19] - Centered Grand Entrance Door Right Half (Walkable Door Trigger)
  rect(1, 71, 0, 0, 16, 16, '#0f172a');
  rect(1, 71, 0, 0, 13, 14, '#050811');
  // Right carved travertine arch jamb (x: 12..15)
  rect(1, 71, 12, 0, 4, 16, C_DARK_OUTLINE);
  rect(1, 71, 12, 0, 3, 15, C_TRAVERTINE_IVORY);
  px(1, 71, 12, 0, C_TRAVERTINE_WHITE, 1, 15);
  px(1, 71, 14, 0, C_TRAVERTINE_DEEP, 1, 15);
  // Smooth antique travertine threshold step at bottom
  rect(1, 71, 0, 13, 16, 3, C_DARK_OUTLINE);
  rect(1, 71, 0, 13, 16, 2, C_TRAVERTINE_LIGHT);
  px(1, 71, 0, 13, C_TRAVERTINE_WHITE, 16, 1);

  // 16. FACADE_BASE_L (tx: 2, ty: 71) [c = 16] - Pillar 1 Base Plinth on clean marble ground
  rect(2, 71, 0, 0, 16, 16, C_TRAVERTINE_LIGHT);
  // Fluted column base (x: 3..12, y: 0..15)
  rect(2, 71, 3, 0, 10, 8, C_DARK_OUTLINE);
  rect(2, 71, 4, 0, 8, 8, C_TRAVERTINE_IVORY);
  px(2, 71, 4, 0, C_TRAVERTINE_WHITE, 1, 8);
  px(2, 71, 6, 0, C_TRAVERTINE_DEEP, 1, 8);
  px(2, 71, 8, 0, C_TRAVERTINE_WHITE, 1, 8);
  px(2, 71, 10, 0, C_TRAVERTINE_DEEP, 1, 8);
  rect(2, 71, 2, 8, 12, 4, C_DARK_OUTLINE);
  rect(2, 71, 3, 8, 10, 3, C_TRAVERTINE_WHITE);
  px(2, 71, 3, 11, C_TRAVERTINE_DEEP, 10, 1);
  rect(2, 71, 1, 12, 14, 4, C_DARK_OUTLINE);
  rect(2, 71, 2, 12, 12, 3, C_TRAVERTINE_IVORY);
  px(2, 71, 1, 11, C_IVY_MID, 3, 4);
  px(2, 71, 0, 13, C_IVY_LIGHT, 2, 3);

