  px(0, 73, 6, 6, C_CYP_LT, 4, 3);
  px(0, 73, 7, 7, C_CYP_HI, 2, 2);
  rect(0, 73, 4, 10, 8, 6, C_DARK_OUTLINE);
  rect(0, 73, 5, 10, 6, 6, C_CYP_MID);
  px(0, 73, 6, 10, C_CYP_LT, 4, 5);
  px(0, 73, 7, 11, C_CYP_HI, 2, 3);
  px(0, 73, 4, 12, C_CYP_DK, 1, 4); // Left shadow edge
  px(0, 73, 11, 12, C_CYP_DK, 1, 4);

  // 36. TREE_CYPRESS_BASE (tx: 1, ty: 73) - Tuscan Cypress columnar base & gnarled trunk
  rect(1, 73, 0, 0, 16, 16, 'transparent');
  // Columnar lower foliage continuing seamlessly
  rect(1, 73, 4, 0, 8, 8, C_DARK_OUTLINE);
  rect(1, 73, 5, 0, 6, 7, C_CYP_MID);
  px(1, 73, 6, 0, C_CYP_LT, 4, 6);
  px(1, 73, 7, 1, C_CYP_HI, 2, 4);
  px(1, 73, 4, 2, C_CYP_DK, 1, 5);
  px(1, 73, 11, 2, C_CYP_DK, 1, 5);
  // Slender gnarled cypress trunk base
  rect(1, 73, 6, 7, 4, 9, C_DARK_OUTLINE);
  rect(1, 73, 7, 7, 2, 8, '#542c16'); // Aged cedar trunk
  px(1, 73, 7, 8, '#783e20', 1, 6);   // Trunk highlight
  px(1, 73, 5, 14, C_DARK_OUTLINE, 2, 2); // Left root flare
  px(1, 73, 5, 14, '#542c16', 1, 1);
  px(1, 73, 9, 14, C_DARK_OUTLINE, 2, 2); // Right root flare
  px(1, 73, 10, 14, '#542c16', 1, 1);
  // Tiny green grass/moss tuft at root base
  px(1, 73, 4, 15, C_CYP_LT, 2, 1);
  px(1, 73, 10, 15, C_CYP_LT, 2, 1);

  // 37. TREE_OAK_AMBER_TOP (tx: 2, ty: 73) - Spreading Amber Oak canopy
  rect(2, 73, 0, 0, 16, 16, 'transparent');
  // Organic rounded billowing foliage lobes (x: 1..14, y: 1..15)
  rect(2, 73, 1, 2, 14, 14, C_DARK_OUTLINE);
  rect(2, 73, 2, 3, 12, 12, '#9a3412'); // Deep amber shadow
  rect(2, 73, 3, 3, 10, 10, '#c2410c'); // Warm amber mid
  rect(2, 73, 3, 2, 10, 8, '#d97706');  // Golden amber foliage
  // Luminous sunlit leaf cluster highlights
  px(2, 73, 5, 2, '#f59e0b', 6, 3);
  px(2, 73, 6, 1, '#fde047', 4, 1); // Crown sun glint
  px(2, 73, 3, 5, '#f59e0b', 4, 3); // Left foliage lobe
  px(2, 73, 9, 5, '#f59e0b', 4, 3); // Right foliage lobe
  px(2, 73, 6, 7, '#fde047', 4, 2); // Center lobe highlight
  rect(2, 73, 2, 12, 12, 4, '#9a3412'); // Underside foliage drape

  // 38. TREE_OAK_AMBER_BASE (tx: 3, ty: 73) - Spreading Amber Oak lower canopy & gnarled trunk
  rect(3, 73, 0, 0, 16, 16, 'transparent');
  rect(3, 73, 2, 0, 12, 4, C_DARK_OUTLINE);
  rect(3, 73, 3, 0, 10, 3, '#9a3412');
  px(3, 73, 4, 1, '#d97706', 8, 2);
  // Twisting gnarled oak branches supporting canopy
  px(3, 73, 4, 3, '#542c16', 3, 2);
  px(3, 73, 9, 3, '#542c16', 3, 2);
  // Sturdy twisting oak trunk (x: 5..10, y: 3..15)
  rect(3, 73, 5, 3, 6, 13, C_DARK_OUTLINE);
  rect(3, 73, 6, 3, 4, 12, '#542c16'); // Dark weathered oak bark
  px(3, 73, 6, 4, '#8a5830', 2, 10);  // Bark ridge highlight
  px(3, 73, 8, 6, '#381c08', 2, 7);   // Bark crevice shadow
  // Spreading root flares gripping ground
  rect(3, 73, 3, 12, 3, 4, C_DARK_OUTLINE);
  rect(3, 73, 4, 13, 2, 3, '#542c16');
  rect(3, 73, 10, 12, 3, 4, C_DARK_OUTLINE);
  rect(3, 73, 10, 13, 2, 3, '#542c16');

  // 39. TREE_OAK_GOLD_TOP (tx: 4, ty: 73) - Spreading Golden Oak canopy
  rect(4, 73, 0, 0, 16, 16, 'transparent');
  rect(4, 73, 1, 2, 14, 14, C_DARK_OUTLINE);
  rect(4, 73, 2, 3, 12, 12, '#b45309');
  rect(4, 73, 3, 3, 10, 10, '#d97706');
  rect(4, 73, 3, 2, 10, 8, '#eab308'); // Vibrant yellow-gold
  px(4, 73, 5, 2, '#fde047', 6, 3);
  px(4, 73, 6, 1, '#ffffff', 4, 1);
  px(4, 73, 3, 5, '#fde047', 4, 3);
  px(4, 73, 9, 5, '#fde047', 4, 3);
  rect(4, 73, 2, 12, 12, 4, '#b45309');

  // 40. TREE_OAK_GOLD_BASE (tx: 5, ty: 73) - Golden Oak trunk
  rect(5, 73, 0, 0, 16, 16, 'transparent');
  rect(5, 73, 2, 0, 12, 4, C_DARK_OUTLINE);
  rect(5, 73, 3, 0, 10, 3, '#b45309');
  px(5, 73, 4, 1, '#eab308', 8, 2);
  rect(5, 73, 5, 3, 6, 13, C_DARK_OUTLINE);
  rect(5, 73, 6, 3, 4, 12, '#542c16');
  px(5, 73, 6, 4, '#8a5830', 2, 10);
  rect(5, 73, 3, 12, 3, 4, C_DARK_OUTLINE);
  rect(5, 73, 4, 13, 2, 3, '#542c16');
  rect(5, 73, 10, 12, 3, 4, C_DARK_OUTLINE);
  rect(5, 73, 10, 13, 2, 3, '#542c16');

  // 41. TREE_OAK_RUSSET_TOP (tx: 6, ty: 73) - Spreading Russet/Crimson Oak canopy
  rect(6, 73, 0, 0, 16, 16, 'transparent');
  rect(6, 73, 1, 2, 14, 14, C_DARK_OUTLINE);
  rect(6, 73, 2, 3, 12, 12, '#7f1d1d');
  rect(6, 73, 3, 3, 10, 10, '#991b1b');
  rect(6, 73, 3, 2, 10, 8, '#dc2626'); // Rich scarlet red
  px(6, 73, 5, 2, '#ef4444', 6, 3);
  px(6, 73, 6, 1, '#f87171', 4, 1);
  px(6, 73, 3, 5, '#ef4444', 4, 3);
  px(6, 73, 9, 5, '#ef4444', 4, 3);
  rect(6, 73, 2, 12, 12, 4, '#7f1d1d');

  // 42. TREE_OAK_RUSSET_BASE (tx: 7, ty: 73) - Russet Oak trunk
  rect(7, 73, 0, 0, 16, 16, 'transparent');
  rect(7, 73, 2, 0, 12, 4, C_DARK_OUTLINE);
  rect(7, 73, 3, 0, 10, 3, '#7f1d1d');
  px(7, 73, 4, 1, '#dc2626', 8, 2);
  rect(7, 73, 5, 3, 6, 13, C_DARK_OUTLINE);
  rect(7, 73, 6, 3, 4, 12, '#542c16');
  px(7, 73, 6, 4, '#8a5830', 2, 10);
  rect(7, 73, 3, 12, 3, 4, C_DARK_OUTLINE);
  rect(7, 73, 4, 13, 2, 3, '#542c16');
  rect(7, 73, 10, 12, 3, 4, C_DARK_OUTLINE);
  rect(7, 73, 10, 13, 2, 3, '#542c16');

  // ==========================================================================
  // ROW 74: SCREEN 4 - VERMILION TORII SHRINE PAVILION & SCRIPTORIUM (OPTION 2)
  // Palette:
  // Vermilion / Lacquered Cinnabar Red: #d92c14, #f04830, #ff6b54, #b31c07, #821002
  // Charcoal Black Ridge Tiles (Kawara): #181414, #27272a, #3f3f46, #52525b
  // Polished Dark Cypress / Lacquered Deck: #26140b, #381f14, #4a2818, #5c3422, #1a0d07
  // Gold / Brass Fittings (Kanagu): #fbbf24, #fde68a, #d97706
  // Autumn Maple Leaves (Momiji): #dc2626, #ef4444, #f97316, #fbbf24
  // Sumi Ink & Rice Paper: #fffdf0, #09090b, #18181b, #ca8a04
  // ==========================================================================
  const C_VERM_BASE = '#d92c14';
  const C_VERM_HI = '#f04830';
  const C_VERM_LIGHT = '#ff6b54';
  const C_VERM_SH = '#b31c07';
  const C_VERM_DK = '#821002';
  const C_KAW_DK = '#181414';
  const C_KAW_MID = '#27272a';
  const C_KAW_LT = '#3f3f46';
  const C_KAW_HI = '#52525b';
  const C_DEC_DK = '#26140b';
  const C_DEC_MID = '#381f14';
  const C_DEC_LT = '#4a2818';
  const C_DEC_HI = '#5c3422';
  const C_DEC_SEAM = '#1a0d07';
  const C_GOLD_BRASS = '#fbbf24';
  const C_GOLD_HI = '#fde68a';
  const C_GOLD_SH = '#d97706';

  // 1. TORII_TOP_L (tx: 0, ty: 74) - Left Sweeping Upturned Torii Lintel with Black Ridge & Gold Fitting
  rect(0, 74, 0, 0, 16, 16, 'transparent');
  // Sweeping black charcoal ridge tile cap (sori upward curve at x: 0..4)
  rect(0, 74, 0, 4, 3, 4, C_DARK_OUTLINE);
  rect(0, 74, 0, 4, 3, 3, C_KAW_DK);
  px(0, 74, 0, 3, C_KAW_HI, 2, 1); // Upturned wingtip peak
  rect(0, 74, 3, 6, 13, 3, C_DARK_OUTLINE);
  rect(0, 74, 3, 6, 13, 2, C_KAW_DK);
  px(0, 74, 3, 6, C_KAW_LT, 13, 1);
  // Vermilion lintel beam (kasagi & shimaki)
  rect(0, 74, 0, 8, 16, 6, C_DARK_OUTLINE);
  rect(0, 74, 1, 9, 15, 4, C_VERM_BASE);
  px(0, 74, 1, 9, C_VERM_HI, 15, 1);
  px(0, 74, 1, 12, C_VERM_SH, 15, 1);
  // Gold corner metal sleeve (kanagu) at corner
  rect(0, 74, 0, 8, 3, 5, C_GOLD_BRASS);
  px(0, 74, 1, 9, C_GOLD_HI, 2, 2);
  px(0, 74, 0, 12, C_GOLD_SH, 3, 1);
  // Lower tie-beam mortise socket shadow
  px(0, 74, 8, 14, C_VERM_DK, 8, 2);

  // 2. TORII_TOP_M (tx: 1, ty: 74) - Center Torii Lintel with Black Lacquer Tablet Plaque (Gakuzuka) & Tie-Beam
  rect(1, 74, 0, 0, 16, 16, 'transparent');
  // Charcoal black curved ridge tile
  rect(1, 74, 0, 6, 16, 3, C_DARK_OUTLINE);
  rect(1, 74, 0, 6, 16, 2, C_KAW_DK);
  px(1, 74, 0, 6, C_KAW_LT, 16, 1);
  // Vermilion upper crossbeam (kasagi)
  rect(1, 74, 0, 8, 16, 5, C_DARK_OUTLINE);
  rect(1, 74, 0, 9, 16, 3, C_VERM_BASE);
  px(1, 74, 0, 9, C_VERM_HI, 16, 1);
  px(1, 74, 0, 11, C_VERM_SH, 16, 1);
  // Central Shinto shrine tablet plaque (gakuzuka) in black lacquer with gold border
  rect(1, 74, 6, 8, 4, 8, C_DARK_OUTLINE);
  rect(1, 74, 6, 8, 4, 8, C_KAW_DK); // Black lacquer plaque
  rect(1, 74, 6, 8, 4, 1, C_GOLD_BRASS); // Gold top border
  rect(1, 74, 6, 15, 4, 1, C_GOLD_BRASS); // Gold bottom border
  px(1, 74, 6, 8, C_GOLD_BRASS, 1, 8);
  px(1, 74, 9, 8, C_GOLD_BRASS, 1, 8);
  // Gold inscribed kanji character motif in center
  px(1, 74, 7, 10, C_GOLD_HI, 2, 1);
  px(1, 74, 7, 12, C_GOLD_HI, 2, 2);
  // Lower horizontal tie-beam (nuki) spanning beneath
  rect(1, 74, 0, 14, 6, 2, C_VERM_BASE);
  px(1, 74, 0, 14, C_VERM_HI, 6, 1);
  rect(1, 74, 10, 14, 6, 2, C_VERM_BASE);
  px(1, 74, 10, 14, C_VERM_HI, 6, 1);

  // 3. TORII_TOP_R (tx: 2, ty: 74) - Right Sweeping Upturned Torii Lintel with Gold Corner Fitting
  rect(2, 74, 0, 0, 16, 16, 'transparent');
  rect(2, 74, 13, 4, 3, 4, C_DARK_OUTLINE);
  rect(2, 74, 13, 4, 3, 3, C_KAW_DK);
  px(2, 74, 14, 3, C_KAW_HI, 2, 1); // Upturned wingtip peak right
  rect(2, 74, 0, 6, 13, 3, C_DARK_OUTLINE);
  rect(2, 74, 0, 6, 13, 2, C_KAW_DK);
  px(2, 74, 0, 6, C_KAW_LT, 13, 1);
  rect(2, 74, 0, 8, 16, 6, C_DARK_OUTLINE);
  rect(2, 74, 0, 9, 15, 4, C_VERM_BASE);
  px(2, 74, 0, 9, C_VERM_HI, 15, 1);
  px(2, 74, 0, 12, C_VERM_SH, 15, 1);
  // Gold corner sleeve
  rect(2, 74, 13, 8, 3, 5, C_GOLD_BRASS);
  px(2, 74, 13, 9, C_GOLD_HI, 2, 2);
  px(2, 74, 13, 12, C_GOLD_SH, 3, 1);
  px(2, 74, 0, 14, C_VERM_DK, 8, 2);

  // 4. TORII_POST_L (tx: 3, ty: 74) - Tall Vermilion Pillar (Left) with Tie-Beam & Black Stone Base
  rect(3, 74, 0, 0, 16, 16, 'transparent');
  // Cylindrical vermilion pillar (x: 5..10, y: 0..14)
  rect(3, 74, 5, 0, 6, 14, C_DARK_OUTLINE);
  rect(3, 74, 6, 0, 4, 13, C_VERM_BASE);
  px(3, 74, 6, 0, C_VERM_HI, 1, 13); // Pillar sunlit luster
  px(3, 74, 9, 0, C_VERM_DK, 1, 13); // Pillar cylindrical shadow
  // Horizontal tie-beam (nuki) mortised into right side with gold wedge (kusabi)
  rect(3, 74, 10, 2, 6, 4, C_DARK_OUTLINE);
  rect(3, 74, 10, 3, 6, 2, C_VERM_BASE);
  px(3, 74, 10, 3, C_VERM_HI, 6, 1);
  rect(3, 74, 9, 2, 2, 4, C_GOLD_BRASS); // Gold wedge fitting
  px(3, 74, 9, 3, C_GOLD_HI, 1, 2);
  // Lower gold ring sleeve (kanagu) at pillar base
  rect(3, 74, 5, 12, 6, 2, C_GOLD_BRASS);
  px(3, 74, 6, 12, C_GOLD_HI, 4, 1);
  // Round black lacquer/stone foundation plinth (kamebara)
  rect(3, 74, 4, 13, 8, 3, C_DARK_OUTLINE);
  rect(3, 74, 5, 14, 6, 2, C_KAW_DK);
  px(3, 74, 5, 13, C_KAW_LT, 6, 1);
  // Fallen red autumn maple leaf at base
  px(3, 74, 11, 13, '#dc2626', 3, 2);
  px(3, 74, 12, 12, '#ef4444', 2, 1);

  // 5. TORII_POST_R (tx: 4, ty: 74) - Tall Vermilion Pillar (Right) with Tie-Beam & Black Stone Base
  rect(4, 74, 0, 0, 16, 16, 'transparent');
  rect(4, 74, 5, 0, 6, 14, C_DARK_OUTLINE);
  rect(4, 74, 6, 0, 4, 13, C_VERM_BASE);
  px(4, 74, 6, 0, C_VERM_HI, 1, 13);
  px(4, 74, 9, 0, C_VERM_DK, 1, 13);
  // Tie-beam mortised into left side
  rect(4, 74, 0, 2, 6, 4, C_DARK_OUTLINE);
  rect(4, 74, 0, 3, 6, 2, C_VERM_BASE);
  px(4, 74, 0, 3, C_VERM_HI, 6, 1);
  rect(4, 74, 5, 2, 2, 4, C_GOLD_BRASS);
  px(4, 74, 5, 3, C_GOLD_HI, 1, 2);
  // Gold sleeve
  rect(4, 74, 5, 12, 6, 2, C_GOLD_BRASS);
  px(4, 74, 6, 12, C_GOLD_HI, 4, 1);
  // Base plinth
  rect(4, 74, 4, 13, 8, 3, C_DARK_OUTLINE);
  rect(4, 74, 5, 14, 6, 2, C_KAW_DK);
  px(4, 74, 5, 13, C_KAW_LT, 6, 1);
  // Fallen orange maple leaf at base
  px(4, 74, 2, 13, '#ea580c', 3, 2);
  px(4, 74, 3, 12, '#f97316', 2, 1);

  // 6. SHRINE_ROOF_L (tx: 5, ty: 74) - Sweeping Japanese Roof Left Hip with Black Ridge Tiles & Vermilion Fascia
  rect(5, 74, 0, 0, 16, 16, 'transparent');
  // Sweeping corner hip tile (onigawara) sweeping up at x: 0..4, y: 1..5
  rect(5, 74, 0, 1, 4, 5, C_DARK_OUTLINE);
  rect(5, 74, 0, 2, 3, 4, C_KAW_DK);
  px(5, 74, 0, 1, C_KAW_HI, 2, 2); // Upturned hip peak
  // Charcoal black roof tile slope
  for (let x = 3; x < 16; x++) {
    const topY = Math.round(5 - (x - 3) * 0.25);
    rect(5, 74, x, topY, 1, 10 - topY, C_KAW_DK);
    px(5, 74, x, topY, C_DARK_OUTLINE, 1, 1);
    px(5, 74, x, topY + 1, C_KAW_LT, 1, 1);
    // Overlapping tile rows
    if ((topY + x) % 3 === 0) px(5, 74, x, topY + 2, C_KAW_HI, 1, 1);
  }
  // Striking lacquered vermilion-red eave fascia (hafu) along bottom (y: 10..13)
  rect(5, 74, 0, 10, 16, 4, C_DARK_OUTLINE);
  rect(5, 74, 0, 10, 16, 3, C_VERM_BASE);
  px(5, 74, 0, 10, C_VERM_HI, 16, 1);
  px(5, 74, 0, 12, C_VERM_SH, 16, 1);
  // Gold ornamental pendant metalwork (kegyo) at eave tip
  rect(5, 74, 1, 11, 4, 4, C_DARK_OUTLINE);
  rect(5, 74, 2, 11, 2, 3, C_GOLD_BRASS);
  px(5, 74, 2, 12, C_GOLD_HI, 2, 1);
  // Exposed painted vermilion rafter tips (taruki)
  for (let tx = 2; tx < 16; tx += 4) {
    px(5, 74, tx, 14, C_VERM_HI, 2, 1);
    px(5, 74, tx, 15, C_VERM_DK, 2, 1);
  }

  // 7. SHRINE_ROOF_M (tx: 6, ty: 74) - Center Sweeping Roof with Charcoal Ridge Tiles & Vermilion Eaves
  rect(6, 74, 0, 0, 16, 16, 'transparent');
  // Charcoal black main ridge tiles (mune-gawara) along top (y: 1..4)
  rect(6, 74, 0, 1, 16, 3, C_DARK_OUTLINE);
  rect(6, 74, 0, 2, 16, 2, C_KAW_DK);
  px(6, 74, 0, 1, C_KAW_HI, 16, 1);
  // Dark cascading roof tile surface (y: 4..10)
  for (let y = 4; y <= 9; y++) {
    rect(6, 74, 0, y, 16, 1, y % 2 === 0 ? C_KAW_MID : C_KAW_DK);
    for (let x = (y % 3); x < 16; x += 4) {
      px(6, 74, x, y, C_KAW_LT, 2, 1); // Tile bevel highlight
    }
  }
  // Vermilion eave fascia
  rect(6, 74, 0, 10, 16, 4, C_DARK_OUTLINE);
  rect(6, 74, 0, 10, 16, 3, C_VERM_BASE);
  px(6, 74, 0, 10, C_VERM_HI, 16, 1);
  px(6, 74, 0, 12, C_VERM_SH, 16, 1);
  // Gold central crest medallion
  rect(6, 74, 7, 10, 2, 3, C_GOLD_BRASS);
  px(6, 74, 7, 11, C_GOLD_HI, 2, 1);
  // Rafter tips
  for (let tx = 1; tx < 16; tx += 4) {
    px(6, 74, tx, 14, C_VERM_HI, 2, 1);
    px(6, 74, tx, 15, C_VERM_DK, 2, 1);
  }

  // 8. SHRINE_ROOF_R (tx: 7, ty: 74) - Sweeping Japanese Roof Right Hip with Gold Ornamentation
  rect(7, 74, 0, 0, 16, 16, 'transparent');
  rect(7, 74, 12, 1, 4, 5, C_DARK_OUTLINE);
  rect(7, 74, 13, 2, 3, 4, C_KAW_DK);
  px(7, 74, 14, 1, C_KAW_HI, 2, 2); // Upturned hip peak right
  for (let x = 0; x < 13; x++) {
    const topY = Math.round(2 + x * 0.25);
    rect(7, 74, x, topY, 1, 10 - topY, C_KAW_DK);
    px(7, 74, x, topY, C_DARK_OUTLINE, 1, 1);
    px(7, 74, x, topY + 1, C_KAW_LT, 1, 1);
    if ((topY + x) % 3 === 0) px(7, 74, x, topY + 2, C_KAW_HI, 1, 1);
  }
  rect(7, 74, 0, 10, 16, 4, C_DARK_OUTLINE);
  rect(7, 74, 0, 10, 16, 3, C_VERM_BASE);
  px(7, 74, 0, 10, C_VERM_HI, 16, 1);
  px(7, 74, 0, 12, C_VERM_SH, 16, 1);
  // Gold pendant fitting right
  rect(7, 74, 11, 11, 4, 4, C_DARK_OUTLINE);
  rect(7, 74, 12, 11, 2, 3, C_GOLD_BRASS);
  px(7, 74, 12, 12, C_GOLD_HI, 2, 1);
  for (let tx = 1; tx < 16; tx += 4) {
    px(7, 74, tx, 14, C_VERM_HI, 2, 1);
    px(7, 74, tx, 15, C_VERM_DK, 2, 1);
  }

  // 9. SHRINE_EAVE (tx: 8, ty: 74) - Vermilion Bracket Set (Doukyou) & Rafters with Gold Fittings Under Eave (Transparent background)
  rect(8, 74, 0, 0, 16, 16, 'transparent'); // Transparent so pillars and deck connect continuously underneath
  // Complex carved vermilion bracket clusters
  rect(8, 74, 0, 0, 16, 3, C_VERM_SH);
  px(8, 74, 0, 0, C_VERM_HI, 16, 1);
  // Step-projecting bracket arms (doukyou)
  for (let bx = 1; bx < 16; bx += 5) {
    rect(8, 74, bx, 3, 4, 3, C_VERM_BASE);
    px(8, 74, bx, 3, C_VERM_HI, 4, 1);
    rect(8, 74, bx + 1, 6, 2, 4, C_VERM_BASE);
    // Gold corner plate fitting (kanagu)
    px(8, 74, bx + 1, 5, C_GOLD_BRASS, 2, 1);
  }
  // Horizontal vermilion lintel tie-beam
  rect(8, 74, 0, 10, 16, 4, C_DARK_OUTLINE);
  rect(8, 74, 0, 11, 16, 3, C_VERM_BASE);
  px(8, 74, 0, 11, C_VERM_HI, 16, 1);
  px(8, 74, 0, 13, C_VERM_DK, 16, 1);
  // Delicate hanging brass bell / wind chime (fuurin) on left
  px(8, 74, 3, 14, C_GOLD_BRASS, 2, 2);
  px(8, 74, 4, 15, '#fef08a', 1, 1);

  // 10. SHRINE_POST_VERMILION (tx: 9, ty: 74) - Graceful Vermilion Pillar with Gold Sleeve Fittings & Maple Leaf
  rect(9, 74, 0, 0, 16, 16, 'transparent');
  // Cylindrical vermilion wooden pillar (x: 5..10, y: 0..14)
  rect(9, 74, 5, 0, 6, 15, C_DARK_OUTLINE);
  rect(9, 74, 6, 0, 4, 14, C_VERM_BASE);
  px(9, 74, 6, 0, C_VERM_HI, 1, 14); // Polished cinnabar luster
  px(9, 74, 9, 0, C_VERM_DK, 1, 14); // Shadow edge
  // Top brass/gold sleeve collar (kanagu) at y: 0..2
  rect(9, 74, 5, 0, 6, 3, C_GOLD_BRASS);
