  // 23. POND_STONE_RIM (tx: 22, ty: 74) - Rounded River-Stone Rim encircling Lotus & Koi Pond
  rect(22, 74, 0, 0, 16, 16, C_OCHRE_BASE); // Ground verge
  rect(22, 74, 2, 2, 12, 12, '#0369a1');   // Water inside rim
  px(22, 74, 4, 4, '#38bdf8', 8, 1);
  // Soft, muted river cobbles around bank edge (harmonious earth & slate tones, no black outlines)
  for (let a = 0; a < 6; a++) {
    const angle = (a / 6) * Math.PI * 2;
    const rx = Math.round(8 + Math.cos(angle) * 6);
    const ry = Math.round(8 + Math.sin(angle) * 6);
    rect(22, 74, rx - 1, ry - 1, 3, 3, '#5c5144'); // Soft earthy shadow
    rect(22, 74, rx - 1, ry - 1, 2, 2, (a % 2 === 0) ? '#7c6e5e' : '#6e6153');
    px(22, 74, rx, ry - 1, '#8e7f6e', 1, 1); // Subtle muted slate highlight
  }

