  const C_LAUREL_MID = '#15803d';

  // 1. RUINS_STATUE_TL (tx: 0, ty: 76) - Top-Left: Head left, laurel crown, draped shoulder & sculpted stone lyre
  rect(0, 76, 0, 0, 16, 16, 'transparent');
