  px(0, 76, 14, 7, C_ST_WHITE, 2, 1);
  px(0, 76, 13, 8, C_ST_IVORY, 3, 2);
  px(0, 76, 10, 15, C_ST_WHITE, 3, 1);
  px(0, 76, 12, 11, C_ST_SH, 1, 5);
  px(0, 76, 13, 10, C_ST_WHITE, 2, 6);
  px(0, 76, 15, 11, C_ST_LINE, 1, 5);

  // Sculpted Stone Lyre held in her left arm (x: 6..12, y: 6..15)
  rect(0, 76, 6, 6, 7, 9, C_DARK_OUTLINE);
  rect(0, 76, 6, 6, 7, 2, C_ST_IVORY); // Crossbar yoke
