  px(0, 76, 7, 5, C_ST_WHITE, 1, 1);  // Tuning peg 1
  px(0, 76, 9, 5, C_ST_WHITE, 1, 1);  // Tuning peg 2
  px(0, 76, 11, 5, C_ST_WHITE, 1, 1); // Tuning peg 3
