  px(0, 76, 6, 7, C_ST_WHITE, 1, 5);
  px(0, 76, 7, 7, C_ST_SH, 1, 5);
  rect(0, 76, 11, 7, 2, 5, C_ST_IVORY);
  px(0, 76, 11, 7, C_ST_SH, 1, 5);
  px(0, 76, 12, 7, C_ST_WHITE, 1, 5);
