  px(1, 76, 4, 12, C_ST_WHITE, 2, 1); // Hand holding mantle

  // 3. RUINS_STATUE_BL (tx: 2, ty: 76) - Bottom-Left: Flowing robes pooling, plinth cornice, panel, step, moss & red leaves
  rect(2, 76, 0, 0, 16, 16, 'transparent');
