  rect(11, 91, 4, 9, 8, 1, '#e8892b');
  rect(11, 91, 4, 13, 8, 1, '#c96f1a');
  px(11, 91, 5, 9, '#3b2410', 1, 3); // Stripes
  px(11, 91, 7, 9, '#3b2410', 1, 4);
  px(11, 91, 9, 9, '#3b2410', 1, 3);
  rect(11, 91, 10, 8, 4, 4, C_DARK_OUTLINE); // Head
