  px(15, 91, 2, 11, '#7c9a8a', 4, 1); // Leaves
  px(15, 91, 10, 11, '#7c9a8a', 4, 1);
  px(15, 91, 3, 12, '#5f7f70', 3, 1);
  px(15, 91, 10, 12, '#5f7f70', 3, 1);
  px(15, 91, 4, 13, '#7c9a8a', 8, 1);
  rect(15, 91, 5, 3, 6, 6, '#3f6212'); // Globe
