  px(15, 91, 7, 6, '#65a30d', 2, 1);
  px(15, 91, 5, 7, '#65a30d', 1, 1);
  px(15, 91, 10, 7, '#65a30d', 1, 1);
  px(15, 91, 7, 2, '#7e22ce', 2, 1); // Purple tip

