// ============================================================================
// 16x24 CHIBI SPRITESHEET (PLAYER & ALL POETS / TOWNSFOLK)
// ============================================================================
let activePlayerCustom: PlayerCustomization = { ...DEFAULT_PLAYER_CUSTOMIZATION };
let playerHasLaurel = false;

export function setHarborPlayerCustomization(custom: PlayerCustomization, hasLaurel = false) {
  activePlayerCustom = { ...custom };
  playerHasLaurel = hasLaurel;
  cachedCharSpritesheetCanvas = null;
}

export function setHarborPlayerHasLaurel(hasLaurel: boolean) {
  if (playerHasLaurel !== hasLaurel) {
    playerHasLaurel = hasLaurel;
    cachedCharSpritesheetCanvas = null;
    cachedSummitScreenData = null;
  }
}

export function getHarborPlayerCustomization(): PlayerCustomization {
  return activePlayerCustom;
}

export function getHarborPlayerHasLaurel(): boolean {
  return playerHasLaurel;
}

let cachedCharSpritesheetCanvas: HTMLCanvasElement | null = null;

export function getHarborCharSpritesheetCanvas(): HTMLCanvasElement {
  if (cachedCharSpritesheetCanvas) return cachedCharSpritesheetCanvas;
  cachedCharSpritesheetCanvas = createHarborCharSpritesheetCanvas();
  return cachedCharSpritesheetCanvas;
}

