    // Tousled natural brown hair
    p(1, 0 + bobY, OUT, 14, 5);
    p(2, 1 + bobY, '#451a03', 12, 4);
    p(3, 0 + bobY, '#542c16', 10, 2);
    p(2, 2 + bobY, '#542c16', 2, 3);
