export const ROOM_HARBOR = CANTO_I;

export function drawGivingTreeStump(
  ctx: CanvasRenderingContext2D,
  worldX: number,
  worldY: number,
  camX: number,
  camY: number,
) {
  const sx = Math.round(worldX - camX);
  const sy = Math.round(worldY - camY);
  const tileset = getHarborTilesetCanvas();
  const rect = getHarborTileSourceRect(HARBOR_TILES.GIVING_TREE_STUMP);
  ctx.drawImage(tileset, rect.sx, rect.sy, 16, 16, sx, sy, 16, 16);
}

// ============================================================================
// 1. BOARDWALK-TO-PATH TIMBER SILL & STEPPING STONES
// Where the pier and path meet at X: 9..12, Y: 20..21 across the sand.
// ============================================================================
export function drawTimberSillAndSteppingStones(
  ctx: CanvasRenderingContext2D,
  camX: number,
  camY: number,
) {
  const startX = Math.round(9 * TILE_SIZE - camX);
  const endX = Math.round(13 * TILE_SIZE - camX);
  const sillY = Math.round(21 * TILE_SIZE - 2 - camY);

  if (endX < -40 || startX > VIEWPORT_WIDTH + 40 || sillY < -40 || sillY > VIEWPORT_HEIGHT + 40) return;

  ctx.save();
  ctx.imageSmoothingEnabled = false;

  // Barrier wall removed: Stepping stones across the sand lead smoothly and cleanly from the dirt path onto the pier deck
  const stones = [
    { x: 9.6 * TILE_SIZE, y: 20.2 * TILE_SIZE, w: 9, h: 5 },
    { x: 10.8 * TILE_SIZE, y: 19.8 * TILE_SIZE, w: 10, h: 6 },
    { x: 11.2 * TILE_SIZE, y: 20.3 * TILE_SIZE, w: 8, h: 5 },
    { x: 10.2 * TILE_SIZE, y: 19.2 * TILE_SIZE, w: 11, h: 6 },
    { x: 11.8 * TILE_SIZE, y: 19.4 * TILE_SIZE, w: 9, h: 5 },
  ];

  stones.forEach((st) => {
    const sx = Math.round(st.x - camX);
    const sy = Math.round(st.y - camY);

    ctx.fillStyle = 'rgba(40, 25, 15, 0.28)';
    ctx.beginPath();
    ctx.ellipse(sx + st.w / 2, sy + st.h - 1, st.w / 2 + 1, 2, 0, 0, Math.PI * 2);
    ctx.fill();

    ctx.fillStyle = '#334155';
    ctx.beginPath();
    ctx.ellipse(sx + st.w / 2, sy + st.h / 2, st.w / 2, st.h / 2, 0, 0, Math.PI * 2);
    ctx.fill();

    ctx.fillStyle = '#64748B';
    ctx.beginPath();
    ctx.ellipse(sx + st.w / 2, sy + st.h / 2 - 0.5, st.w / 2 - 0.5, st.h / 2 - 0.5, 0, 0, Math.PI * 2);
    ctx.fill();

    ctx.fillStyle = '#94A3B8';
    ctx.beginPath();
    ctx.ellipse(sx + st.w / 2 - 0.5, sy + st.h / 2 - 1, st.w / 2 - 1.5, Math.max(1, st.h / 4), 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = '#CBD5E1';
    ctx.fillRect(sx + Math.round(st.w / 2) - 1, sy + 1, 2, 1);
  });

  ctx.restore();
}

// ============================================================================
// 2. UPGRADED 16-BIT COASTAL TREES (REPLACING RECTANGULAR LOLLIPOP TREES)
// Multi-tiered rounded canopy using layered circles/pixels:
//   dark shadow #3B6828, midtone #4E8A34, highlight #68AC48.
// Sturdy wooden trunk (#5A3B1C) with soft root flare and 1px bark texture.
// ============================================================================
export function drawLushCoastalTree(
  ctx: CanvasRenderingContext2D,
  worldX: number,
  worldY: number,
  camX: number,
  camY: number,
  scale = 1.0,
) {
  const sx = Math.round(worldX - camX);
  const sy = Math.round(worldY - camY);

  if (sx < -48 || sx > VIEWPORT_WIDTH + 48 || sy < -64 || sy > VIEWPORT_HEIGHT + 48) return;

  ctx.save();
  ctx.imageSmoothingEnabled = false;

  const trunkW = Math.round(6 * scale);
  const trunkH = Math.round(18 * scale);
  const trunkX = sx - Math.round(trunkW / 2);
  const trunkY = sy - trunkH;

  // 1. Soft ground contact shadow
  ctx.fillStyle = 'rgba(25, 45, 20, 0.28)';
  ctx.beginPath();
  ctx.ellipse(sx, sy + 1, Math.round(14 * scale), Math.round(5 * scale), 0, 0, Math.PI * 2);
  ctx.fill();

  // 2. Sturdy wooden trunk (#5A3B1C) with soft root flare and 1px bark texture
  ctx.fillStyle = '#5A3B1C';
  ctx.beginPath();
  ctx.moveTo(trunkX - Math.round(4 * scale), sy);
  ctx.lineTo(trunkX, sy - Math.round(6 * scale));
  ctx.lineTo(trunkX + trunkW, sy - Math.round(6 * scale));
  ctx.lineTo(trunkX + trunkW + Math.round(4 * scale), sy);
  ctx.closePath();
  ctx.fill();

  ctx.fillRect(trunkX, trunkY, trunkW, trunkH);

  ctx.fillStyle = '#3E2612';
  ctx.fillRect(trunkX - Math.round(4 * scale), sy - 1, Math.round(trunkW + 8 * scale), 2);

  ctx.fillStyle = '#785028';
  ctx.fillRect(trunkX + 1, trunkY + 2, 1, trunkH - 4);
  ctx.fillStyle = '#8C6032';
  ctx.fillRect(trunkX + 2, trunkY + 4, 1, trunkH - 8);
  ctx.fillStyle = '#3E2612';
  ctx.fillRect(trunkX + trunkW - 2, trunkY + 3, 1, trunkH - 5);

  // 3. Multi-tiered rounded canopy
  const canopyBaseY = trunkY - Math.round(4 * scale);

  const drawFoliageCluster = (cx: number, cy: number, r: number) => {
    ctx.fillStyle = '#3B6828';
    ctx.beginPath();
    ctx.arc(cx, cy + Math.round(2 * scale), r, 0, Math.PI * 2);
    ctx.fill();

    ctx.fillStyle = '#4E8A34';
    ctx.beginPath();
    ctx.arc(cx, cy, Math.max(1, r - 1.5), 0, Math.PI * 2);
    ctx.fill();

    ctx.fillStyle = '#68AC48';
    ctx.beginPath();
    ctx.arc(cx - Math.round(r * 0.25), cy - Math.round(r * 0.28), Math.max(1, r * 0.55), 0, Math.PI * 2);
    ctx.fill();

    ctx.fillStyle = '#7EC658';
    ctx.fillRect(cx - Math.round(r * 0.4), cy - Math.round(r * 0.4), 2, 2);
    ctx.fillRect(cx + Math.round(r * 0.1), cy - Math.round(r * 0.35), 2, 1);
  };

  const r1 = Math.round(11 * scale);
  drawFoliageCluster(sx - Math.round(9 * scale), canopyBaseY + Math.round(2 * scale), r1);
  drawFoliageCluster(sx + Math.round(9 * scale), canopyBaseY + Math.round(2 * scale), r1);
  drawFoliageCluster(sx, canopyBaseY + Math.round(4 * scale), Math.round(12 * scale));

  const r2 = Math.round(10 * scale);
  drawFoliageCluster(sx - Math.round(6 * scale), canopyBaseY - Math.round(6 * scale), r2);
  drawFoliageCluster(sx + Math.round(6 * scale), canopyBaseY - Math.round(6 * scale), r2);

  const r3 = Math.round(9 * scale);
  drawFoliageCluster(sx, canopyBaseY - Math.round(13 * scale), r3);

  ctx.restore();
}

// ============================================================================
// 3. OVERTURNED DRIFTWOOD ROWBOAT WITH PERCHED SEAGULL
// Location: X: 6.5, Y: 19.5 on the sandy berm left of the path.
// Overturned weathered pine hull: dark cedar brown #704E32 with #8C6442 planks
// and #523620 keel rim (length ~24px, height ~8px).
// Perched on bow: small 16-bit white seagull (white body, #94A3B8 wing, #F59E0B beak).
// ============================================================================
export function drawOverturnedRowboat(
  ctx: CanvasRenderingContext2D,
  camX: number,
  camY: number,
  animTime: number,
) {
  const worldX = 6.5 * TILE_SIZE; // 104
  const worldY = 19.5 * TILE_SIZE; // 312
  const sx = Math.round(worldX - camX);
  const sy = Math.round(worldY - camY);

  if (sx < -40 || sx > VIEWPORT_WIDTH + 40 || sy < -30 || sy > VIEWPORT_HEIGHT + 30) return;

  ctx.save();
  ctx.imageSmoothingEnabled = false;

  // 1. Soft contact shadow in the sand beneath the overturned hull
  ctx.fillStyle = 'rgba(60, 40, 25, 0.35)';
  ctx.beginPath();
  ctx.ellipse(sx, sy + 4, 13, 3, -0.05, 0, Math.PI * 2);
  ctx.fill();

  // 2. Overturned Weathered Pine Rowboat Hull (length ~24px, height ~8px)
  ctx.fillStyle = '#523620';
  ctx.beginPath();
  ctx.ellipse(sx, sy - 3, 10, 2, -0.05, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillRect(sx - 9, sy - 4, 18, 2);

  ctx.fillStyle = '#704E32';
  ctx.beginPath();
  ctx.moveTo(sx - 12, sy + 3);
  ctx.quadraticCurveTo(sx - 10, sy - 3, sx, sy - 4);
  ctx.quadraticCurveTo(sx + 10, sy - 3, sx + 12, sy + 2);
  ctx.quadraticCurveTo(sx + 6, sy + 4, sx, sy + 4);
  ctx.quadraticCurveTo(sx - 8, sy + 4, sx - 12, sy + 3);
  ctx.closePath();
  ctx.fill();

  ctx.fillStyle = '#8C6442';
  ctx.beginPath();
  ctx.moveTo(sx - 11, sy + 1);
  ctx.quadraticCurveTo(sx - 8, sy - 2, sx, sy - 2.5);
  ctx.quadraticCurveTo(sx + 8, sy - 2, sx + 11, sy + 1);
  ctx.lineTo(sx + 10, sy + 3);
  ctx.quadraticCurveTo(sx, sy + 3.5, sx - 10, sy + 2.5);
  ctx.closePath();
  ctx.fill();

  ctx.fillStyle = '#A47854';
  ctx.fillRect(sx - 8, sy - 2, 16, 1);

  ctx.fillStyle = '#523620';
  ctx.fillRect(sx - 9, sy - 1, 18, 1);
  ctx.fillRect(sx - 10, sy + 1, 20, 1);

  ctx.fillStyle = '#523620';
  ctx.fillRect(sx - 12, sy, 2, 3);
  ctx.fillRect(sx + 11, sy - 1, 2, 4);

  // 3. Small 16-Bit White Seagull perched on bow
  const gullX = sx - 10;
  const gullY = sy - 4;

  ctx.fillStyle = '#F59E0B';
  ctx.fillRect(gullX, gullY, 1, 2);
  ctx.fillRect(gullX + 2, gullY, 1, 2);

  ctx.fillStyle = '#FFFFFF';
  ctx.fillRect(gullX - 1, gullY - 3, 5, 3);
  ctx.fillRect(gullX - 2, gullY - 2, 6, 2);

  ctx.fillStyle = '#94A3B8';
  ctx.fillRect(gullX, gullY - 3, 3, 2);
  ctx.fillStyle = '#64748B';
  ctx.fillRect(gullX - 1, gullY - 2, 2, 1);

  ctx.fillStyle = '#FFFFFF';
  ctx.fillRect(gullX + 2, gullY - 5, 3, 3);
  ctx.fillStyle = '#0F172A';
  ctx.fillRect(gullX + 3, gullY - 4, 1, 1);

  ctx.fillStyle = '#F59E0B';
  ctx.fillRect(gullX + 5, gullY - 4, 2, 1);

  ctx.restore();
}

// ============================================================================
// 4. DRIFTWOOD WAYFINDING SIGNPOST
// Location: X: 13, Y: 19 beside the path entrance.
// ============================================================================
export function drawDriftwoodSignpost(
  ctx: CanvasRenderingContext2D,
  camX: number,
  camY: number,
  animTime: number,
) {
  const worldX = 15 * TILE_SIZE; // 240 (moved off the walking path to the right side on the sand)
  const worldY = 19 * TILE_SIZE; // 304
  const sx = Math.round(worldX - camX);
  const sy = Math.round(worldY - camY);

  if (sx < -30 || sx > VIEWPORT_WIDTH + 30 || sy < -30 || sy > VIEWPORT_HEIGHT + 30) return;

  ctx.save();
  ctx.imageSmoothingEnabled = false;

  ctx.fillStyle = 'rgba(50, 35, 20, 0.35)';
  ctx.beginPath();
  ctx.ellipse(sx + 8, sy + 15, 6, 2, 0, 0, Math.PI * 2);
  ctx.fill();

  ctx.fillStyle = '#381C08';
  ctx.fillRect(sx + 6, sy + 1, 4, 15);
  ctx.fillStyle = '#542C16';
  ctx.fillRect(sx + 7, sy + 1, 2, 14);
  ctx.fillStyle = '#784420';
  ctx.fillRect(sx + 7, sy + 1, 1, 14);

  // Top Board (↑ Path to Town Gate)
  ctx.fillStyle = '#381C08';
  ctx.fillRect(sx + 1, sy + 2, 14, 5);
  ctx.fillStyle = '#B0784A';
  ctx.fillRect(sx + 2, sy + 3, 12, 3);
  ctx.fillStyle = '#CA8A04';
  ctx.fillRect(sx + 2, sy + 3, 12, 1);
  ctx.fillStyle = '#261205';
  ctx.fillRect(sx + 4, sy + 3, 1, 2);
  ctx.fillRect(sx + 3, sy + 3, 3, 1);
  ctx.fillRect(sx + 7, sy + 4, 6, 1);

  // Lower Board (→ The Bight Boathouse & Lighthouse)
  ctx.fillStyle = '#381C08';
  ctx.fillRect(sx + 2, sy + 8, 14, 5);
  ctx.fillStyle = '#9E6A3E';
  ctx.fillRect(sx + 3, sy + 9, 12, 3);
  ctx.fillStyle = '#C4824D';
  ctx.fillRect(sx + 3, sy + 9, 12, 1);
  ctx.fillStyle = '#261205';
  ctx.fillRect(sx + 5, sy + 10, 5, 1);
  ctx.fillRect(sx + 12, sy + 10, 2, 1);
  ctx.fillRect(sx + 11, sy + 9, 1, 3);

  // Brass Lantern hanging from side bracket
  const lantX = sx - 1;
  const lantY = sy + 6;

  ctx.fillStyle = '#334155';
  ctx.fillRect(lantX + 4, lantY - 2, 4, 1);
  ctx.fillRect(lantX + 5, lantY - 1, 1, 2);

  ctx.fillStyle = '#261B14';
  ctx.fillRect(lantX, lantY, 5, 6);
  ctx.fillStyle = '#D97706';
  ctx.fillRect(lantX, lantY, 5, 1);
  ctx.fillStyle = '#FBBF24';
  ctx.fillRect(lantX + 1, lantY - 1, 3, 1);

  ctx.fillStyle = '#F59E0B';
  ctx.fillRect(lantX + 1, lantY + 1, 3, 4);
  ctx.fillStyle = '#FEF08A';
  ctx.fillRect(lantX + 2, lantY + 2, 2, 2);
  ctx.fillStyle = '#FFFFFF';
  ctx.fillRect(lantX + 2, lantY + 2, 1, 1);

  const flicker = Math.sin(animTime * 4.5) * 1.5;
  const radius = Math.max(1, 16 + flicker);
  const glow = ctx.createRadialGradient(lantX + 2, lantY + 3, 1, lantX + 2, lantY + 3, radius);
  glow.addColorStop(0, 'rgba(254, 240, 138, 0.40)');
  glow.addColorStop(0.45, 'rgba(251, 191, 36, 0.16)');
  glow.addColorStop(1, 'rgba(245, 158, 11, 0)');
  ctx.fillStyle = glow;
  ctx.beginPath();
  ctx.arc(lantX + 2, lantY + 3, radius, 0, Math.PI * 2);
  ctx.fill();

  ctx.restore();
}

// ============================================================================
// CANTO I: ANIMATED COASTAL SAILING BOAT, CRATES & UPPER COVE MEADOW RENDERER
// ============================================================================
export function drawCanto1Decorations(
  ctx: CanvasRenderingContext2D,
  cameraX: number,
  cameraY: number,
  canvas: { width: number; height: number } = { width: VIEWPORT_WIDTH, height: VIEWPORT_HEIGHT },
  now: number = Date.now(),
) {
  // 1. Authentic 16-bit wooden cargo crates next to The Bight boathouse (X: 22..23, Y: 18..19)
  const cratesScreenX = Math.round(22 * TILE_SIZE - cameraX);
  const cratesScreenY = Math.round(18 * TILE_SIZE - cameraY);

  if (cratesScreenX > -40 && cratesScreenX < canvas.width + 40 && cratesScreenY > -40 && cratesScreenY < canvas.height + 40) {
    drawBoathouseCrates(ctx, cameraX, cameraY);
  }

  // 1d. Overturned weathered pine rowboat with perched seagull at X: 6.5, Y: 19.5
  drawOverturnedRowboat(ctx, cameraX, cameraY, now / 1000);

  // 1e. Driftwood wayfinding signpost with hanging brass lantern at X: 13, Y: 19
  drawDriftwoodSignpost(ctx, cameraX, cameraY, now / 1000);

  if (cratesScreenX > -40 && cratesScreenX < canvas.width + 40 && cratesScreenY > -40 && cratesScreenY < canvas.height + 40) {
    ctx.save();
    ctx.imageSmoothingEnabled = false;

    // Soft drop shadow under the crate stack on the dock
    ctx.fillStyle = 'rgba(40, 25, 15, 0.30)';
    ctx.fillRect(cratesScreenX + 1, cratesScreenY + 29, 30, 3);

    // Crate renderer helper for authentic 16-bit wooden cargo crates
    const drawSingleCrate = (cx: number, cy: number, crossLeftToRight: boolean) => {
      // Dark corner iron/wood boundary
      ctx.fillStyle = '#4A3B2C';
      ctx.fillRect(cx, cy, 15, 15);

      // Shaded weathered pine bevel
      ctx.fillStyle = '#8B6235';
      ctx.fillRect(cx + 1, cy + 1, 13, 13);

      // Warm weathered pine face
      ctx.fillStyle = '#A07848';
      ctx.fillRect(cx + 2, cy + 2, 11, 11);

      // Top sunlit pine plank highlight
      ctx.fillStyle = '#B88C56';
      ctx.fillRect(cx + 2, cy + 2, 11, 1);

      // Horizontal plank seam
      ctx.fillStyle = '#8B6235';
      ctx.fillRect(cx + 2, cy + 7, 11, 1);

      // Clean diagonal cross braces (#B88C56)
      ctx.fillStyle = '#B88C56';
      if (crossLeftToRight) {
        ctx.fillRect(cx + 3, cy + 3, 2, 2);
        ctx.fillRect(cx + 5, cy + 5, 2, 2);
        ctx.fillRect(cx + 7, cy + 7, 2, 2);
        ctx.fillRect(cx + 9, cy + 9, 2, 2);
        ctx.fillRect(cx + 10, cy + 10, 2, 2);
      } else {
        ctx.fillRect(cx + 10, cy + 3, 2, 2);
        ctx.fillRect(cx + 8, cy + 5, 2, 2);
        ctx.fillRect(cx + 6, cy + 7, 2, 2);
        ctx.fillRect(cx + 4, cy + 9, 2, 2);
        ctx.fillRect(cx + 3, cy + 10, 2, 2);
      }

      // Dark corner iron brackets (#4A3B2C) at all four corners (no yellow dots!)
      ctx.fillStyle = '#4A3B2C';
      // Top-Left bracket
      ctx.fillRect(cx + 1, cy + 1, 3, 2);
      ctx.fillRect(cx + 1, cy + 1, 2, 3);
      // Top-Right bracket
      ctx.fillRect(cx + 11, cy + 1, 3, 2);
      ctx.fillRect(cx + 12, cy + 1, 2, 3);
      // Bottom-Left bracket
      ctx.fillRect(cx + 1, cy + 12, 3, 2);
      ctx.fillRect(cx + 1, cy + 11, 2, 3);
      // Bottom-Right bracket
      ctx.fillRect(cx + 11, cy + 12, 3, 2);
      ctx.fillRect(cx + 12, cy + 11, 2, 3);

      // Dark iron rivets in brackets (#36291C)
      ctx.fillStyle = '#36291C';
      ctx.fillRect(cx + 2, cy + 2, 1, 1);
      ctx.fillRect(cx + 12, cy + 2, 1, 1);
      ctx.fillRect(cx + 2, cy + 12, 1, 1);
      ctx.fillRect(cx + 12, cy + 12, 1, 1);
    };

    // Draw the 2x2 crate arrangement on the timber side-dock
    drawSingleCrate(cratesScreenX, cratesScreenY, true);        // Top-Left crate
    drawSingleCrate(cratesScreenX + 16, cratesScreenY, false);   // Top-Right crate
    drawSingleCrate(cratesScreenX, cratesScreenY + 15, false);   // Bottom-Left crate
    drawSingleCrate(cratesScreenX + 16, cratesScreenY + 15, true); // Bottom-Right crate

    ctx.restore();
  }

  // 2. Charming Upper Cove Meadow Decor above the Lighthouse (X: 31..35, Y: 10..14)
  const meadowScreenX = Math.round(31 * TILE_SIZE - cameraX);
  const meadowScreenY = Math.round(10 * TILE_SIZE - cameraY);

  if (meadowScreenX > -90 && meadowScreenX < canvas.width + 40 && meadowScreenY > -90 && meadowScreenY < canvas.height + 40) {
    ctx.save();
    ctx.imageSmoothingEnabled = false;

    // Helper: Draw smooth coastal grey rocks
    const drawCoastalRock = (rx: number, ry: number, rw: number, rh: number) => {
      ctx.fillStyle = 'rgba(25, 20, 15, 0.20)';
      ctx.beginPath();
      ctx.ellipse(rx + rw / 2, ry + rh - 1, rw / 2 + 1, 2.5, 0, 0, Math.PI * 2);
      ctx.fill();

      // Slate-grey rock body (#64748B, #475569)
      ctx.fillStyle = '#475569';
      ctx.beginPath();
      ctx.ellipse(rx + rw / 2, ry + rh / 2, rw / 2, rh / 2, 0, 0, Math.PI * 2);
      ctx.fill();

      ctx.fillStyle = '#64748B';
      ctx.beginPath();
      ctx.ellipse(rx + rw / 2 - 0.5, ry + rh / 2 - 0.5, rw / 2 - 1, rh / 2 - 1, 0, 0, Math.PI * 2);
      ctx.fill();

      // Sunlit upper facet highlight (#94A3B8, #CBD5E1)
      ctx.fillStyle = '#94A3B8';
      ctx.beginPath();
      ctx.ellipse(rx + rw / 2 - 1, ry + rh / 2 - 1.5, rw / 2 - 2, Math.max(1, rh / 4), 0, 0, Math.PI * 2);
      ctx.fill();

      // Soft velvety moss accent (#4D7C0F, #365314)
      ctx.fillStyle = '#4D7C0F';
      ctx.fillRect(rx + 2, ry + rh - 3, 3, 2);
    };

    // Helper: Draw clusters of seaside wildflowers (lavender #9B84C8, sea pinks #E886A2, yellow poppies #F4CA54)
    const drawWildflowerCluster = (fx: number, fy: number, type: 'LAVENDER' | 'SEA_PINK' | 'POPPY') => {
      if (type === 'LAVENDER') {
        // Slender green stem
        ctx.fillStyle = '#3E6643';
        ctx.fillRect(fx + 1, fy + 2, 1, 6);
        ctx.fillRect(fx + 4, fy + 3, 1, 5);
        // Lavender sprigs (#9B84C8, #7C62A8)
        ctx.fillStyle = '#7C62A8';
        ctx.fillRect(fx, fy, 3, 4);
        ctx.fillRect(fx + 3, fy + 1, 3, 4);
        ctx.fillStyle = '#9B84C8';
        ctx.fillRect(fx + 1, fy, 1, 3);
        ctx.fillRect(fx + 4, fy + 1, 1, 3);
        ctx.fillStyle = '#C2B2DE';
        ctx.fillRect(fx + 1, fy - 1, 1, 1);
      } else if (type === 'SEA_PINK') {
        // Sea pinks (#E886A2, #D06684) rounded thrift pom-pom blossoms
        ctx.fillStyle = '#2B5732';
        ctx.fillRect(fx + 2, fy + 3, 1, 5);
        ctx.fillRect(fx + 5, fy + 2, 1, 6);
        ctx.fillStyle = '#D06684';
        ctx.fillRect(fx, fy, 4, 4);
        ctx.fillRect(fx + 4, fy - 1, 4, 4);
        ctx.fillStyle = '#E886A2';
        ctx.fillRect(fx + 1, fy, 2, 2);
        ctx.fillRect(fx + 5, fy - 1, 2, 2);
        ctx.fillStyle = '#F4B6C6';
        ctx.fillRect(fx + 1, fy, 1, 1);
        ctx.fillRect(fx + 5, fy - 1, 1, 1);
      } else {
        // Yellow maritime poppies (#F4CA54, #D8A62A)
        ctx.fillStyle = '#3E6643';
        ctx.fillRect(fx + 2, fy + 3, 1, 5);
        ctx.fillStyle = '#D8A62A';
        ctx.fillRect(fx, fy, 5, 4);
        ctx.fillStyle = '#F4CA54';
        ctx.fillRect(fx + 1, fy, 3, 3);
        ctx.fillStyle = '#78350F'; // Dark poppy center
        ctx.fillRect(fx + 2, fy + 1, 1, 1);
        ctx.fillStyle = '#FDF0A6';
        ctx.fillRect(fx + 1, fy, 1, 1);
      }
    };

    // Helper: Draw charming coastal pine trees with layered dark teal-green needles and brown trunks
    const drawCoastalPineTree = (tx: number, ty: number, height: number) => {
      // Soft tree shadow
      ctx.fillStyle = 'rgba(20, 30, 25, 0.22)';
      ctx.beginPath();
      ctx.ellipse(tx + 8, ty + height, 9, 3, 0, 0, Math.PI * 2);
      ctx.fill();

      // Weathered brown pine trunk (#6B4423, #4A2E16, #8C5A32)
      ctx.fillStyle = '#4A2E16';
      ctx.fillRect(tx + 6, ty + height - 10, 4, 10);
      ctx.fillStyle = '#6B4423';
      ctx.fillRect(tx + 7, ty + height - 10, 2, 9);
      ctx.fillStyle = '#8C5A32';
      ctx.fillRect(tx + 7, ty + height - 10, 1, 8); // Sunlit bark ridge
      // Root flare
      ctx.fillStyle = '#4A2E16';
      ctx.fillRect(tx + 5, ty + height - 2, 2, 2);
      ctx.fillRect(tx + 9, ty + height - 2, 2, 2);

      // Layered dark teal-green pine needles:
      // Palette: deep #134E48, mid #0F766E, sunlit #14B8A6 / #2DD4BF
      // Tier 3 (Bottom wide bough)
      const b3Y = ty + height - 14;
      ctx.fillStyle = '#0B3632';
      ctx.beginPath();
      ctx.moveTo(tx + 8, b3Y - 6);
      ctx.lineTo(tx + 18, b3Y + 4);
      ctx.lineTo(tx - 2, b3Y + 4);
      ctx.closePath();
      ctx.fill();

      ctx.fillStyle = '#0F766E';
      ctx.beginPath();
      ctx.moveTo(tx + 8, b3Y - 5);
      ctx.lineTo(tx + 16, b3Y + 3);
      ctx.lineTo(tx, b3Y + 3);
      ctx.closePath();
      ctx.fill();

      ctx.fillStyle = '#14B8A6';
      ctx.fillRect(tx + 2, b3Y - 1, 12, 2);
      ctx.fillStyle = '#2DD4BF';
      ctx.fillRect(tx + 4, b3Y - 1, 7, 1);

      // Tier 2 (Middle bough)
      const b2Y = ty + height - 21;
      ctx.fillStyle = '#0B3632';
      ctx.beginPath();
      ctx.moveTo(tx + 8, b2Y - 6);
      ctx.lineTo(tx + 16, b2Y + 4);
      ctx.lineTo(tx, b2Y + 4);
      ctx.closePath();
      ctx.fill();

      ctx.fillStyle = '#0F766E';
      ctx.beginPath();
      ctx.moveTo(tx + 8, b2Y - 5);
      ctx.lineTo(tx + 14, b2Y + 3);
      ctx.lineTo(tx + 2, b2Y + 3);
      ctx.closePath();
      ctx.fill();

      ctx.fillStyle = '#14B8A6';
      ctx.fillRect(tx + 4, b2Y - 1, 8, 2);
      ctx.fillStyle = '#2DD4BF';
      ctx.fillRect(tx + 5, b2Y - 1, 5, 1);

      // Tier 1 (Top tapered crown)
      const b1Y = ty + height - 28;
      ctx.fillStyle = '#0B3632';
      ctx.beginPath();
      ctx.moveTo(tx + 8, b1Y - 6);
      ctx.lineTo(tx + 13, b1Y + 4);
      ctx.lineTo(tx + 3, b1Y + 4);
      ctx.closePath();
      ctx.fill();

      ctx.fillStyle = '#0F766E';
      ctx.beginPath();
      ctx.moveTo(tx + 8, b1Y - 5);
      ctx.lineTo(tx + 12, b1Y + 3);
      ctx.lineTo(tx + 4, b1Y + 3);
      ctx.closePath();
      ctx.fill();

      ctx.fillStyle = '#14B8A6';
      ctx.fillRect(tx + 6, b1Y - 2, 4, 2);
      ctx.fillStyle = '#2DD4BF';
      ctx.fillRect(tx + 7, b1Y - 4, 2, 2);
    };

    // Render charming coastal pine trees in the meadow above lighthouse (X: 31..35, Y: 10..14)
    const pine1X = Math.round(32 * TILE_SIZE - cameraX);
    const pine1Y = Math.round(10 * TILE_SIZE - cameraY);
    drawCoastalPineTree(pine1X, pine1Y, 34);

    const pine2X = Math.round(34.2 * TILE_SIZE - cameraX);
    const pine2Y = Math.round(11 * TILE_SIZE - cameraY);
    drawCoastalPineTree(pine2X, pine2Y, 32);

    const pine3X = Math.round(31 * TILE_SIZE - cameraX);
    const pine3Y = Math.round(12.5 * TILE_SIZE - cameraY);
    drawCoastalPineTree(pine3X, pine3Y, 30);

    // Smooth coastal grey rocks nestled in the meadow grass
    drawCoastalRock(Math.round(33.2 * TILE_SIZE - cameraX), Math.round(12.2 * TILE_SIZE - cameraY), 12, 8);
    drawCoastalRock(Math.round(34.5 * TILE_SIZE - cameraX), Math.round(13.6 * TILE_SIZE - cameraY), 10, 6);
    drawCoastalRock(Math.round(31.8 * TILE_SIZE - cameraX), Math.round(14.0 * TILE_SIZE - cameraY), 11, 7);

    // Clusters of seaside wildflowers in the meadow
    // Lavender sprigs (#9B84C8)
    drawWildflowerCluster(Math.round(32.8 * TILE_SIZE - cameraX), Math.round(13.2 * TILE_SIZE - cameraY), 'LAVENDER');
    drawWildflowerCluster(Math.round(35.0 * TILE_SIZE - cameraX), Math.round(12.4 * TILE_SIZE - cameraY), 'LAVENDER');

    // Sea pinks (#E886A2)
    drawWildflowerCluster(Math.round(33.8 * TILE_SIZE - cameraX), Math.round(14.0 * TILE_SIZE - cameraY), 'SEA_PINK');
    drawWildflowerCluster(Math.round(31.2 * TILE_SIZE - cameraX), Math.round(11.8 * TILE_SIZE - cameraY), 'SEA_PINK');

    // Yellow maritime poppies (#F4CA54)
    drawWildflowerCluster(Math.round(32.2 * TILE_SIZE - cameraX), Math.round(14.2 * TILE_SIZE - cameraY), 'POPPY');
    drawWildflowerCluster(Math.round(34.4 * TILE_SIZE - cameraX), Math.round(10.8 * TILE_SIZE - cameraY), 'POPPY');

    ctx.restore();
  }

  // 3. Animated coastal sailing boat in Canto I (proportionate coastal trading vessel)
  const cycleDuration = 45000; // 45s cycle
  const tCycle = (now % cycleDuration);
  const sailDuration = 32000; // sails for 32s, rests 13s offscreen
  if (tCycle < sailDuration) {
    const progress = tCycle / sailDuration; // 0 to 1
    // Non-linear speed curve: slows down near lighthouse (around progress 0.1 to 0.35)
    // Map progress to world X from 38 down to -6:
    let boatWorldX = 38;
    if (progress < 0.12) {
      // Entering from right
      const p = progress / 0.12;
      boatWorldX = 38 - p * 4; // 38 -> 34
    } else if (progress < 0.38) {
      // Drifting slowly past lighthouse (X: 34 to 30)
      const p = (progress - 0.12) / 0.26;
      boatWorldX = 34 - p * 4; // 34 -> 30 (slow!)
    } else {
      // Cruising westward past boathouse and open water below pier (X: 30 to -6)
      const p = (progress - 0.38) / 0.62;
      boatWorldX = 30 - p * 36; // 30 -> -6
    }
    const boatScreenX = Math.round(boatWorldX * TILE_SIZE - cameraX);
    // Sail lane locked strictly to open ocean water BELOW the pier at Y: 24.2 (well below pier edge at Y: 23)
    const boatBob = Math.sin(now / 500) * 1.5;
    const boatScreenY = Math.round(24.2 * TILE_SIZE - cameraY + boatBob);

    if (boatScreenX > -50 && boatScreenX < canvas.width + 50) {
      // Draw wake trailing behind to the right (stern is at boatScreenX + 32)
      ctx.fillStyle = 'rgba(255, 255, 255, 0.45)';
      ctx.fillRect(boatScreenX + 32, boatScreenY + 6, 12, 2);
      ctx.fillStyle = 'rgba(200, 235, 255, 0.30)';
      ctx.fillRect(boatScreenX + 42, boatScreenY + 7, 10, 1.5);
      ctx.fillRect(boatScreenX + 28, boatScreenY + 7, 8, 1);
      // Small bow wave ripple at the front
      ctx.fillStyle = 'rgba(255, 255, 255, 0.50)';
      ctx.fillRect(boatScreenX - 2, boatScreenY + 7, 3, 1.5);

      // Sturdy timber hull (~32px wide, ~8px tall, facing left)
      // Dark bottom keel
      ctx.fillStyle = '#261205';
      ctx.fillRect(boatScreenX + 6, boatScreenY + 7, 22, 2);

      // Main timber hull body
      ctx.fillStyle = '#603818'; // Lower strake / shadow
      ctx.fillRect(boatScreenX + 4, boatScreenY + 5, 26, 3);
      ctx.fillStyle = '#7A4B24'; // Mid strake
      ctx.fillRect(boatScreenX + 2, boatScreenY + 3, 29, 3);
      ctx.fillStyle = '#925226'; // Upper strake
      ctx.fillRect(boatScreenX + 1, boatScreenY + 1, 30, 3);

      // Curved bow on left (pointing westward)
      ctx.fillStyle = '#7A4B24';
      ctx.fillRect(boatScreenX - 1, boatScreenY + 2, 3, 2);
      ctx.fillRect(boatScreenX - 3, boatScreenY + 1, 3, 2);
      // Wooden bowsprit spar projecting forward
      ctx.fillStyle = '#542C16';
      ctx.fillRect(boatScreenX - 7, boatScreenY + 1, 5, 1);
      ctx.fillStyle = '#FBBF24'; // Brass cap
      ctx.fillRect(boatScreenX - 8, boatScreenY + 1, 1, 1);

      // Transom stern on right
      ctx.fillStyle = '#542C16';
      ctx.fillRect(boatScreenX + 31, boatScreenY + 2, 2, 4);

      // Gunwale sheer highlight along top edge
      ctx.fillStyle = '#C4824D';
      ctx.fillRect(boatScreenX - 2, boatScreenY + 1, 34, 1);
      ctx.fillStyle = '#DF9C64';
      ctx.fillRect(boatScreenX, boatScreenY + 1, 18, 1);

      // Tall wooden mast (~18px tall, positioned at boatScreenX + 13)
      const mastX = boatScreenX + 13;
      const mastTopY = boatScreenY - 18;
      ctx.fillStyle = '#381C08';
      ctx.fillRect(mastX, mastTopY, 2, 20);
      ctx.fillStyle = '#8A5830';
      ctx.fillRect(mastX, mastTopY, 1, 20);
      ctx.fillStyle = '#FBBF24'; // Brass truck / masthead ball
      ctx.fillRect(mastX - 1, mastTopY - 1, 4, 2);

      // Red pennant on masthead (fluttering trailing eastward)
      const pennantFlutter = Math.round(Math.sin(now / 180) * 0.8);
      ctx.fillStyle = '#DC2626';
      ctx.fillRect(mastX + 2, mastTopY - 1 + pennantFlutter, 6, 2);
      ctx.fillStyle = '#EF4444';
      ctx.fillRect(mastX + 2, mastTopY - 1 + pennantFlutter, 4, 1);
      ctx.fillRect(mastX + 8, mastTopY + pennantFlutter, 2, 1);

      // Billowing Mainsail (aft of mast, between mastX and stern)
      ctx.fillStyle = '#CBD5E1'; // Shadow crease
      ctx.beginPath();
      ctx.moveTo(mastX + 2, mastTopY + 2);
      ctx.lineTo(boatScreenX + 30, boatScreenY);
      ctx.lineTo(mastX + 2, boatScreenY + 1);
      ctx.closePath();
      ctx.fill();

      ctx.fillStyle = '#F1F5F9'; // Main canvas body
      ctx.beginPath();
      ctx.moveTo(mastX + 2, mastTopY + 3);
      ctx.lineTo(boatScreenX + 28, boatScreenY - 1);
      ctx.lineTo(mastX + 2, boatScreenY);
      ctx.closePath();
      ctx.fill();

      ctx.fillStyle = '#FFFFFF'; // Sunlit billowing highlight
      ctx.beginPath();
      ctx.moveTo(mastX + 2, mastTopY + 5);
      ctx.lineTo(boatScreenX + 24, boatScreenY - 2);
      ctx.lineTo(mastX + 2, boatScreenY - 2);
      ctx.closePath();
      ctx.fill();

      // Triangular Jib / Headsail (forward of mast down to bow)
      ctx.fillStyle = '#CBD5E1'; // Shadow
      ctx.beginPath();
      ctx.moveTo(mastX - 1, mastTopY + 3);
      ctx.lineTo(boatScreenX - 4, boatScreenY + 1);
      ctx.lineTo(mastX - 1, boatScreenY + 1);
      ctx.closePath();
      ctx.fill();

      ctx.fillStyle = '#FFFFFF'; // Crisp white canvas
      ctx.beginPath();
      ctx.moveTo(mastX - 1, mastTopY + 4);
      ctx.lineTo(boatScreenX - 3, boatScreenY);
      ctx.lineTo(mastX - 1, boatScreenY);
      ctx.closePath();
      ctx.fill();

      // Forestay rigging stay line from masthead to bowsprit
      ctx.strokeStyle = '#94A3B8';
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.moveTo(mastX, mastTopY + 1);
      ctx.lineTo(boatScreenX - 7, boatScreenY + 1);
      ctx.stroke();
    }
  }
}

export function drawBoathouseCrates(
  ctx: CanvasRenderingContext2D,
  camX: number,
  camY: number,
) {
  const worldX = 22 * TILE_SIZE; // 352
  const worldY = 18 * TILE_SIZE; // 288
  const sx = Math.round(worldX - camX);
  const sy = Math.round(worldY - camY);

  if (sx < -40 || sx > VIEWPORT_WIDTH + 40 || sy < -40 || sy > VIEWPORT_HEIGHT + 40) return;

  ctx.save();
  ctx.imageSmoothingEnabled = false;

  ctx.fillStyle = 'rgba(40, 25, 15, 0.30)';
  ctx.fillRect(sx + 1, sy + 29, 30, 3);

  const drawSingleCrate = (cx: number, cy: number, crossLeftToRight: boolean) => {
    ctx.fillStyle = '#4A3B2C';
    ctx.fillRect(cx, cy, 15, 15);
    ctx.fillStyle = '#8B6235';
    ctx.fillRect(cx + 1, cy + 1, 13, 13);
    ctx.fillStyle = '#A07848';
    ctx.fillRect(cx + 2, cy + 2, 11, 11);
    ctx.fillStyle = '#B88C56';
    ctx.fillRect(cx + 2, cy + 2, 11, 1);
    ctx.fillStyle = '#8B6235';
    ctx.fillRect(cx + 2, cy + 7, 11, 1);

    ctx.fillStyle = '#B88C56';
    if (crossLeftToRight) {
      ctx.fillRect(cx + 3, cy + 3, 2, 2);
      ctx.fillRect(cx + 5, cy + 5, 2, 2);
      ctx.fillRect(cx + 7, cy + 7, 2, 2);
      ctx.fillRect(cx + 9, cy + 9, 2, 2);
      ctx.fillRect(cx + 10, cy + 10, 2, 2);
    } else {
      ctx.fillRect(cx + 10, cy + 3, 2, 2);
      ctx.fillRect(cx + 8, cy + 5, 2, 2);
      ctx.fillRect(cx + 6, cy + 7, 2, 2);
      ctx.fillRect(cx + 4, cy + 9, 2, 2);
      ctx.fillRect(cx + 3, cy + 10, 2, 2);
    }

    ctx.fillStyle = '#4A3B2C';
    ctx.fillRect(cx + 1, cy + 1, 3, 2);
    ctx.fillRect(cx + 1, cy + 1, 2, 3);
    ctx.fillRect(cx + 11, cy + 1, 3, 2);
    ctx.fillRect(cx + 12, cy + 1, 2, 3);
    ctx.fillRect(cx + 1, cy + 12, 3, 2);
    ctx.fillRect(cx + 1, cy + 11, 2, 3);
    ctx.fillRect(cx + 11, cy + 12, 3, 2);
    ctx.fillRect(cx + 12, cy + 11, 2, 3);

    ctx.fillStyle = '#36291C';
    ctx.fillRect(cx + 2, cy + 2, 1, 1);
    ctx.fillRect(cx + 12, cy + 2, 1, 1);
    ctx.fillRect(cx + 2, cy + 12, 1, 1);
    ctx.fillRect(cx + 12, cy + 12, 1, 1);
  };

  drawSingleCrate(sx, sy, true);
  drawSingleCrate(sx + 16, sy, false);
  drawSingleCrate(sx, sy + 15, false);
  drawSingleCrate(sx + 16, sy + 15, true);

  ctx.restore();
}

export function drawBoathouseExterior(
  ctx: CanvasRenderingContext2D,
  camX: number,
  camY: number,
  animTime: number,
) {
  // Building sits at X: 24..29, Y: 16..19 (6 tiles wide, 4 tiles tall)
  const worldX = 24 * TILE_SIZE; // 384
  const worldY = 16 * TILE_SIZE; // 256
  const sx = Math.round(worldX - camX);
  const sy = Math.round(worldY - camY);
  const w = 6 * TILE_SIZE; // 96
  const h = 4 * TILE_SIZE; // 64

  if (sx < -w - 20 || sx > VIEWPORT_WIDTH + 20 || sy < -h - 20 || sy > VIEWPORT_HEIGHT + 20) {
    return;
  }

  ctx.save();
  ctx.imageSmoothingEnabled = false;

  // 1. Draw natural underlying coastal sand terrain first across the building footprint
  ctx.fillStyle = '#edd69c';
  ctx.fillRect(sx - 2, sy + 28, w + 4, h - 28);

  // 2. Weathered Light Cedar Wood Walls (Rows Y: 18..19, which is sy + 30 to sy + 64)
  // Palette: #C8B898 warm light cedar, #D8C8A8 sunlit plank, #B0A080 shadow seam
  ctx.fillStyle = '#7a6a58'; // Soft weathered wood boundary
  ctx.fillRect(sx + 2, sy + 30, w - 4, 34);
  ctx.fillStyle = '#C8B898'; // Warm weathered cedar base
  ctx.fillRect(sx + 3, sy + 31, w - 6, 33);

  // Subtle vertical plank seams spaced every 8px
  for (let px = sx + 8; px < sx + w - 4; px += 8) {
    ctx.fillStyle = '#B0A080'; // Plank shadow joint
    ctx.fillRect(px, sy + 31, 1, 33);
    ctx.fillStyle = '#D8C8A8'; // Subtle sunlit plank highlight
    ctx.fillRect(px + 1, sy + 31, 1, 33);
  }

  // Stone/timber foundation plinth trim along bottom
  ctx.fillStyle = '#9e8e7a';
  ctx.fillRect(sx + 2, sy + 62, w - 4, 2);
  ctx.fillStyle = '#B0A080';
  ctx.fillRect(sx + 3, sy + 62, w - 6, 1);

  // 3. Sloping Gabled Shingle Roof across top 2 rows (Y: 16..17, sy + 0 to sy + 31)
  // Palette: #607888 slate blue / cedar blue-grey shingles, #7a90a0 highlight, #455564 shadow
  // Overhanging roof eave at sy + 28 projecting 2px beyond walls on both sides
  ctx.fillStyle = '#334155';
  ctx.fillRect(sx - 3, sy + 28, w + 6, 4);
  ctx.fillStyle = '#E8DEC8'; // Clean cream/white eave fascia trim
  ctx.fillRect(sx - 2, sy + 28, w + 4, 2);
  ctx.fillStyle = '#FFFFFF';
  ctx.fillRect(sx - 2, sy + 28, w + 4, 1);
  // Soft eave drop shadow onto cedar walls below
  ctx.fillStyle = 'rgba(45, 35, 25, 0.20)';
  ctx.fillRect(sx + 2, sy + 32, w - 4, 3);

  // Gabled pitched roof shingles (sy + 2 to sy + 28)
  for (let y = 0; y <= 26; y++) {
    const curY = sy + 28 - y;
    const inset = Math.round(y * 1.3);
    const rowX = sx - 2 + inset;
    const rowW = Math.max(4, (w + 4) - inset * 2);

    ctx.fillStyle = (y % 4 === 0) ? '#4a5d6e' : '#607888'; // Slate blue/cedar blue-grey
    ctx.fillRect(rowX, curY, rowW, 1);

    if (y % 3 === 0) {
      ctx.fillStyle = '#7a90a0'; // Shingle sunlit edge
      ctx.fillRect(rowX, curY, rowW, 1);
      ctx.fillStyle = '#3a4a58'; // Shingle vertical joint
      for (let ix = rowX + 6; ix < rowX + rowW - 4; ix += 8) {
        ctx.fillRect(ix, curY, 1, 2);
      }
    }
  }

  // Dark roof ridge cap at top peak
  ctx.fillStyle = '#334155';
  ctx.fillRect(sx + 28, sy + 2, w - 56, 2);
  ctx.fillStyle = '#7a90a0';
  ctx.fillRect(sx + 30, sy + 1, w - 60, 1);

  // Small brass weathervane with flying gull at apex
  ctx.fillStyle = '#475569';
  ctx.fillRect(sx + 47, sy - 5, 2, 7);
  ctx.fillStyle = '#fbbf24'; // Brass ball
  ctx.fillRect(sx + 46, sy - 6, 4, 2);
  ctx.fillStyle = '#d97706';
  ctx.fillRect(sx + 43, sy - 4, 10, 1); // Cross arms
  // Flying white gull
  ctx.fillStyle = '#ffffff';
  ctx.fillRect(sx + 45, sy - 9, 6, 2);
  ctx.fillStyle = '#cbd5e1';
  ctx.fillRect(sx + 44, sy - 10, 2, 2);
  ctx.fillRect(sx + 50, sy - 10, 2, 2);

  // 4. Windows: Two Small Square Multi-Pane Windows with White Trim and Sky-Blue Reflection
  // Left window (X: 25, sx + 14..26, sy + 35..45)
  const lWinX = sx + 14;
  const lWinY = sy + 35;
  ctx.fillStyle = '#7a6a58';
  ctx.fillRect(lWinX - 1, lWinY - 1, 14, 13);
  ctx.fillStyle = '#ffffff'; // Crisp white trim
  ctx.fillRect(lWinX, lWinY, 12, 11);
  // Sky-blue glass reflection
  ctx.fillStyle = '#38bdf8';
  ctx.fillRect(lWinX + 1, lWinY + 1, 4, 4); // Pane TL
  ctx.fillRect(lWinX + 7, lWinY + 1, 4, 4); // Pane TR
  ctx.fillRect(lWinX + 1, lWinY + 6, 4, 4); // Pane BL
  ctx.fillRect(lWinX + 7, lWinY + 6, 4, 4); // Pane BR
  ctx.fillStyle = '#7dd3fc';
  ctx.fillRect(lWinX + 2, lWinY + 2, 2, 2); // Glass shine
  ctx.fillRect(lWinX + 8, lWinY + 2, 2, 2);
  ctx.fillStyle = '#ffffff';
  ctx.fillRect(lWinX + 5, lWinY, 2, 11); // Center vertical mullion
  ctx.fillRect(lWinX, lWinY + 5, 12, 1); // Center horizontal mullion
  // Window sill
  ctx.fillStyle = '#54321d';
  ctx.fillRect(lWinX - 2, lWinY + 11, 16, 2);
  ctx.fillStyle = '#9e623b';
  ctx.fillRect(lWinX - 2, lWinY + 11, 16, 1);

  // Right window (X: 28, sx + 70..82, sy + 35..45)
  const rWinX = sx + 70;
  const rWinY = sy + 35;
  ctx.fillStyle = '#7a6a58';
  ctx.fillRect(rWinX - 1, rWinY - 1, 14, 13);
  ctx.fillStyle = '#ffffff';
  ctx.fillRect(rWinX, rWinY, 12, 11);
  ctx.fillStyle = '#38bdf8';
  ctx.fillRect(rWinX + 1, rWinY + 1, 4, 4);
  ctx.fillRect(rWinX + 7, rWinY + 1, 4, 4);
  ctx.fillRect(rWinX + 1, rWinY + 6, 4, 4);
  ctx.fillRect(rWinX + 7, rWinY + 6, 4, 4);
  ctx.fillStyle = '#7dd3fc';
  ctx.fillRect(rWinX + 2, rWinY + 2, 2, 2);
  ctx.fillRect(rWinX + 8, rWinY + 2, 2, 2);
  ctx.fillStyle = '#ffffff';
  ctx.fillRect(rWinX + 5, rWinY, 2, 11);
  ctx.fillRect(rWinX, rWinY + 5, 12, 1);
  ctx.fillStyle = '#54321d';
  ctx.fillRect(rWinX - 2, rWinY + 11, 16, 2);
  ctx.fillStyle = '#9e623b';
  ctx.fillRect(rWinX - 2, rWinY + 11, 16, 1);

  // 5. Wooden Plaque Sign Above Door: "THE BIGHT" (Row Y: 18, sy + 33..41, directly above door)
  const signW = 38;
  const signH = 9;
  const signX = sx + Math.round((w - signW) / 2); // Center aligned at sx + 29
  const signY = sy + 33;

  // Clean wooden plaque sign border
  ctx.fillStyle = '#4a2812';
  ctx.fillRect(signX - 1, signY - 1, signW + 2, signH + 2);
  ctx.fillStyle = '#8a5830'; // Cedar timber border
  ctx.fillRect(signX, signY, signW, signH);
  // Cream vellum face
  ctx.fillStyle = '#fef3c7';
  ctx.fillRect(signX + 2, signY + 2, signW - 4, signH - 4);
  // Polished brass corner studs
  ctx.fillStyle = '#fbbf24';
  ctx.fillRect(signX, signY, 2, 2);
  ctx.fillRect(signX + signW - 2, signY, 2, 2);
  ctx.fillRect(signX, signY + signH - 2, 2, 2);
  ctx.fillRect(signX + signW - 2, signY + signH - 2, 2, 2);

  // Crisp legible pixel font for "THE BIGHT"
  const textStartX = signX + 5;
  const textY = signY + 3;
  ctx.fillStyle = '#1e293b';

  const letterP = (lx: number, ly: number, pattern: number[][]) => {
    ctx.fillStyle = '#1e293b';
    for (let r = 0; r < pattern.length; r++) {
      for (let c = 0; c < pattern[r].length; c++) {
        if (pattern[r][c] === 1) ctx.fillRect(lx + c, ly + r, 1, 1);
      }
    }
  };

  // 'T'
  letterP(textStartX + 0, textY, [[1,1,1],[0,1,0],[0,1,0],[0,1,0]]);
  // 'H'
  letterP(textStartX + 4, textY, [[1,0,1],[1,1,1],[1,0,1],[1,0,1]]);
  // 'E'
  letterP(textStartX + 8, textY, [[1,1,1],[1,1,0],[1,0,0],[1,1,1]]);
  // 'B'
  letterP(textStartX + 13, textY, [[1,1,0],[1,1,1],[1,0,1],[1,1,0]]);
  // 'I'
  letterP(textStartX + 17, textY, [[1,1,1],[0,1,0],[0,1,0],[1,1,1]]);
  // 'G'
  letterP(textStartX + 21, textY, [[0,1,1],[1,0,0],[1,0,1],[0,1,1]]);
  // 'H'
  letterP(textStartX + 25, textY, [[1,0,1],[1,1,1],[1,0,1],[1,0,1]]);
  // 'T'
  letterP(textStartX + 29, textY, [[1,1,1],[0,1,0],[0,1,0],[0,1,0]]);

  // 6. WELCOMING WOODEN DOOR AT THE VERY BOTTOM CENTER (X: 26, Y: 19)
  // Placed at sx + 32..48, sy + 44..64 (rests flush against the bottom edge sy + 64!)
  const doorX = sx + 32;
  const doorY = sy + 44;
  const doorW = 16;
  const doorH = 20;

  // Outer dark casing frame
  ctx.fillStyle = '#2d180c';
  ctx.fillRect(doorX - 2, doorY - 2, doorW + 4, doorH + 2);
  // Red-trimmed / warm dark oak casing header lintel
  ctx.fillStyle = '#6e1824';
  ctx.fillRect(doorX - 1, doorY - 1, doorW + 2, 2);
  ctx.fillStyle = '#991b1b';
  ctx.fillRect(doorX - 1, doorY - 1, doorW + 2, 1);

  // Welcoming warm dark oak door body (#4a2812 / #6b3c1b)
  ctx.fillStyle = '#381f10';
  ctx.fillRect(doorX, doorY, doorW, doorH);
  ctx.fillStyle = '#542d17';
  ctx.fillRect(doorX + 1, doorY + 1, doorW - 2, doorH - 1);

  // Vertical oak plank grooves
  ctx.fillStyle = '#381f10';
  ctx.fillRect(doorX + 5, doorY + 1, 1, doorH - 1);
  ctx.fillStyle = '#78431e';
  ctx.fillRect(doorX + 6, doorY + 1, 1, doorH - 1);
  ctx.fillStyle = '#381f10';
  ctx.fillRect(doorX + 10, doorY + 1, 1, doorH - 1);
  ctx.fillStyle = '#78431e';
  ctx.fillRect(doorX + 11, doorY + 1, 1, doorH - 1);

  // Upper recessed wood panel
  ctx.fillStyle = '#381f10';
  ctx.fillRect(doorX + 2, doorY + 3, 12, 6);
  ctx.fillStyle = '#683618';
  ctx.fillRect(doorX + 3, doorY + 4, 10, 4);

  // Gleaming polished brass door handle & escutcheon at sx + 43, sy + 54
  ctx.fillStyle = '#0f172a';
  ctx.fillRect(doorX + 11, doorY + 10, 3, 4);
  ctx.fillStyle = '#fbbf24'; // Brass handle plate
  ctx.fillRect(doorX + 12, doorY + 10, 2, 3);
  ctx.fillStyle = '#ffffff';
  ctx.fillRect(doorX + 12, doorY + 10, 1, 1); // Handle shine
  ctx.fillStyle = '#d97706';
  ctx.fillRect(doorX + 13, doorY + 12, 1, 2); // Handle lever

  // 7. Small Lantern Hung to the Left of the Door (at sx + 27, sy + 44..50)
  const lantX = doorX - 6;
  const lantY = doorY + 1;
  ctx.fillStyle = '#334155'; // Bracket
  ctx.fillRect(lantX + 3, lantY + 2, 3, 1);
  ctx.fillStyle = '#261b14'; // Lantern housing
  ctx.fillRect(lantX, lantY, 4, 6);
  ctx.fillStyle = '#fbbf24'; // Brass lantern cap
  ctx.fillRect(lantX, lantY, 4, 1);
  ctx.fillStyle = '#f59e0b'; // Amber lamp glass
  ctx.fillRect(lantX + 1, lantY + 1, 2, 4);
  ctx.fillStyle = '#fef08a'; // Glowing wick
  ctx.fillRect(lantX + 1, lantY + 2, 2, 2);
  ctx.fillStyle = '#ffffff';
  ctx.fillRect(lantX + 1, lantY + 2, 1, 1);

  // Soft gentle lantern glow
  const lGlow = ctx.createRadialGradient(lantX + 2, lantY + 3, 1, lantX + 2, lantY + 3, 12);
  lGlow.addColorStop(0, 'rgba(254, 240, 138, 0.40)');
  lGlow.addColorStop(0.5, 'rgba(251, 191, 36, 0.15)');
  lGlow.addColorStop(1, 'rgba(245, 158, 11, 0)');
  ctx.fillStyle = lGlow;
  ctx.beginPath();
  ctx.arc(lantX + 2, lantY + 3, 12, 0, Math.PI * 2);
  ctx.fill();

  // 8. Clean Woven Coir Doormat Directly on the Sand at (X: 26, Y: 20)
  // Sits right outside the door threshold from sy + 64 to sy + 73 (doorstep)
  const matX = doorX - 1; // sx + 31
  const matY = sy + 64;   // Row Y: 20
  const matW = 18;
  const matH = 7;

  // Soft mat shadow on sand
  ctx.fillStyle = 'rgba(70, 50, 30, 0.25)';
  ctx.fillRect(matX, matY + 1, matW + 1, matH);

  // Woven coir doorstep mat (#C29B38 / #D4AF37)
  ctx.fillStyle = '#78531e'; // Mat border
  ctx.fillRect(matX, matY, matW, matH);
  ctx.fillStyle = '#C29B38'; // Coir mat base
  ctx.fillRect(matX + 1, matY + 1, matW - 2, matH - 2);
  ctx.fillStyle = '#D4AF37'; // Woven fiber texture
  for (let mx = matX + 2; mx < matX + matW - 2; mx += 3) {
    ctx.fillRect(mx, matY + 2, 1, matH - 4);
    ctx.fillRect(mx + 1, matY + 3, 1, matH - 5);
  }

  ctx.restore();
}

export function drawLighthouseBeacon(
  ctx: CanvasRenderingContext2D,
  camX: number,
  camY: number,
  animTime: number,
) {
  // Spanning X: 32..34 (48px wide), Y: 14..18 (shifted upward by 18px so base rests on beach at Y ≈ 18.5..19)
  const worldX = 32 * TILE_SIZE; // 512
  const worldY = 15 * TILE_SIZE - 18; // 222px (~13.875 tiles)
  const sx = Math.round(worldX - camX);
  const sy = Math.round(worldY - camY);
  const w = 3 * TILE_SIZE; // 48
  const h = 6 * TILE_SIZE; // 96

  if (sx < -w - 40 || sx > VIEWPORT_WIDTH + 40 || sy < -h - 40 || sy > VIEWPORT_HEIGHT + 40) {
    return;
  }

  ctx.save();
  ctx.imageSmoothingEnabled = false;

  const centerX = sx + 24;

  // 1. Soft rounded contact shadow on sand/headland at base
  ctx.fillStyle = 'rgba(45, 35, 25, 0.28)';
  ctx.beginPath();
  ctx.ellipse(centerX, sy + h - 1, 22, 5, 0, 0, Math.PI * 2);
  ctx.fill();

  // 2. Sturdy, dark-granite coastal masonry base at Y: 20 (sy + 80 to sy + 96)
  // Anchored solidly into the rocky headland
  ctx.fillStyle = '#1e293b';
  ctx.beginPath();
  ctx.moveTo(centerX - 18, sy + 80);
  ctx.lineTo(centerX + 18, sy + 80);
  ctx.lineTo(centerX + 20, sy + 96);
  ctx.lineTo(centerX - 20, sy + 96);
  ctx.closePath();
  ctx.fill();

  ctx.fillStyle = '#334155';
  ctx.beginPath();
  ctx.moveTo(centerX - 17, sy + 81);
  ctx.lineTo(centerX + 17, sy + 81);
  ctx.lineTo(centerX + 19, sy + 95);
  ctx.lineTo(centerX - 19, sy + 95);
  ctx.closePath();
  ctx.fill();

  // Chiseled ashlar granite blocks & mortar seams
  ctx.fillStyle = '#475569';
  ctx.fillRect(centerX - 16, sy + 82, 32, 2);
  ctx.fillStyle = '#64748b';
  ctx.fillRect(centerX - 15, sy + 82, 14, 1);
  ctx.fillStyle = '#1e293b';
  ctx.fillRect(centerX - 17, sy + 87, 34, 1);
  ctx.fillRect(centerX - 18, sy + 92, 36, 1);
  ctx.fillRect(centerX - 8, sy + 82, 1, 5);
  ctx.fillRect(centerX + 6, sy + 82, 1, 5);
  ctx.fillRect(centerX - 3, sy + 87, 1, 5);
  ctx.fillRect(centerX - 11, sy + 92, 1, 4);
  ctx.fillRect(centerX + 8, sy + 92, 1, 4);
  ctx.fillStyle = '#65a30d';
  ctx.fillRect(centerX - 17, sy + 93, 2, 2);
  ctx.fillRect(centerX + 15, sy + 94, 2, 2);
  ctx.fillStyle = '#cbd5e1';
  ctx.fillRect(centerX - 15, sy + 88, 2, 1);

  // Arched heavy dark oak service doorway in base facing sand
  const dX = centerX - 4;
  const dY = sy + 84;
  ctx.fillStyle = '#0f172a';
  ctx.fillRect(dX - 1, dY - 1, 10, 13);
  ctx.fillStyle = '#64748b';
  ctx.fillRect(dX, dY - 1, 8, 2);
  ctx.fillStyle = '#94a3b8';
  ctx.fillRect(dX + 3, dY - 2, 2, 2);
  ctx.fillStyle = '#381c08';
  ctx.fillRect(dX, dY + 1, 8, 11);
  ctx.fillStyle = '#542c16';
  ctx.fillRect(dX + 1, dY + 2, 6, 9);
  ctx.fillStyle = '#0f172a';
  ctx.fillRect(dX + 1, dY + 3, 6, 1);
  ctx.fillRect(dX + 1, dY + 8, 6, 1);
  ctx.fillStyle = '#fbbf24';
  ctx.fillRect(dX + 5, dY + 6, 2, 2);

  // 3. Grand, tapered whitewashed stone tower with classic alternating crimson-red bands (Y: 16..19, sy + 32 to sy + 80)
  const towerTopW = 20;
  const towerBottomW = 34;
  const towerTopY = sy + 32;
  const towerBottomY = sy + 80;
  const towerH = 48;

  ctx.fillStyle = '#0f172a';
  ctx.beginPath();
  ctx.moveTo(centerX - towerTopW / 2 - 1, towerTopY);
  ctx.lineTo(centerX + towerTopW / 2 + 1, towerTopY);
  ctx.lineTo(centerX + towerBottomW / 2 + 1, towerBottomY);
  ctx.lineTo(centerX - towerBottomW / 2 - 1, towerBottomY);
  ctx.closePath();
  ctx.fill();

  const towerBands = [
    { y1: towerTopY, y2: towerTopY + 12, col: '#f8fafc', hi: '#ffffff', sh: '#cbd5e1', deepSh: '#94a3b8' },
    { y1: towerTopY + 12, y2: towerTopY + 24, col: '#dc2626', hi: '#ef4444', sh: '#991b1b', deepSh: '#7f1d1d' },
    { y1: towerTopY + 24, y2: towerTopY + 36, col: '#f8fafc', hi: '#ffffff', sh: '#cbd5e1', deepSh: '#94a3b8' },
    { y1: towerTopY + 36, y2: towerBottomY, col: '#dc2626', hi: '#ef4444', sh: '#991b1b', deepSh: '#7f1d1d' },
  ];

  towerBands.forEach((band) => {
    const p1 = (band.y1 - towerTopY) / towerH;
    const p2 = (band.y2 - towerTopY) / towerH;
    const w1 = towerTopW + (towerBottomW - towerTopW) * p1;
    const w2 = towerTopW + (towerBottomW - towerTopW) * p2;

    ctx.fillStyle = band.col;
    ctx.beginPath();
    ctx.moveTo(centerX - w1 / 2, band.y1);
    ctx.lineTo(centerX + w1 / 2, band.y1);
    ctx.lineTo(centerX + w2 / 2, band.y2);
    ctx.lineTo(centerX - w2 / 2, band.y2);
    ctx.closePath();
    ctx.fill();

    // Western highlight
    ctx.fillStyle = band.hi;
    ctx.beginPath();
    ctx.moveTo(centerX - w1 / 2 + 1, band.y1);
    ctx.lineTo(centerX - w1 / 2 + 6, band.y1);
    ctx.lineTo(centerX - w2 / 2 + 8, band.y2);
    ctx.lineTo(centerX - w2 / 2 + 1, band.y2);
    ctx.closePath();
    ctx.fill();

    // Eastern shadow
    ctx.fillStyle = band.sh;
    ctx.beginPath();
    ctx.moveTo(centerX + w1 / 2 - 5, band.y1);
    ctx.lineTo(centerX + w1 / 2, band.y1);
    ctx.lineTo(centerX + w2 / 2, band.y2);
    ctx.lineTo(centerX + w2 / 2 - 6, band.y2);
    ctx.closePath();
    ctx.fill();

    ctx.fillStyle = band.deepSh;
    ctx.beginPath();
    ctx.moveTo(centerX + w1 / 2 - 2, band.y1);
    ctx.lineTo(centerX + w1 / 2, band.y1);
    ctx.lineTo(centerX + w2 / 2, band.y2);
    ctx.lineTo(centerX + w2 / 2 - 2, band.y2);
    ctx.closePath();
    ctx.fill();
  });

  // Windows in tower
  const w1Y = towerTopY + 4;
  ctx.fillStyle = '#0f172a';
  ctx.fillRect(centerX - 3, w1Y, 6, 7);
  ctx.fillStyle = '#64748b';
  ctx.fillRect(centerX - 3, w1Y, 6, 1);
  ctx.fillStyle = '#38bdf8';
  ctx.fillRect(centerX - 2, w1Y + 1, 4, 5);
  ctx.fillStyle = '#7dd3fc';
  ctx.fillRect(centerX - 1, w1Y + 2, 2, 2);
  ctx.fillStyle = '#0f172a';
  ctx.fillRect(centerX - 1, w1Y + 1, 1, 5);

  const w2Y = towerTopY + 28;
  ctx.fillStyle = '#0f172a';
  ctx.fillRect(centerX - 3, w2Y, 6, 7);
  ctx.fillStyle = '#64748b';
  ctx.fillRect(centerX - 3, w2Y, 6, 1);
  ctx.fillStyle = '#38bdf8';
  ctx.fillRect(centerX - 2, w2Y + 1, 4, 5);
  ctx.fillStyle = '#7dd3fc';
  ctx.fillRect(centerX - 1, w2Y + 2, 2, 2);
  ctx.fillStyle = '#0f172a';
  ctx.fillRect(centerX - 1, w2Y + 1, 1, 5);

  // 4. Black wrought-iron catwalk railing and gallery deck at Y: 16 (sy + 26..32)
  const deckY = sy + 29;
  const deckW = 34;

  // Corbels supporting deck
  ctx.fillStyle = '#1e293b';
  ctx.fillRect(centerX - 14, deckY + 2, 4, 3);
  ctx.fillRect(centerX - 5, deckY + 2, 3, 3);
  ctx.fillRect(centerX + 2, deckY + 2, 3, 3);
  ctx.fillRect(centerX + 10, deckY + 2, 4, 3);
  ctx.fillStyle = '#475569';
  ctx.fillRect(centerX - 14, deckY + 2, 3, 1);
  ctx.fillRect(centerX - 5, deckY + 2, 2, 1);
  ctx.fillRect(centerX + 2, deckY + 2, 2, 1);
  ctx.fillRect(centerX + 10, deckY + 2, 3, 1);

  // Gallery Deck platform
  ctx.fillStyle = '#0f172a';
  ctx.fillRect(centerX - deckW / 2, deckY, deckW, 3);
  ctx.fillStyle = '#334155';
  ctx.fillRect(centerX - deckW / 2 + 1, deckY, deckW - 2, 2);
  ctx.fillStyle = '#64748b';
  ctx.fillRect(centerX - deckW / 2 + 1, deckY, deckW - 2, 1);

  // Black wrought-iron catwalk railing
  const railTopY = sy + 25;
  ctx.fillStyle = '#0f172a';
  ctx.fillRect(centerX - deckW / 2, railTopY, deckW, 1);
  ctx.fillStyle = '#475569';
  ctx.fillRect(centerX - deckW / 2 + 1, railTopY, deckW - 2, 1);
  ctx.fillStyle = '#0f172a';
  for (let rx = centerX - deckW / 2 + 1; rx <= centerX + deckW / 2 - 1; rx += 3) {
    ctx.fillRect(rx, railTopY, 1, deckY - railTopY);
  }

  // 5. Taller, glass-paneled lantern room housing glowing golden-amber Fresnel lens (sy + 14..26)
  const roomW = 22;
  const roomH = 13;
  const roomY = sy + 16;

  ctx.fillStyle = '#0f172a';
  ctx.fillRect(centerX - roomW / 2 - 1, roomY - 1, roomW + 2, roomH + 2);
  ctx.fillStyle = '#1e293b';
  ctx.fillRect(centerX - roomW / 2, roomY, roomW, roomH);

  ctx.fillStyle = '#fef08a';
  ctx.fillRect(centerX - roomW / 2 + 1, roomY + 1, roomW - 2, roomH - 2);

  // Cast-iron astragals
  ctx.fillStyle = '#0f172a';
  ctx.fillRect(centerX - 6, roomY, 1, roomH);
  ctx.fillRect(centerX, roomY, 1, roomH);
  ctx.fillRect(centerX + 6, roomY, 1, roomH);
  ctx.fillRect(centerX - roomW / 2 + 1, roomY + Math.round(roomH / 2), roomW - 2, 1);

  // Fresnel lens core
  const lensX = centerX;
  const lensY = roomY + Math.round(roomH / 2);
  ctx.fillStyle = '#f59e0b';
  ctx.fillRect(lensX - 4, lensY - 4, 8, 8);
  ctx.fillStyle = '#fef08a';
  ctx.fillRect(lensX - 3, lensY - 3, 6, 6);
  ctx.fillStyle = '#ffffff';
  ctx.fillRect(lensX - 1, lensY - 1, 2, 2);

  // Soft ambient warm beacon halo (rgba(255, 220, 120, 0.2))
  const breatheProgress = 0.5 + 0.5 * Math.sin(animTime * 1.5);
  const glowAlpha = 0.15 + 0.07 * breatheProgress;

  const beaconGlow = ctx.createRadialGradient(lensX, lensY, 2, lensX, lensY, 36);
  beaconGlow.addColorStop(0, `rgba(255, 240, 160, ${glowAlpha * 1.5})`);
  beaconGlow.addColorStop(0.4, `rgba(255, 220, 120, ${glowAlpha})`);
  beaconGlow.addColorStop(0.75, 'rgba(251, 191, 36, 0.04)');
  beaconGlow.addColorStop(1, 'rgba(245, 158, 11, 0)');
  ctx.fillStyle = beaconGlow;
  ctx.beginPath();
  ctx.arc(lensX, lensY, 36, 0, Math.PI * 2);
  ctx.fill();

  // 6. Copper/slate conical roof crowned with brass spire / weathervane at Y: 15 (sy + 0..16)
  const roofBaseY = sy + 16;
  const roofApexY = sy + 6;
  const roofBaseW = 26;

  ctx.fillStyle = '#0f172a';
  ctx.beginPath();
  ctx.moveTo(centerX - roofBaseW / 2 - 1, roofBaseY + 1);
  ctx.lineTo(centerX + roofBaseW / 2 + 1, roofBaseY + 1);
  ctx.lineTo(centerX + 2, roofApexY - 1);
  ctx.lineTo(centerX - 2, roofApexY - 1);
  ctx.closePath();
  ctx.fill();

  ctx.fillStyle = '#334155';
  ctx.beginPath();
  ctx.moveTo(centerX - roofBaseW / 2, roofBaseY);
  ctx.lineTo(centerX + roofBaseW / 2, roofBaseY);
  ctx.lineTo(centerX + 1, roofApexY);
  ctx.lineTo(centerX - 1, roofApexY);
  ctx.closePath();
  ctx.fill();

  ctx.fillStyle = '#475569';
  ctx.beginPath();
  ctx.moveTo(centerX - roofBaseW / 2 + 1, roofBaseY);
  ctx.lineTo(centerX, roofBaseY);
  ctx.lineTo(centerX, roofApexY);
  ctx.lineTo(centerX - 1, roofApexY);
  ctx.closePath();
  ctx.fill();

  ctx.fillStyle = '#64748b';
  ctx.beginPath();
  ctx.moveTo(centerX - roofBaseW / 2 + 2, roofBaseY);
  ctx.lineTo(centerX - roofBaseW / 2 + 6, roofBaseY);
  ctx.lineTo(centerX - 1, roofApexY);
  ctx.closePath();
  ctx.fill();

  ctx.fillStyle = '#0d9488';
  ctx.fillRect(centerX - 5, roofBaseY - 3, 2, 2);
  ctx.fillRect(centerX + 4, roofBaseY - 4, 2, 2);
  ctx.fillStyle = '#2dd4bf';
  ctx.fillRect(centerX - 5, roofBaseY - 3, 1, 1);

  ctx.fillStyle = '#1e293b';
  ctx.fillRect(centerX - roofBaseW / 2 - 1, roofBaseY, roofBaseW + 2, 2);
  ctx.fillStyle = '#64748b';
  ctx.fillRect(centerX - roofBaseW / 2, roofBaseY, roofBaseW, 1);

  // Brass finial ball & spire
  ctx.fillStyle = '#d97706';
  ctx.fillRect(centerX - 2, roofApexY - 1, 4, 2);
  ctx.fillStyle = '#fbbf24';
  ctx.fillRect(centerX - 2, roofApexY - 1, 4, 1);

  ctx.fillStyle = '#d97706';
  ctx.fillRect(centerX - 1, sy + 1, 2, 5);
  ctx.fillStyle = '#fbbf24';
  ctx.fillRect(centerX - 1, sy, 2, 2);
  ctx.fillStyle = '#ffffff';
  ctx.fillRect(centerX, sy, 1, 1);

  // Weathervane
  ctx.fillStyle = '#fbbf24';
  ctx.fillRect(centerX - 4, sy + 3, 8, 1);
  ctx.fillStyle = '#fef08a';
  ctx.fillRect(centerX + 3, sy + 2, 2, 3);

  ctx.restore();
}

export function drawShipwreckRibs(
  ctx: CanvasRenderingContext2D,
  camX: number,
  camY: number,
  animTime: number,
) {
  // Grounded firmly across the surf-line (Row 20 sand, Row 21 shallow surf)
  const worldX = 30 * TILE_SIZE; // 480
  const worldY = 20 * TILE_SIZE; // 320
  const sx = Math.round(worldX - camX);
  const sy = Math.round(worldY - camY);
  const w = 24;
  const h = 32;

  if (sx < -w - 20 || sx > VIEWPORT_WIDTH + 20 || sy < -h - 20 || sy > VIEWPORT_HEIGHT + 20) {
    return;
  }

  ctx.save();
  ctx.imageSmoothingEnabled = false;

  // 1. Wet sand depression & embedded keel shadow
  ctx.fillStyle = 'rgba(55, 42, 30, 0.35)';
  ctx.beginPath();
  ctx.ellipse(sx + 8, sy + 16, 12, 4.5, -0.2, 0, Math.PI * 2);
  ctx.fill();

  // 2. Partially buried keel spine timber running along wet sand & surf (sy + 12 to sy + 26)
  ctx.fillStyle = '#261b14'; // Dark waterlogged keel timber
  ctx.beginPath();
  ctx.moveTo(sx - 3, sy + 14);
  ctx.lineTo(sx + 18, sy + 22);
  ctx.lineTo(sx + 16, sy + 26);
  ctx.lineTo(sx - 5, sy + 17);
  ctx.closePath();
  ctx.fill();

  ctx.fillStyle = '#4a382a'; // Aged keel timber highlight
  ctx.beginPath();
  ctx.moveTo(sx - 3, sy + 14);
  ctx.lineTo(sx + 17, sy + 22);
  ctx.lineTo(sx + 16, sy + 23);
  ctx.lineTo(sx - 4, sy + 15);
  ctx.closePath();
  ctx.fill();

  // 3. Four Well-Defined, Weathered Bleached-Oak Timber Ribs arching gracefully from the keel:
  // Bleached-oak palette:
  // Shadow/rot: #2d241c
  // Deep grain: #54473b
  // Midtone bleached oak: #7d6f60
  // Sunlit bleached wood: #9c8e7e
  // Salt-crusted top highlights: #c9bfb2

  // Rib 1 (Foremost rib, x: ~0..6, rising from sy + 16 to sy + 6)
  ctx.fillStyle = '#1c1510';
  ctx.beginPath();
  ctx.moveTo(sx - 3, sy + 16);
  ctx.quadraticCurveTo(sx + 5, sy + 12, sx + 4, sy + 6);
  ctx.quadraticCurveTo(sx + 1, sy + 10, sx - 4, sy + 16);
  ctx.closePath();
  ctx.fill();

  ctx.fillStyle = '#7d6f60';
  ctx.beginPath();
  ctx.moveTo(sx - 3, sy + 15);
  ctx.quadraticCurveTo(sx + 4, sy + 12, sx + 3, sy + 6);
  ctx.quadraticCurveTo(sx + 1, sy + 10, sx - 3, sy + 15);
  ctx.closePath();
  ctx.fill();

  ctx.fillStyle = '#c9bfb2'; // Salt-bleached rib tip
  ctx.fillRect(sx + 3, sy + 6, 2, 2);

  // Rib 2 (Main central rib, x: ~4..12, tallest arch rising from sy + 20 to sy + 1)
  ctx.fillStyle = '#1c1510';
  ctx.beginPath();
  ctx.moveTo(sx + 3, sy + 20);
  ctx.quadraticCurveTo(sx + 13, sy + 13, sx + 11, sy + 2);
  ctx.quadraticCurveTo(sx + 7, sy + 10, sx + 2, sy + 19);
  ctx.closePath();
  ctx.fill();

  ctx.fillStyle = '#7d6f60';
  ctx.beginPath();
  ctx.moveTo(sx + 2, sy + 19);
  ctx.quadraticCurveTo(sx + 12, sy + 12, sx + 10, sy + 2);
  ctx.quadraticCurveTo(sx + 7, sy + 10, sx + 2, sy + 18);
  ctx.closePath();
  ctx.fill();

  ctx.fillStyle = '#9c8e7e';
  ctx.beginPath();
  ctx.moveTo(sx + 3, sy + 18);
  ctx.quadraticCurveTo(sx + 11, sy + 12, sx + 10, sy + 3);
  ctx.lineTo(sx + 9, sy + 4);
  ctx.closePath();
  ctx.fill();

  ctx.fillStyle = '#c9bfb2'; // Salt-bleached rib crest
  ctx.fillRect(sx + 9, sy + 2, 2, 2);
  ctx.fillStyle = '#ffffff';
  ctx.fillRect(sx + 10, sy + 2, 1, 1);

  // Rib 3 (Mid-aft rib, x: ~10..18, rising from sy + 23 to sy + 7)
  ctx.fillStyle = '#1c1510';
  ctx.beginPath();
  ctx.moveTo(sx + 9, sy + 24);
  ctx.quadraticCurveTo(sx + 19, sy + 18, sx + 17, sy + 8);
  ctx.quadraticCurveTo(sx + 14, sy + 15, sx + 8, sy + 23);
  ctx.closePath();
  ctx.fill();

  ctx.fillStyle = '#7d6f60';
  ctx.beginPath();
  ctx.moveTo(sx + 8, sy + 23);
  ctx.quadraticCurveTo(sx + 18, sy + 17, sx + 16, sy + 8);
  ctx.quadraticCurveTo(sx + 13, sy + 15, sx + 8, sy + 22);
  ctx.closePath();
  ctx.fill();

  ctx.fillStyle = '#c9bfb2';
  ctx.fillRect(sx + 16, sy + 8, 2, 2);

  // Rib 4 (Aft rib / fractured timber knee, x: ~14..20, rising to sy + 14)
  ctx.fillStyle = '#1c1510';
  ctx.beginPath();
  ctx.moveTo(sx + 14, sy + 26);
  ctx.quadraticCurveTo(sx + 21, sy + 21, sx + 20, sy + 14);
  ctx.quadraticCurveTo(sx + 17, sy + 18, sx + 13, sy + 25);
  ctx.closePath();
  ctx.fill();

  ctx.fillStyle = '#7d6f60';
  ctx.beginPath();
  ctx.moveTo(sx + 14, sy + 25);
  ctx.quadraticCurveTo(sx + 20, sy + 20, sx + 19, sy + 14);
  ctx.lineTo(sx + 18, sy + 16);
  ctx.closePath();
  ctx.fill();

  ctx.fillStyle = '#c9bfb2';
  ctx.fillRect(sx + 19, sy + 14, 2, 2);

  // 4. Weathered copper drift-bolts with verdigris patina
  ctx.fillStyle = '#0f766e'; // Verdigris dark
  ctx.fillRect(sx, sy + 13, 2, 2);
  ctx.fillRect(sx + 7, sy + 12, 2, 2);
  ctx.fillRect(sx + 14, sy + 17, 2, 2);
  ctx.fillStyle = '#2dd4bf'; // Verdigris light glint
  ctx.fillRect(sx, sy + 13, 1, 1);
  ctx.fillRect(sx + 7, sy + 12, 1, 1);

  // 5. White/slate barnacle clusters on lower timbers near waterline
  ctx.fillStyle = '#e2e8f0';
  ctx.fillRect(sx, sy + 16, 2, 1);
  ctx.fillRect(sx + 5, sy + 20, 2, 2);
  ctx.fillRect(sx + 11, sy + 23, 2, 2);
  ctx.fillStyle = '#64748b';
  ctx.fillRect(sx + 1, sy + 17, 1, 1);
  ctx.fillRect(sx + 6, sy + 21, 1, 1);

  // 6. Strands of dark green seaweed / bladderwrack clinging to lower wood
  ctx.fillStyle = '#14532d';
  ctx.fillRect(sx + 1, sy + 21, 2, 5);
  ctx.fillRect(sx + 7, sy + 24, 3, 5);
  ctx.fillRect(sx + 13, sy + 26, 2, 4);
  ctx.fillStyle = '#166534';
  ctx.fillRect(sx + 2, sy + 22, 1, 3);
  ctx.fillRect(sx + 8, sy + 25, 2, 3);

  // 7. Dynamic translucent foam ripples lapping against aged wood
  const foamWave = Math.sin(animTime * 2.2) * 1.5;
  ctx.fillStyle = 'rgba(232, 248, 255, 0.60)';
  ctx.fillRect(sx - 2, sy + 24 + Math.round(foamWave), 22, 1);
  ctx.fillStyle = 'rgba(186, 230, 253, 0.40)';
  ctx.fillRect(sx + 1, sy + 26 - Math.round(foamWave * 0.5), 18, 1);

  ctx.restore();
}

export function drawTidepoolRocks(
  ctx: CanvasRenderingContext2D,
  camX: number,
  camY: number,
  animTime: number,
) {
  const poolWorldX = 31 * TILE_SIZE; // 496
  const poolWorldY = 19 * TILE_SIZE; // 304
  const px = Math.round(poolWorldX - camX);
  const py = Math.round(poolWorldY - camY);

  if (px < -30 || px > VIEWPORT_WIDTH + 30 || py < -30 || py > VIEWPORT_HEIGHT + 30) {
    return;
  }

  ctx.save();
  ctx.imageSmoothingEnabled = false;

  // 1. Natural shallow tidepool puddle with smooth, organic edges (no weird circular mask/border!)
  // Wet sand depression blending naturally into beach sand
  ctx.fillStyle = 'rgba(180, 150, 100, 0.35)';
  ctx.beginPath();
  ctx.ellipse(px + 8, py + 8, 9, 5, -0.15, 0, Math.PI * 2);
  ctx.fill();

  // Shallow crystal-clear seawater puddle with organic soft shape
  ctx.fillStyle = 'rgba(52, 136, 220, 0.32)';
  ctx.beginPath();
  ctx.ellipse(px + 8, py + 8, 7.5, 4, -0.15, 0, Math.PI * 2);
  ctx.fill();

  // Subtle translucent surface water shimmer
  const wave = Math.sin(animTime * 2.0) * 0.5;
  ctx.fillStyle = 'rgba(224, 245, 255, 0.38)';
  ctx.fillRect(px + 5, py + 7 + Math.round(wave), 4, 1);
  ctx.fillRect(px + 7, py + 9 - Math.round(wave), 3, 1);

  // Smooth tiny grey beach pebbles nestled naturally around the puddle
  ctx.fillStyle = '#475569';
  ctx.fillRect(px + 2, py + 6, 2, 2);
  ctx.fillStyle = '#94a3b8';
  ctx.fillRect(px + 2, py + 6, 1, 1);

  ctx.fillStyle = '#334155';
  ctx.fillRect(px + 13, py + 8, 3, 2);
  ctx.fillStyle = '#64748b';
  ctx.fillRect(px + 14, py + 8, 2, 1);

  ctx.fillStyle = '#64748b';
  ctx.fillRect(px + 4, py + 11, 2, 1);

  // Tiny dark green seaweed frond
  ctx.fillStyle = '#15803d';
  ctx.fillRect(px + 12, py + 6, 2, 2);
  ctx.fillStyle = '#166534';
  ctx.fillRect(px + 13, py + 7, 1, 1);

  // 2. Delightful pixel-art sea-frosted emerald bottle resting naturally in the shallow water
  const bottleWorldX = 31 * TILE_SIZE + 7;
  const bottleWorldY = 19 * TILE_SIZE + 7;
  const bsx = Math.round(bottleWorldX - camX);
  const bsy = Math.round(bottleWorldY - camY);

  const bob = Math.sin(animTime * 2.0) * 0.5;
  const tilt = 0.28 + Math.sin(animTime * 1.4) * 0.04; // Natural resting tilt ~16 degrees

  ctx.save();
  ctx.translate(bsx, bsy + bob);
  ctx.rotate(tilt);

  // Soft bottle shadow in wet sand
  ctx.fillStyle = 'rgba(30, 45, 35, 0.30)';
  ctx.fillRect(-2, 4, 5, 2);

  // Sea-frosted emerald bottle body (5px wide, 8px tall)
  ctx.fillStyle = '#064e3b'; // Deep emerald glass shadow
  ctx.fillRect(-2, -3, 5, 8);
  ctx.fillStyle = '#059669'; // Sea-frosted emerald glass body
  ctx.fillRect(-1, -2, 3, 6);
  ctx.fillStyle = '#10b981'; // Luminous emerald midtone
  ctx.fillRect(-1, -2, 2, 5);

  // Sea-frosted translucent gleam on left shoulder
  ctx.fillStyle = '#6ee7b7';
  ctx.fillRect(-1, -2, 1, 4);
  ctx.fillStyle = '#ffffff'; // Delicate specular sky reflection
  ctx.fillRect(-1, -1, 1, 2);

  // Curled parchment coil visible inside the green glass
  ctx.fillStyle = '#fef3c7'; // Cream rolled vellum
  ctx.fillRect(0, -1, 1, 4);
  ctx.fillStyle = '#fde68a';
  ctx.fillRect(0, 0, 1, 2);
  ctx.fillStyle = '#78350f'; // Faint line of aged ink on the parchment coil
  ctx.fillRect(0, 1, 1, 1);

  // Slender bottle neck & rounded lip
  ctx.fillStyle = '#064e3b';
  ctx.fillRect(-1, -5, 3, 3);
  ctx.fillStyle = '#059669';
  ctx.fillRect(0, -5, 1, 2);
  ctx.fillStyle = '#6ee7b7';
  ctx.fillRect(-1, -5, 1, 1); // Glass lip glint

  // Weathered cork stopper with a touch of sealing wax
  ctx.fillStyle = '#b45309'; // Cork body
  ctx.fillRect(-1, -7, 3, 2);
  ctx.fillStyle = '#d97706'; // Cork highlight
  ctx.fillRect(0, -7, 1, 2);
  ctx.fillStyle = '#991b1b'; // Red sealing pitch dot
  ctx.fillRect(0, -8, 1, 1);

  ctx.restore();
  ctx.restore();
}

// 1. Water slipway underbody with clean, calm deep blue water, gentle subtle wave ripples, and lush aquatic vegetation
export function drawBoathouseWaterSlip(
  ctx: CanvasRenderingContext2D,
  camX: number,
  camY: number,
  animTime: number,
) {
  const now = typeof animTime === 'number' && animTime > 0 ? animTime * 1000 : Date.now();
  const nowSec = now / 1000;

  ctx.save();
  ctx.imageSmoothingEnabled = false;

  ctx.fillStyle = 'rgba(40, 20, 10, 0.15)';
  ctx.fillRect(0, 0, VIEWPORT_WIDTH, VIEWPORT_HEIGHT);

  const slipX = 5 * TILE_SIZE - camX;
  const slipY = 4 * TILE_SIZE - camY;
  const slipW = 6 * TILE_SIZE; // 96px
  const slipH = 5 * TILE_SIZE; // 80px

  // Clean, calm deep blue water slipway
  const slipGrad = ctx.createLinearGradient(0, slipY, 0, slipY + slipH);
  slipGrad.addColorStop(0.0, '#1B4360');
  slipGrad.addColorStop(0.3, '#1E4A68');
  slipGrad.addColorStop(0.65, '#193A54');
  slipGrad.addColorStop(1.0, '#16324A');
  ctx.fillStyle = slipGrad;
  ctx.fillRect(slipX, slipY, slipW, slipH);

  // Gentle horizontal water wavelets
  for (let i = 0; i < 5; i++) {
    const cyBase = slipY + 10 + i * 14;
    const wavePhase = (now / 4000) + i * 1.2;
    ctx.strokeStyle = 'rgba(125, 211, 252, 0.16)';
    ctx.lineWidth = 1.2;
    ctx.beginPath();
    for (let x = 0; x <= slipW - 8; x += 4) {
      const wx = slipX + 4 + x;
      const wy = cyBase + Math.sin(wavePhase + x * 0.08) * 1.8;
      if (x === 0) ctx.moveTo(wx, wy);
      else ctx.lineTo(wx, wy);
    }
    ctx.stroke();
  }

  // =========================================================================
  // AQUATIC VEGETATION IN THE WATER SLIPWAY HOLD
  // - Swaying emerald eelgrass/ribbon kelp anchored along corners/edges
  //   (e.g. at slipX + 16, slipY + 16, slipX + slipW - 20, slipY + 18, and along submerged pilings)
  // - Slender green kelp blades (#1E5E3A, #2F855A, #48BB78) that sway gently with water currents (Math.sin(now / 1800 + i))
  // - Small floating sea-foam/duckweed specks near timber edges
  // =========================================================================
  const kelpAnchors = [
    { x: slipX + 16, y: slipY + 16, len: 26, blades: 3 },
    { x: slipX + slipW - 20, y: slipY + 18, len: 24, blades: 3 },
    { x: slipX + 8, y: slipY + 8, len: 22, blades: 2 },
    { x: slipX + slipW - 10, y: slipY + 10, len: 25, blades: 2 },
    { x: slipX + 10, y: slipY + slipH - 12, len: 20, blades: 2 },
    { x: slipX + slipW - 12, y: slipY + slipH - 12, len: 22, blades: 2 },
    { x: slipX + 28, y: slipY + 8, len: 18, blades: 2 },
    { x: slipX + slipW - 28, y: slipY + 8, len: 19, blades: 2 },
  ];

  let kelpBladeIdx = 0;
  kelpAnchors.forEach((plant) => {
    for (let b = 0; b < plant.blades; b++) {
      const i = kelpBladeIdx++;
      const bladeLen = plant.len + (b * 3 - 2);
      const angleOffset = (b - (plant.blades - 1) / 2) * 0.25;
      const segments = 5;
      const segLen = bladeLen / segments;

      ctx.save();
      ctx.lineCap = 'round';
      let prevX = plant.x + b * 2;
      let prevY = plant.y;

      for (let s = 1; s <= segments; s++) {
        const segRatio = s / segments;
        // Sway gently with water currents (Math.sin(now / 1800 + i))
        const sway = Math.sin(now / 1800 + i + segRatio * 1.3) * (3.5 * segRatio);
        const curX = (plant.x + b * 2) + Math.sin(angleOffset) * (s * segLen) + sway;
        const curY = plant.y + Math.cos(angleOffset) * (s * segLen);

        ctx.beginPath();
        ctx.moveTo(prevX, prevY);
        ctx.lineTo(curX, curY);

        if (s <= 2) {
          ctx.strokeStyle = '#1E5E3A'; // Dark green base
          ctx.lineWidth = 1.8;
        } else if (s <= 4) {
          ctx.strokeStyle = '#2F855A'; // Mid blade
          ctx.lineWidth = 1.3;
        } else {
          ctx.strokeStyle = '#48BB78'; // Tip highlight
          ctx.lineWidth = 0.9;
        }
        ctx.stroke();

        prevX = curX;
        prevY = curY;
      }
      ctx.restore();
    }
  });

  // Floating duckweed & sea-foam specks near timber edges
  const floatingSpecks = [
    { x: slipX + 6, y: slipY + 5, r: 1.8, col: '#2F855A' },
    { x: slipX + 12, y: slipY + 6, r: 1.4, col: '#48BB78' },
    { x: slipX + 22, y: slipY + 4, r: 1.3, col: '#E0F2FE' }, // sea-foam speck
    { x: slipX + slipW - 7, y: slipY + 5, r: 1.6, col: '#2F855A' },
    { x: slipX + slipW - 14, y: slipY + 6, r: 1.3, col: '#48BB78' },
    { x: slipX + slipW - 22, y: slipY + 4, r: 1.2, col: '#E0F2FE' },
    { x: slipX + 6, y: slipY + slipH - 6, r: 1.6, col: '#2F855A' },
    { x: slipX + 11, y: slipY + slipH - 5, r: 1.2, col: '#48BB78' },
    { x: slipX + slipW - 8, y: slipY + slipH - 6, r: 1.5, col: '#2F855A' },
    { x: slipX + slipW - 15, y: slipY + slipH - 5, r: 1.2, col: '#E0F2FE' },
  ];

  floatingSpecks.forEach((sp, idx) => {
    const bob = Math.sin(now / 1800 + idx * 1.4) * 0.5;
    ctx.fillStyle = sp.col;
    ctx.beginPath();
    ctx.arc(sp.x, sp.y + bob, sp.r, 0, Math.PI * 2);
    ctx.fill();
  });

  // Poetic, Slow Water Ripples around the fish:
  // Serene 45-second leisurely cruise
  const minFishX = slipX + 22;
  const maxFishX = slipX + slipW - 22;
  const minFishY = slipY + 18;
  const maxFishY = slipY + slipH - 20;

  const centerFishX = (minFishX + maxFishX) * 0.5;
  const ampFishX = (maxFishX - minFishX) * 0.5;
  const centerFishY = (minFishY + maxFishY) * 0.5;
  const ampFishY = (maxFishY - minFishY) * 0.5;

  const cycleMs = 45000;
  const swimProgress = (now % cycleMs) / cycleMs;
  const angleX = swimProgress * Math.PI * 2;
  const angleY = swimProgress * Math.PI * 4;

  const fishX = centerFishX + Math.sin(angleX) * ampFishX;
  const fishY = centerFishY + Math.sin(angleY) * ampFishY;
  const fishCenterX = fishX + 8.0;
  const fishCenterY = fishY + 3.0;

  const ripPeriod = 11.5; // Meditative, slow ripple period
  for (let r = 0; r < 3; r++) {
    const rProgress = ((nowSec / ripPeriod + r * 0.333) % 1.0);
    const ripRadX = 4 + rProgress * 16;
    const ripRadY = 1.6 + rProgress * 5.5;
    const ripAlpha = Math.max(0, (1.0 - rProgress) * (1.0 - rProgress)) * 0.24;
    ctx.strokeStyle = `rgba(160, 220, 255, ${ripAlpha.toFixed(3)})`;
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.ellipse(fishCenterX, fishCenterY, Math.max(0.1, ripRadX), Math.max(0.1, ripRadY), 0, 0, Math.PI * 2);
    ctx.stroke();
  }

  // Timber curbs
  ctx.fillStyle = '#1e1008';
  ctx.fillRect(slipX - 2, slipY - 2, slipW + 4, 3);
  ctx.fillRect(slipX - 2, slipY, 3, slipH + 2);
  ctx.fillRect(slipX + slipW - 1, slipY, 3, slipH + 2);
  ctx.fillStyle = '#783e20';
  ctx.fillRect(slipX - 1, slipY - 1, slipW + 2, 1);
  ctx.fillRect(slipX - 1, slipY, 1, slipH);
  ctx.fillRect(slipX + slipW - 1, slipY, 1, slipH);

  // Green algae on timber edges
  ctx.fillStyle = '#1E5E3A';
  ctx.fillRect(slipX, slipY - 1, slipW, 2);
  ctx.fillStyle = '#2F855A';
  ctx.fillRect(slipX + 4, slipY - 1, 14, 1);
  ctx.fillRect(slipX + 54, slipY - 1, 20, 1);
  ctx.fillStyle = '#48BB78';
  ctx.fillRect(slipX + 8, slipY - 1, 6, 1);

  ctx.restore();
}

// 2. The Hook-Jawed Fish sprite: Sleek, hydrodynamic, poetic fish (body length ~16px, height ~5px)
// Serene 45000ms leisurely cruise, elegant forked tail fin with gentle undulating swish (Math.sin(now / 800)),
// delicate 2x2px dark eye with tiny 1px amber/gold glint
export function drawBoathouseFish(
  ctx: CanvasRenderingContext2D,
  camX: number,
  camY: number,
  animTime: number,
) {
  const now = typeof animTime === 'number' && animTime > 0 ? animTime * 1000 : Date.now();

  const slipX = 5 * TILE_SIZE - camX;
  const slipY = 4 * TILE_SIZE - camY;
  const slipW = 6 * TILE_SIZE; // 96px
  const slipH = 5 * TILE_SIZE; // 80px

  const minFishX = slipX + 22;
  const maxFishX = slipX + slipW - 22;
  const minFishY = slipY + 18;
  const maxFishY = slipY + slipH - 20;

  const centerFishX = (minFishX + maxFishX) * 0.5;
  const ampFishX = (maxFishX - minFishX) * 0.5; // ~26px
  const centerFishY = (minFishY + maxFishY) * 0.5;
  const ampFishY = (maxFishY - minFishY) * 0.5; // ~21px

  // Serene 45000ms leisurely cruise
  const cycleMs = 45000;
  const swimProgress = (now % cycleMs) / cycleMs;
  const angleX = swimProgress * Math.PI * 2;
  const angleY = swimProgress * Math.PI * 4;

  const fishX = centerFishX + Math.sin(angleX) * ampFishX;
  const fishY = centerFishY + Math.sin(angleY) * ampFishY;

  // Velocity vectors
  const vx = Math.cos(angleX) * (Math.PI * 2 * ampFishX / (cycleMs / 1000));
  const facingLeft = vx < 0 || (vx === 0 && Math.sin(angleX) > 0);

  // Elegant forked tail fin with very slow, gentle undulating swish (Math.sin(now / 800))
  const tailSwish = Math.sin(now / 800) * 1.5;
  const finFlutter = Math.sin(now / 900) * 0.5;
  const fishBob = Math.sin(now / 1400) * 0.4;

  ctx.save();
  ctx.imageSmoothingEnabled = false;
  ctx.translate(Math.round(fishX), Math.round(fishY + fishBob));

  // Flip horizontally when swimming right (sprite by default faces left)
  if (!facingLeft) {
    ctx.translate(8, 0);
    ctx.scale(-1, 1);
    ctx.translate(-8, 0);
  }

  // Underwater shadow
  ctx.fillStyle = 'rgba(6, 18, 28, 0.40)';
  ctx.beginPath();
  ctx.ellipse(8, 4.5, 8.5, 3.0, 0, 0, Math.PI * 2);
  ctx.fill();

  // A. Elegant Forked Caudal Tail Fin with gentle undulating swish (Math.sin(now / 800))
  ctx.fillStyle = '#1E2B16';
  ctx.beginPath();
  ctx.moveTo(12.0, 3.0);
  ctx.lineTo(16.0 + tailSwish, 0.8);
  ctx.lineTo(14.0 + tailSwish * 0.6, 3.0);
  ctx.lineTo(16.0 + tailSwish, 5.2);
  ctx.lineTo(12.0, 3.8);
  ctx.closePath();
  ctx.fill();

  ctx.fillStyle = '#4E6132';
  ctx.beginPath();
  ctx.moveTo(12.5, 3.2);
  ctx.lineTo(15.5 + tailSwish, 1.4);
  ctx.lineTo(13.8 + tailSwish * 0.6, 3.0);
  ctx.lineTo(15.5 + tailSwish, 4.6);
  ctx.lineTo(12.5, 3.6);
  ctx.closePath();
  ctx.fill();

  ctx.fillStyle = 'rgba(72, 187, 120, 0.50)';
  ctx.fillRect(Math.round(13.5 + tailSwish * 0.5), 2, 2, 1);
  ctx.fillRect(Math.round(13.5 + tailSwish * 0.5), 4, 2, 1);

  // B. Slender Hydrodynamic Olive-Bronze Body (body length ~16px with tail, height ~5px)
  // Dark spine / outline (#1E2B16)
  ctx.fillStyle = '#1E2B16';
  ctx.beginPath();
  ctx.moveTo(0, 3.2);
  ctx.quadraticCurveTo(2.5, 1.0, 6.5, 1.0);
  ctx.quadraticCurveTo(10.0, 1.2, 12.5, 2.8);
  ctx.lineTo(12.5, 3.8);
  ctx.quadraticCurveTo(9.5, 5.8, 6.0, 5.8);
  ctx.quadraticCurveTo(2.5, 5.2, 0, 3.6);
  ctx.closePath();
  ctx.fill();

  // Midtone olive-bronze flank (#4E6132)
  ctx.fillStyle = '#4E6132';
  ctx.beginPath();
  ctx.moveTo(1.2, 3.2);
  ctx.quadraticCurveTo(3.0, 1.6, 6.5, 1.6);
  ctx.quadraticCurveTo(10.0, 1.8, 12.0, 3.0);
  ctx.lineTo(12.0, 3.6);
  ctx.quadraticCurveTo(9.5, 5.2, 6.0, 5.2);
  ctx.quadraticCurveTo(3.0, 4.8, 1.2, 3.6);
  ctx.closePath();
  ctx.fill();

  // Luminous golden-olive dorsal flank (#728848)
  ctx.fillStyle = '#728848';
  ctx.beginPath();
  ctx.moveTo(2.2, 2.6);
  ctx.quadraticCurveTo(6.0, 2.0, 10.0, 2.4);
  ctx.lineTo(10.5, 3.6);
  ctx.quadraticCurveTo(6.0, 4.2, 2.2, 3.6);
  ctx.closePath();
  ctx.fill();

  // Delicate speckled bronze / olive-gold flecks
  ctx.fillStyle = '#B59E4B';
  ctx.fillRect(4, 2.4, 1.5, 1);
  ctx.fillRect(7, 2.6, 1.5, 1);
  ctx.fillRect(9, 3.0, 1.5, 1);
  ctx.fillStyle = '#5A6E36';
  ctx.fillRect(5.5, 3.4, 1.5, 1);

  // C. Delicate Translucent Dorsal Fin
  ctx.fillStyle = '#2B381C';
  ctx.beginPath();
  ctx.moveTo(6.0, 1.6);
  ctx.lineTo(8.0, -0.6);
  ctx.lineTo(10.5, 0.4);
  ctx.lineTo(11.0, 1.6);
  ctx.closePath();
  ctx.fill();
  ctx.fillStyle = 'rgba(72, 187, 120, 0.55)';
  ctx.fillRect(7, 0.2, 2.5, 1);

  // D. Delicate Pectoral Fin with subtle slow flutter
  ctx.fillStyle = '#2B381C';
  ctx.beginPath();
  ctx.moveTo(4.5, 3.8);
  ctx.lineTo(7.0, 4.6 + finFlutter);
  ctx.lineTo(6.4, 5.8 + finFlutter);
  ctx.lineTo(4.3, 4.6);
  ctx.closePath();
  ctx.fill();
  ctx.fillStyle = 'rgba(72, 187, 120, 0.55)';
  ctx.fillRect(5.2, 4.4 + finFlutter * 0.5, 1.5, 1);

  // E. Tapered Snout, Lower Jaw & Hook
  ctx.fillStyle = '#1E2B16';
  ctx.fillRect(0.4, 2.8, 2.0, 1.0);
  ctx.fillRect(0, 3.2, 1.0, 0.8);
  ctx.fillStyle = '#3E5028';
  ctx.fillRect(0.5, 3.6, 1.8, 0.8);
  ctx.fillStyle = '#1E2B16';
  ctx.fillRect(0.2, 3.8, 1.2, 0.6);

  // Operculum gill cover
  ctx.strokeStyle = '#2B381C';
  ctx.lineWidth = 0.8;
  ctx.beginPath();
  ctx.arc(3.8, 3.2, 1.6, Math.PI * 1.4, Math.PI * 0.6);
  ctx.stroke();

  // Eye: delicate 2x2px dark eye with tiny 1px amber/gold glint (remove oversized cartoon eye)
  ctx.fillStyle = '#111810';
  ctx.fillRect(2, 2, 2, 2);
  ctx.fillStyle = '#F59E0B';
  ctx.fillRect(2, 2, 1, 1);

  ctx.restore();
}

// 3. Boathouse Props: Decluttered 16-bit JRPG layout with balanced corner stations,
// calm patient coastal crab resting/breathing cadence (now / 2000), and centered coastal chart
export function drawBoathouseProps(
  ctx: CanvasRenderingContext2D,
  camX: number,
  camY: number,
  animTime: number,
  interactionState?: Record<string, number>,
  playerPos?: { x: number; y: number },
) {
  const now = typeof animTime === 'number' && animTime > 0 ? animTime * 1000 : Date.now();

  ctx.save();
  ctx.imageSmoothingEnabled = false;

  // North Wall: Framed maritime coastal chart centered above the pool between the two desks
  const chartW = 30;
  const chartH = 17;
  const chartX = 113 - camX;
  const chartY = 12 - camY;
  ctx.save();
  ctx.fillStyle = 'rgba(15, 23, 42, 0.45)';
  ctx.fillRect(chartX + 1, chartY + 1, chartW, chartH);
  ctx.fillStyle = '#45220c';
  ctx.fillRect(chartX, chartY, chartW, chartH);
  ctx.fillStyle = '#6b3c1b';
  ctx.fillRect(chartX + 1, chartY + 1, chartW - 2, chartH - 2);
  ctx.fillStyle = '#fef3c7';
  ctx.fillRect(chartX + 2, chartY + 2, chartW - 4, chartH - 4);
  ctx.fillStyle = '#fffdf0';
  ctx.fillRect(chartX + 3, chartY + 3, chartW - 6, chartH - 6);

  ctx.fillStyle = '#fbbf24';
  ctx.fillRect(chartX, chartY, 2, 2);
  ctx.fillRect(chartX + chartW - 2, chartY, 2, 2);
  ctx.fillRect(chartX + chartW - 2, chartY + chartH - 2, 2, 2);
  ctx.fillRect(chartX, chartY + chartH - 2, 2, 2);

  // Coastline contour lines
  ctx.strokeStyle = '#0284c7';
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.moveTo(chartX + 4, chartY + 6);
  ctx.quadraticCurveTo(chartX + 11, chartY + 5, chartX + 16, chartY + 9);
  ctx.quadraticCurveTo(chartX + 20, chartY + 13, chartX + 26, chartY + 10);
  ctx.stroke();

  // Depth soundings
  ctx.fillStyle = '#1e3a8a';
  ctx.fillRect(chartX + 6, chartY + 8, 2, 1);
  ctx.fillRect(chartX + 12, chartY + 11, 2, 1);
  ctx.fillRect(chartX + 18, chartY + 8, 2, 1);

  // Navigation rhumb lines
  ctx.strokeStyle = 'rgba(220, 38, 38, 0.65)';
  ctx.lineWidth = 0.8;
  ctx.beginPath();
  ctx.moveTo(chartX + 4, chartY + 12);
  ctx.lineTo(chartX + 22, chartY + 4);
  ctx.moveTo(chartX + 8, chartY + 4);
  ctx.lineTo(chartX + 24, chartY + 12);
  ctx.stroke();

  // Compass rose
  const compX = chartX + 22;
  const compY = chartY + 5;
  ctx.fillStyle = '#0f172a';
  ctx.fillRect(compX - 1, compY - 1, 3, 3);
  ctx.fillStyle = '#dc2626';
  ctx.fillRect(compX, compY - 2, 1, 2);
  ctx.fillStyle = '#ca8a04';
  ctx.fillRect(compX, compY + 2, 1, 2);
  ctx.fillStyle = '#d97706';
  ctx.fillRect(compX - 2, compY, 2, 1);
  ctx.fillRect(compX + 1, compY, 2, 1);
  ctx.fillStyle = '#fde047';
  ctx.fillRect(compX, compY, 1, 1);

  ctx.strokeStyle = 'rgba(255, 255, 255, 0.35)';
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.moveTo(chartX + 4, chartY + 3);
  ctx.lineTo(chartX + 12, chartY + 13);
  ctx.stroke();
  ctx.restore();

  // Entrance Threshold: Muted dark-slate / weathered woven doormat
  const matX = 7 * TILE_SIZE - camX;
  const matY = 10 * TILE_SIZE + 4 - camY;
  const matW = 32;
  const matH = 14;
  ctx.save();
  ctx.fillStyle = 'rgba(15, 23, 42, 0.35)';
  ctx.fillRect(matX + 1, matY + 1, matW + 1, matH);
  ctx.fillStyle = '#1E293B';
  ctx.fillRect(matX, matY, matW, matH);
  ctx.fillStyle = '#334155';
  ctx.fillRect(matX + 1, matY + 1, matW - 2, matH - 2);
  for (let my = matY + 2; my < matY + matH - 2; my += 2) {
    ctx.fillStyle = my % 4 === 0 ? '#1E293B' : '#475569';
    ctx.fillRect(matX + 2, my, matW - 4, 1);
  }
  ctx.restore();

  // Sideways Crimson Crab on West Walkway (at X: 4, Y: 6) with proximity reaction
  // Reduced crab idle twitching/scuttle speed: slow, subtle breathing/resting cadence (now / 2000)
  const pTileX = playerPos ? (playerPos.x + 8) / TILE_SIZE : 999;
  const pTileY = playerPos ? (playerPos.y + 12) / TILE_SIZE : 999;
  const distToCrab = Math.hypot(pTileX - 4, pTileY - 6);
  const isCrabDiving = distToCrab < 2.5;

  const crabBaseX = 4 * TILE_SIZE + 2;
  const crabBaseY = 6 * TILE_SIZE + 6;

  // Slow, subtle breathing/resting cadence (now / 2000)
  const crabPhase = now / 2000;
  const crabScuttle = Math.sin(crabPhase) * 2.0;
  const legCycle = Math.sin(crabPhase * 1.3) > 0 ? 1 : 0;
  const clawSnap = Math.sin(crabPhase * 0.8) > 0.6 ? 1 : 0;

  // Smooth jump arc and gentle ripple into water slip edge
  const diveT = Math.min(1.0, Math.max(0, (2.5 - distToCrab) / 1.5));
  const diveArc = Math.sin(diveT * Math.PI) * 4;
  const crabWorldX = isCrabDiving ? crabBaseX + 14 * diveT : crabBaseX + crabScuttle;
  const crabWorldY = isCrabDiving ? crabBaseY + 3 * diveT - diveArc : crabBaseY;
  const crabScreenX = Math.round(crabWorldX - camX);
  const crabScreenY = Math.round(crabWorldY - camY);

  if (isCrabDiving) {
    ctx.save();
    const crabRipPeriod = 14.0; // Slow, calm expanding ripples
    for (let r = 0; r < 2; r++) {
      const ripProgress = ((now / 14000 + r * 0.5) % 1.0);
      const ripR = 3 + ripProgress * 12;
      const ripA = Math.max(0, (1.0 - ripProgress) * (1.0 - ripProgress)) * 0.30;
      ctx.strokeStyle = `rgba(160, 220, 255, ${ripA.toFixed(3)})`;
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.ellipse(crabScreenX + 4, crabScreenY + 5, Math.max(0.1, ripR), Math.max(0.1, ripR * 0.45), 0, 0, Math.PI * 2);
      ctx.stroke();
    }
    ctx.restore();
  }

  ctx.save();
  ctx.translate(crabScreenX, crabScreenY);
  if (isCrabDiving) {
    ctx.globalAlpha = 0.75;
  } else {
    ctx.fillStyle = 'rgba(15, 23, 42, 0.25)';
    ctx.fillRect(0, 6, 10, 2);
  }

  ctx.fillStyle = '#0f172a';
  ctx.fillRect(1, 1, 8, 5);
  ctx.fillStyle = '#dc2626';
  ctx.fillRect(2, 2, 6, 4);
  ctx.fillStyle = '#ef4444';
  ctx.fillRect(3, 2, 4, 1);

  ctx.fillStyle = '#0f172a';
  ctx.fillRect(-1 + clawSnap, 0, 3, 3);
  ctx.fillRect(7 - clawSnap, 0, 3, 3);
  ctx.fillStyle = '#dc2626';
  ctx.fillRect(0 + clawSnap, 0, 2, 2);
  ctx.fillRect(7 - clawSnap, 0, 2, 2);
  ctx.fillStyle = '#f87171';
  ctx.fillRect(0 + clawSnap, 0, 1, 1);
  ctx.fillRect(8 - clawSnap, 0, 1, 1);

  ctx.fillStyle = '#09090b';
  ctx.fillRect(3, 0, 1, 2);
  ctx.fillRect(6, 0, 1, 2);
  ctx.fillStyle = '#ffffff';
  ctx.fillRect(3, 0, 1, 1);
  ctx.fillRect(6, 0, 1, 1);

  ctx.fillStyle = '#b91c1c';
  if (legCycle === 0) {
    ctx.fillRect(-1, 3, 2, 2);
    ctx.fillRect(0, 5, 2, 2);
    ctx.fillRect(8, 3, 2, 2);
    ctx.fillRect(7, 5, 2, 2);
  } else {
    ctx.fillRect(0, 3, 2, 2);
    ctx.fillRect(-1, 5, 2, 2);
    ctx.fillRect(7, 3, 2, 2);
    ctx.fillRect(8, 5, 2, 2);
  }
  ctx.restore();

  // 5. SALVAGE WORKTABLE & SHIP'S BELL at X: 2..3, Y: 2
  const tableX = 2 * TILE_SIZE - camX;
  const tableY = 2 * TILE_SIZE - camY;

  ctx.fillStyle = '#0f172a';
  ctx.fillRect(tableX + 1, tableY + 4, 30, 12);
  ctx.fillStyle = '#542c16';
  ctx.fillRect(tableX + 2, tableY + 5, 28, 6);
  ctx.fillStyle = '#8a5830';
  ctx.fillRect(tableX + 2, tableY + 5, 28, 1);
  ctx.fillStyle = '#381c08';
  ctx.fillRect(tableX + 3, tableY + 11, 3, 5);
  ctx.fillRect(tableX + 26, tableY + 11, 3, 5);

  ctx.fillStyle = '#94a3b8';
  ctx.fillRect(tableX + 6, tableY + 3, 8, 2);
  ctx.fillStyle = '#ffffff';
  ctx.fillRect(tableX + 6, tableY + 3, 4, 1);

  ctx.strokeStyle = '#b45309';
  ctx.lineWidth = 1.5;
  ctx.beginPath();
  ctx.arc(tableX + 20, tableY + 4, 3.5, 0, Math.PI * 2);
  ctx.stroke();

  ctx.fillStyle = '#0f172a';
  ctx.fillRect(tableX + 22, tableY - 6, 6, 7);
  ctx.fillStyle = '#fbbf24';
  ctx.beginPath();
  ctx.moveTo(tableX + 24, tableY - 5);
  ctx.lineTo(tableX + 27, tableY);
  ctx.lineTo(tableX + 22, tableY);
  ctx.closePath();
  ctx.fill();
  ctx.fillStyle = '#d97706';
  ctx.fillRect(tableX + 24, tableY, 2, 2);

  // 6. HARBOR MASTER'S ARRIVAL LEDGER at X: 12..13, Y: 2
  const ledgerX = 12 * TILE_SIZE - camX;
  const ledgerY = 2 * TILE_SIZE - camY;

  ctx.fillStyle = '#0f172a';
  ctx.fillRect(ledgerX + 1, ledgerY + 3, 30, 13);
  ctx.fillStyle = '#6b3c1b';
  ctx.fillRect(ledgerX + 2, ledgerY + 4, 28, 6);
  ctx.fillStyle = '#8c5228';
  ctx.fillRect(ledgerX + 2, ledgerY + 4, 28, 1);
  ctx.fillStyle = '#381c08';
  ctx.fillRect(ledgerX + 3, ledgerY + 10, 3, 6);
  ctx.fillRect(ledgerX + 26, ledgerY + 10, 3, 6);

  ctx.fillStyle = '#0f172a';
  ctx.fillRect(ledgerX + 6, ledgerY + 1, 16, 8);
  ctx.fillStyle = '#fffdf0';
  ctx.fillRect(ledgerX + 7, ledgerY + 2, 14, 6);
  ctx.fillStyle = '#1e293b';
  ctx.fillRect(ledgerX + 8, ledgerY + 3, 5, 1);
  ctx.fillRect(ledgerX + 8, ledgerY + 5, 5, 1);
  ctx.fillRect(ledgerX + 15, ledgerY + 3, 5, 1);
  ctx.fillRect(ledgerX + 15, ledgerY + 5, 4, 1);
  ctx.fillStyle = '#dc2626';
  ctx.fillRect(ledgerX + 13, ledgerY + 1, 2, 7);

  ctx.fillStyle = '#fbbf24';
  ctx.fillRect(ledgerX + 23, ledgerY + 2, 3, 3);
  ctx.fillStyle = '#ffffff';
  ctx.fillRect(ledgerX + 24, ledgerY - 4, 1, 6);
  ctx.fillRect(ledgerX + 25, ledgerY - 3, 1, 3);

  // 7. OILSKIN EXPLORER'S SEA-CHEST at X: 2, Y: 9
  const chestX = 2 * TILE_SIZE - camX;
  const chestY = 9 * TILE_SIZE - camY;

  ctx.fillStyle = '#0f172a';
  ctx.fillRect(chestX + 1, chestY + 3, 14, 12);
  ctx.fillStyle = '#783e20';
  ctx.fillRect(chestX + 2, chestY + 4, 12, 10);
  ctx.fillStyle = '#b0784a';
  ctx.fillRect(chestX + 2, chestY + 4, 12, 2);

  ctx.fillStyle = '#fbbf24';
  ctx.fillRect(chestX + 2, chestY + 4, 2, 2);
  ctx.fillRect(chestX + 12, chestY + 4, 2, 2);
  ctx.fillRect(chestX + 2, chestY + 12, 2, 2);
  ctx.fillRect(chestX + 12, chestY + 12, 2, 2);
  ctx.fillRect(chestX + 7, chestY + 7, 2, 3);

  const chestOpened = interactionState?.boathouse_chest_granted;
  if (!chestOpened) {
    const glint = Math.sin(now / 300) > 0.3;
    if (glint) {
      ctx.fillStyle = '#fef08a';
      ctx.fillRect(chestX + 8, chestY + 2, 2, 2);
      ctx.fillStyle = '#ffffff';
      ctx.fillRect(chestX + 8, chestY + 2, 1, 1);
    }
  }

  // 8. BOOKBINDER'S BENCH at X: 13, Y: 9 (Cedar workbench with screw press, folios, cobalt & emerald glass floats)
  const benchX = 13 * TILE_SIZE - camX;
  const benchY = 9 * TILE_SIZE - camY;

  ctx.fillStyle = 'rgba(15, 23, 42, 0.35)';
  ctx.fillRect(benchX, benchY + 14, 18, 3);

  ctx.fillStyle = '#0f172a';
  ctx.fillRect(benchX, benchY + 4, 18, 11);
  ctx.fillStyle = '#6b3c1b';
  ctx.fillRect(benchX + 1, benchY + 5, 16, 5);
  ctx.fillStyle = '#8a5830';
  ctx.fillRect(benchX + 1, benchY + 5, 16, 1);
  ctx.fillStyle = '#b0784a';
  ctx.fillRect(benchX + 1, benchY + 5, 16, 1);

  ctx.fillStyle = '#381c08';
  ctx.fillRect(benchX + 2, benchY + 10, 3, 5);
  ctx.fillRect(benchX + 13, benchY + 10, 3, 5);

  // A. Screw press clamping wet folio sheets
  ctx.fillStyle = '#261205';
  ctx.fillRect(benchX + 2, benchY + 4, 8, 2);
  ctx.fillStyle = '#fffdf0';
  ctx.fillRect(benchX + 3, benchY + 3, 6, 2);
  ctx.fillStyle = '#cbd5e1';
  ctx.fillRect(benchX + 3, benchY + 4, 6, 1);
  ctx.fillStyle = '#542c16';
  ctx.fillRect(benchX + 2, benchY + 2, 8, 1);

  // Threaded bronze screw spindle
  ctx.fillStyle = '#d97706';
  ctx.fillRect(benchX + 5, benchY - 1, 2, 3);
  ctx.fillStyle = '#fbbf24';
  ctx.fillRect(benchX + 5, benchY, 2, 1);

  // Crossbar turning lever handle with brass end knobs
  ctx.fillStyle = '#1e293b';
  ctx.fillRect(benchX + 3, benchY - 1, 6, 1);
  ctx.fillStyle = '#94a3b8';
  ctx.fillRect(benchX + 4, benchY - 1, 4, 1);
  ctx.fillStyle = '#fbbf24';
  ctx.fillRect(benchX + 2, benchY - 2, 2, 2);
  ctx.fillRect(benchX + 8, benchY - 2, 2, 2);

  // B. Paper folios
  ctx.fillStyle = '#fffdf0';
  ctx.fillRect(benchX + 10, benchY + 4, 4, 2);
  ctx.fillStyle = '#cbd5e1';
  ctx.fillRect(benchX + 10, benchY + 5, 4, 1);

  // C. Glass fishing floats
  // Emerald-green float with netting
  ctx.fillStyle = '#064e3b';
  ctx.fillRect(benchX + 11, benchY + 1, 5, 5);
  ctx.fillStyle = '#059669';
  ctx.fillRect(benchX + 12, benchY + 2, 3, 3);
  ctx.fillStyle = '#34d399';
  ctx.fillRect(benchX + 12, benchY + 2, 2, 1);
  ctx.fillStyle = '#ffffff';
  ctx.fillRect(benchX + 12, benchY + 2, 1, 1);
  ctx.fillStyle = '#78350f';
  ctx.fillRect(benchX + 11, benchY + 2, 1, 3);
  ctx.fillRect(benchX + 14, benchY + 3, 1, 2);
  ctx.fillRect(benchX + 12, benchY + 4, 3, 1);

  // Cobalt-blue float
  ctx.fillStyle = '#1e3a8a';
  ctx.fillRect(benchX + 14, benchY + 3, 4, 4);
  ctx.fillStyle = '#2563eb';
  ctx.fillRect(benchX + 15, benchY + 4, 2, 2);
  ctx.fillStyle = '#93c5fd';
  ctx.fillRect(benchX + 15, benchY + 4, 1, 1);
  ctx.fillStyle = '#ffffff';
  ctx.fillRect(benchX + 15, benchY + 4, 1, 1);

  // 9. 4 CORNER BULKHEAD LANTERNS & AMBIENT LIGHTING
  const lanterns = [
    { x: 3 * TILE_SIZE + 8, y: 1 * TILE_SIZE + 10 },
    { x: 12 * TILE_SIZE + 8, y: 1 * TILE_SIZE + 10 },
    { x: 1 * TILE_SIZE + 12, y: 6 * TILE_SIZE + 8 },
    { x: 14 * TILE_SIZE + 4, y: 6 * TILE_SIZE + 8 },
  ];

  lanterns.forEach((l, idx) => {
    const lx = l.x - camX;
    const ly = l.y - camY;
    const flicker = Math.sin(animTime * 5.0 + idx * 1.8) * 1.5;
    const radius = Math.max(1, 38 + flicker);

    const gGrad = ctx.createRadialGradient(lx, ly, 2, lx, ly, radius);
    gGrad.addColorStop(0, 'rgba(254, 240, 138, 0.48)');
    gGrad.addColorStop(0.35, 'rgba(251, 191, 36, 0.22)');
    gGrad.addColorStop(0.75, 'rgba(245, 158, 11, 0.06)');
    gGrad.addColorStop(1, 'rgba(245, 158, 11, 0)');
    ctx.fillStyle = gGrad;
    ctx.beginPath();
    ctx.arc(lx, ly, radius, 0, Math.PI * 2);
    ctx.fill();

    ctx.fillStyle = '#0f172a';
    ctx.fillRect(lx - 2, ly - 3, 5, 6);
    ctx.fillStyle = '#fbbf24';
    ctx.fillRect(lx - 1, ly - 2, 3, 4);
    ctx.fillStyle = '#ffffff';
    ctx.fillRect(lx, ly - 1, 1, 2);
  });

  ctx.restore();
}

export function drawBoathouseInterior(
  ctx: CanvasRenderingContext2D,
  camX: number,
  camY: number,
  animTime: number,
  interactionState?: Record<string, number>,
  playerPos?: { x: number; y: number },
) {
  drawBoathouseWaterSlip(ctx, camX, camY, animTime);
  drawBoathouseFish(ctx, camX, camY, animTime);
  drawBoathouseProps(ctx, camX, camY, animTime, interactionState, playerPos);
}

// ============================================================================
// CAFÉ DE FLORE PROCEDURAL INTERIOR RENDERER
// ============================================================================
export function drawCafeDeFloreInterior(
  ctx: CanvasRenderingContext2D,
  camX: number,
  camY: number,
  animTime: number,
  interactionState?: Record<string, number>,
  playerPos?: { x: number; y: number },
) {
  ctx.save();
  ctx.imageSmoothingEnabled = false;

  const rect = (rx: number, ry: number, rw: number, rh: number, col: string) => {
    ctx.fillStyle = col;
    ctx.fillRect(rx - camX, ry - camY, rw, rh);
  };
  const px = (pxX: number, pxY: number, col: string, pw = 1, ph = 1) => {
    ctx.fillStyle = col;
    ctx.fillRect(pxX - camX, pxY - camY, pw, ph);
  };

  const OUT = '#0f172a';

  // 1. Polished Mahogany Bar Counter (X: 3..7 in tiles, Y: 3 in tiles -> px: 48..128, Y: 48..64)
  const barX = 3 * TILE_SIZE;
  const barY = 3 * TILE_SIZE;
  const barW = 5 * TILE_SIZE; // 80px

  rect(barX, barY + 4, barW, 14, OUT);
  rect(barX + 1, barY + 5, barW - 2, 4, '#542c16'); // Mahogany counter top
  rect(barX + 1, barY + 5, barW - 2, 1, '#8a5830'); // Bevel luster
  rect(barX + 1, barY + 9, barW - 2, 8, '#381c08'); // Front dark wood panel
  rect(barX + 1, barY + 16, barW - 2, 2, '#fbbf24'); // Polished brass footrail

  // 2. Shiny Vintage Brass Espresso Machine (La Marzocco / vintage brass urn) at X: 3.5, Y: 2.8 -> px: 56, Y: 38
  const espX = 3 * TILE_SIZE + 8;
  const espY = 2 * TILE_SIZE + 6;

  // Brass machine housing & dome urn
  rect(espX, espY + 4, 16, 12, OUT);
  rect(espX + 1, espY + 5, 14, 10, '#d97706'); // Burnished brass body
  rect(espX + 2, espY + 5, 12, 10, '#fbbf24'); // Luminous polished brass
  px(espX + 3, espY + 6, '#ffffff', 4, 8);    // Specular shine on brass
  // Top brass dome & eagle/finial
  rect(espX + 3, espY + 1, 10, 4, OUT);
  rect(espX + 4, espY + 2, 8, 3, '#fbbf24');
  px(espX + 7, espY, '#fbbf24', 2, 2);        // Finial eagle/globe
  px(espX + 7, espY, '#ffffff', 1, 1);
  // Chrome group heads & twin portafilters
  rect(espX + 2, espY + 11, 4, 3, '#94a3b8');
  rect(espX + 10, espY + 11, 4, 3, '#94a3b8');
  px(espX + 3, espY + 14, '#1e293b', 2, 2);   // Portafilter handle 1
  px(espX + 11, espY + 14, '#1e293b', 2, 2);  // Portafilter handle 2
  // Pressure manometer gauge dials
  px(espX + 4, espY + 7, '#ffffff', 3, 3);
  px(espX + 5, espY + 8, '#dc2626', 1, 1);    // Red pressure needle
  px(espX + 9, espY + 7, '#ffffff', 3, 3);
  px(espX + 10, espY + 8, '#0284c7', 1, 1);

  // Animated Rising Steam Wisps from the espresso machine
  for (let s = 0; s < 3; s++) {
    const sCycle = (animTime * 1.4 + s * 0.9) % 2.6;
    const sProgress = sCycle / 2.6;
    const sRise = sProgress * 15;
    const sSway = Math.sin(animTime * 2.5 + s * 1.8) * 2.2;
    const sAlpha = Math.sin(sProgress * Math.PI) * 0.55;

    if (sAlpha > 0.05) {
      const curSteamX = Math.round(espX + 7 + (s - 1) * 3 + sSway);
      const curSteamY = Math.round(espY - 2 - sRise);
      ctx.fillStyle = `rgba(255, 255, 255, ${sAlpha.toFixed(2)})`;
      ctx.fillRect(curSteamX - camX, curSteamY - camY, 2, 2);
      ctx.fillStyle = `rgba(224, 242, 254, ${(sAlpha * 0.5).toFixed(2)})`;
      ctx.fillRect(curSteamX - camX, curSteamY + 1 - camY, 2, 1);
    }
  }

  // 3. Bar Counter Props: Demitasse cups with rich crema, croissant dish
  rect(espX + 22, barY + 3, 5, 3, OUT);
  rect(espX + 22, barY + 3, 4, 2, '#ffffff'); // White demitasse cup
  px(espX + 23, barY + 3, '#451a03', 2, 1);  // Dark espresso crema
  px(espX + 21, barY + 4, '#cbd5e1', 6, 1);  // Saucer
  px(espX + 27, barY + 3, '#fbbf24', 1, 2);  // Silver/gold spoon

  // 4. Apollinaire's Corner Marble Table at X: 10, Y: 5 (px: 160, 80)
  const apTabX = 10 * TILE_SIZE;
  const apTabY = 5 * TILE_SIZE;

  // Round Carrara marble tabletop
  rect(apTabX + 2, apTabY + 4, 12, 7, OUT);
  rect(apTabX + 3, apTabY + 5, 10, 5, '#f8fafc'); // White Carrara marble
  rect(apTabX + 3, apTabY + 5, 10, 1, '#ffffff'); // Sunlit top edge highlight
  px(apTabX + 5, apTabY + 7, '#cbd5e1', 6, 2);    // Grey marble veining

  // Table pedestal base
  rect(apTabX + 7, apTabY + 9, 2, 5, OUT);
  px(apTabX + 7, apTabY + 9, '#334155', 1, 4);
  px(apTabX + 4, apTabY + 13, '#1e293b', 8, 2);   // Cast-iron base

  // Apollinaire's Notebook with Calligramme Eiffel Tower & Demitasse cup
  rect(apTabX + 4, apTabY + 4, 5, 4, OUT);
  rect(apTabX + 4, apTabY + 4, 5, 3, '#fef3c7'); // Cream notebook paper
  px(apTabX + 6, apTabY + 4, '#09090b', 1, 2);  // Calligramme tower spire!
  px(apTabX + 5, apTabY + 6, '#09090b', 3, 1);  // Tower legs
  // Fresh croissant on porcelain plate
  rect(apTabX + 10, apTabY + 4, 4, 3, '#d97706'); // Golden croissant
  px(apTabX + 11, apTabY + 3, '#f59e0b', 2, 1);
  px(apTabX + 10, apTabY + 6, '#ffffff', 4, 1); // Porcelain plate

  // 5. Bistro Table 2 at X: 3, Y: 7
  const t2X = 3 * TILE_SIZE;
  const t2Y = 7 * TILE_SIZE;
  rect(t2X + 2, t2Y + 4, 12, 7, OUT);
  rect(t2X + 3, t2Y + 5, 10, 5, '#f8fafc');
  rect(t2X + 3, t2Y + 5, 10, 1, '#ffffff');
  px(t2X + 5, t2Y + 7, '#cbd5e1', 6, 2);
  rect(t2X + 7, t2Y + 9, 2, 5, OUT);
  px(t2X + 4, t2Y + 13, '#1e293b', 8, 2);
  // Coffee cup on table 2
  px(t2X + 5, t2Y + 4, '#ffffff', 2, 2);
  px(t2X + 5, t2Y + 4, '#451a03', 1, 1);

  // 6. Bistro Table 3 at X: 12, Y: 8
  const t3X = 12 * TILE_SIZE;
  const t3Y = 8 * TILE_SIZE;
  rect(t3X + 2, t3Y + 4, 12, 7, OUT);
  rect(t3X + 3, t3Y + 5, 10, 5, '#f8fafc');
  rect(t3X + 3, t3Y + 5, 10, 1, '#ffffff');
  px(t3X + 5, t3Y + 7, '#cbd5e1', 6, 2);
  rect(t3X + 7, t3Y + 9, 2, 5, OUT);
  px(t3X + 4, t3Y + 13, '#1e293b', 8, 2);

  // 7. Warm Brass Wall Sconces & Mirrors along top wall
  const sconces = [3, 7, 11];
  sconces.forEach((sc) => {
    const sx = sc * TILE_SIZE + 6;
    const sy = 1 * TILE_SIZE + 4;
    rect(sx, sy, 4, 6, OUT);
    rect(sx + 1, sy + 1, 2, 4, '#f59e0b');
    px(sx + 1, sy + 2, '#ffffff', 1, 2);
    rect(sx - 1, sy + 5, 6, 1, '#fbbf24');
  });

  ctx.restore();
}

// ============================================================================
// SHAKESPEARE AND COMPANY PROCEDURAL INTERIOR RENDERER
// ============================================================================
export function drawShakespeareCoInterior(
  ctx: CanvasRenderingContext2D,
  camX: number,
  camY: number,
  animTime: number,
  interactionState?: Record<string, number>,
  playerPos?: { x: number; y: number },
) {
  ctx.save();
  ctx.imageSmoothingEnabled = false;

  const rect = (rx: number, ry: number, rw: number, rh: number, col: string) => {
    ctx.fillStyle = col;
    ctx.fillRect(rx - camX, ry - camY, rw, rh);
  };
  const px = (pxX: number, pxY: number, col: string, pw = 1, ph = 1) => {
    ctx.fillStyle = col;
    ctx.fillRect(pxX - camX, pxY - camY, pw, ph);
  };

  const OUT = '#0f172a';

  // 1. Rolling Brass Ladder against wall at X: 3, Y: 2 (px: 48, 32)
  const ladX = 3 * TILE_SIZE + 4;
  const ladY = 2 * TILE_SIZE;
  // Brass hanging track rail at y=33
  rect(ladX - 10, ladY + 1, 24, 2, '#fbbf24');
  px(ladX - 10, ladY + 1, '#ffffff', 24, 1);
  // Slanted ladder uprights
  rect(ladX, ladY + 2, 2, 14, '#b45309');
  rect(ladX + 8, ladY + 2, 2, 14, '#b45309');
  // Ladder rungs
  rect(ladX + 1, ladY + 4, 8, 1, '#fbbf24');
  rect(ladX + 1, ladY + 8, 8, 1, '#fbbf24');
  rect(ladX + 1, ladY + 12, 8, 1, '#fbbf24');
  // Brass caster wheels at base
  px(ladX - 1, ladY + 15, '#fbbf24', 3, 2);
  px(ladX + 7, ladY + 15, '#fbbf24', 3, 2);

  // 2. Sylvia Beach's Polished Oak Reading Desk at X: 7..8, Y: 3 (px: 112..144, 48)
  const deskX = 7 * TILE_SIZE;
  const deskY = 3 * TILE_SIZE;
  const deskW = 2 * TILE_SIZE; // 32px

  rect(deskX, deskY + 4, deskW, 12, OUT);
  rect(deskX + 1, deskY + 5, deskW - 2, 5, '#542c16'); // Solid oak desktop
  rect(deskX + 1, deskY + 5, deskW - 2, 1, '#8a5830'); // Bevel highlight
  rect(deskX + 2, deskY + 10, 3, 6, '#381c08'); // Legs
  rect(deskX + deskW - 5, deskY + 10, 3, 6, '#381c08');

  // Desk Items: Open lending ledger, blue Ulysses subscriber cards, brass stamp holder
  rect(deskX + 3, deskY + 3, 10, 6, OUT);
  rect(deskX + 4, deskY + 4, 8, 4, '#fffdf0'); // Open ledger book
  px(deskX + 5, deskY + 5, '#1e293b', 6, 1);   // Text lines
  px(deskX + 5, deskY + 6, '#1e293b', 5, 1);
  // Iconic blue Shakespeare & Co subscription card (matching Ulysses cover blue)
  rect(deskX + 16, deskY + 4, 6, 4, '#1d4ed8'); // Bright blue card
  px(deskX + 17, deskY + 5, '#ffffff', 4, 1);
  // Brass stamp holder & feather quill in inkpot
  rect(deskX + 24, deskY + 3, 3, 3, '#fbbf24');
  px(deskX + 25, deskY, '#ffffff', 1, 3);       // White feather quill

  // 3. Fluffy Tortoiseshell Bookstore Cat snoozing on folios stack at X: 4, Y: 6 (px: 64, 96)
  const catStackX = 4 * TILE_SIZE;
  const catStackY = 6 * TILE_SIZE;

  // Stack of 3 thick leather-bound folios
  rect(catStackX + 1, catStackY + 9, 14, 4, OUT);
  rect(catStackX + 2, catStackY + 10, 12, 2, '#7f1d1d'); // Bottom crimson folio
  px(catStackX + 2, catStackY + 10, '#fbbf24', 12, 1);  // Gold gilt page edge
  rect(catStackX + 2, catStackY + 7, 12, 3, OUT);
  rect(catStackX + 3, catStackY + 8, 10, 2, '#1e3a8a');  // Middle navy folio
  rect(catStackX + 3, catStackY + 5, 10, 3, OUT);
  rect(catStackX + 4, catStackY + 6, 8, 2, '#78350f');   // Top amber folio

  // Fluffy Tortoiseshell Cat curled on top with gentle breathing animation (Math.sin(animTime * 2.0))
  const catBreathe = Math.sin(animTime * 2.0) * 0.8;
  const catY = Math.round(catStackY + 1 - catBreathe);

  // Cat body (rich ginger, black, and white calico/tortoiseshell patches)
  rect(catStackX + 3, catY + 1, 10, 6, OUT);
  rect(catStackX + 4, catY + 2, 8, 4, '#ea580c'); // Warm ginger base
  // Tortoiseshell dark black & white patches
  px(catStackX + 4, catY + 2, '#09090b', 3, 2);  // Black patch
  px(catStackX + 8, catY + 3, '#09090b', 3, 2);
  px(catStackX + 6, catY + 4, '#ffffff', 3, 2);  // White belly fur
  // Sleeping curled head & cute pointed ears
  rect(catStackX + 9, catY + 1, 4, 4, OUT);
  rect(catStackX + 10, catY + 2, 3, 3, '#ea580c');
  px(catStackX + 9, catY, '#ea580c', 2, 2);      // Ear 1
  px(catStackX + 10, catY + 1, '#fca5a5', 1, 1); // Inner pink ear
  px(catStackX + 12, catY, '#09090b', 2, 2);     // Ear 2
  // Sleeping closed eye lines & pink nose
  px(catStackX + 11, catY + 3, '#09090b', 2, 1);
  px(catStackX + 12, catY + 4, '#fca5a5', 1, 1); // Pink nose
  // Curled tail wrapped around
  px(catStackX + 2, catY + 3, '#ea580c', 2, 3);
  px(catStackX + 3, catY + 5, '#09090b', 2, 1);

  // 4. Comfy Reading Armchair & Glowing Floor Lamp at X: 12..13, Y: 6..7 (px: 192..224, 96..112)
  const chairX = 12 * TILE_SIZE;
  const chairY = 6 * TILE_SIZE + 4;

  // Deep velvet reading armchair
  rect(chairX, chairY, 14, 12, OUT);
  rect(chairX + 1, chairY + 1, 12, 10, '#047857'); // Emerald velvet armchair
  rect(chairX + 2, chairY + 2, 10, 2, '#10b981');  // Headrest highlight
  rect(chairX + 3, chairY + 5, 8, 4, '#065f46');   // Seat cushion
  px(chairX + 1, chairY + 11, '#381c08', 2, 2);    // Front feet
  px(chairX + 11, chairY + 11, '#381c08', 2, 2);

  // Brass Floor Lamp beside armchair at X: 13.5 (px: 216, 96)
  const lampX = 13 * TILE_SIZE + 8;
  const lampY = 5 * TILE_SIZE + 2;
  // Stand pole & weighted base
  rect(lampX, lampY + 6, 2, 20, '#fbbf24');
  rect(lampX - 2, lampY + 24, 6, 2, '#d97706');
  // Silk lampshade
  rect(lampX - 4, lampY, 10, 6, OUT);
  rect(lampX - 3, lampY + 1, 8, 5, '#fef08a'); // Luminous warm silk shade
  px(lampX - 2, lampY + 2, '#ffffff', 6, 2);
  rect(lampX - 4, lampY + 5, 10, 1, '#d97706'); // Fringe

  // Warm ambient reading lamp light cone
  const rGlow = ctx.createRadialGradient(lampX + 1 - camX, lampY + 3 - camY, 2, lampX + 1 - camX, lampY + 12 - camY, 32);
  rGlow.addColorStop(0, 'rgba(254, 240, 138, 0.45)');
  rGlow.addColorStop(0.5, 'rgba(251, 191, 36, 0.18)');
  rGlow.addColorStop(1, 'rgba(245, 158, 11, 0)');
  ctx.fillStyle = rGlow;
  ctx.beginPath();
  ctx.arc(lampX + 1 - camX, lampY + 12 - camY, 32, 0, Math.PI * 2);
  ctx.fill();

  ctx.restore();
}

// ============================================================================
// CANTO VI: THE SUMMIT PROCEDURAL ENVIRONMENT
// 1. Serene alpine twilight sky (#283044 to #7E8D9F) with clean pixel stars & mountain peaks
// 2. Crisp, stepped pixel-art cloud banks (#FFFFFF, #EEF2F6, #CBD4DE, #9AA8B8)
// 3. Hellenic Architecture: Calm Pentelic marble flagstone tiles (#F4F7F9 and #E6EBF0)
//    with delicate 1px soft seams (#CCD4DD), clean marble steps with 1px white tread highlight,
//    and NO radial yellow spokes, concentric gold rings, or yellow stair dividing stripe.
// ============================================================================
export function drawSummitCelestialSkyAndClouds(
  ctx: CanvasRenderingContext2D,
  camX: number,
  camY: number,
  animTime: number,
) {
  // 1. Serene alpine twilight sky (#283044 at top to #7E8D9F at horizon)
  const skyGrad = ctx.createLinearGradient(0, 0 - camY, 0, 180 - camY);
  skyGrad.addColorStop(0.0, '#283044'); // Deep alpine twilight
  skyGrad.addColorStop(0.35, '#3C495E');
  skyGrad.addColorStop(0.70, '#59687D');
  skyGrad.addColorStop(1.0, '#7E8D9F'); // Soft twilight horizon
  ctx.fillStyle = skyGrad;
  ctx.fillRect(0, 0, VIEWPORT_WIDTH, VIEWPORT_HEIGHT);

  // Subtle clean pixel stars in the upper alpine sky
  const stars = [
    { x: 24, y: 14 }, { x: 58, y: 22 }, { x: 92, y: 10 }, { x: 134, y: 26 },
    { x: 178, y: 16 }, { x: 212, y: 30 }, { x: 256, y: 12 }, { x: 298, y: 24 },
    { x: 342, y: 18 }, { x: 384, y: 28 }, { x: 426, y: 14 }, { x: 470, y: 22 },
    { x: 512, y: 16 }, { x: 548, y: 26 },
  ];
  ctx.fillStyle = '#FFFFFF';
  stars.forEach((s) => {
    const sx = Math.round(s.x - camX);
    const sy = Math.round(s.y - camY);
    if (sx >= 0 && sx < VIEWPORT_WIDTH && sy >= 0 && sy < VIEWPORT_HEIGHT) {
      ctx.fillRect(sx, sy, 1, 1);
    }
  });

  // Distant serene mountain silhouettes in crisp 16-bit pixel steps
  const peaks = [
    { startX: 10, peakX: 60, endX: 130, peakY: 42, color: '#3A4456', snowColor: '#CBD4DE' },
    { startX: 95, peakX: 160, endX: 235, peakY: 34, color: '#455064', snowColor: '#EEF2F6' },
    { startX: 335, peakX: 410, endX: 485, peakY: 36, color: '#414D60', snowColor: '#CBD4DE' },
    { startX: 440, peakX: 510, endX: 575, peakY: 46, color: '#364052', snowColor: '#9AA8B8' },
  ];

  peaks.forEach((pk) => {
    const p1x = Math.round(pk.startX - camX);
    const px = Math.round(pk.peakX - camX);
    const p2x = Math.round(pk.endX - camX);
    const py = Math.round(pk.peakY - camY);
    const baseY = Math.round(110 - camY);

    if (p2x >= -20 && p1x <= VIEWPORT_WIDTH + 20 && baseY >= 0) {
      ctx.save();
      ctx.fillStyle = pk.color;
      ctx.beginPath();
      ctx.moveTo(p1x, baseY);
      ctx.lineTo(px, py);
      ctx.lineTo(p2x, baseY);
      ctx.closePath();
      ctx.fill();

      // Clean, stepped snowcap
      ctx.fillStyle = pk.snowColor;
      ctx.beginPath();
      ctx.moveTo(px, py);
      ctx.lineTo(px - 10, py + 16);
      ctx.lineTo(px - 4, py + 13);
      ctx.lineTo(px + 4, py + 18);
      ctx.lineTo(px + 10, py + 14);
      ctx.closePath();
      ctx.fill();
      ctx.restore();
    }
  });
}

function drawSteppedPixelCloud(
  ctx: CanvasRenderingContext2D,
  cx: number,
  cy: number,
  rx: number,
  ry: number,
) {
  if (rx <= 0 || ry <= 0) return;
  ctx.save();
  ctx.fillStyle = '#9AA8B8';
  ctx.beginPath();
  ctx.ellipse(cx, cy + 2, Math.max(1, rx), Math.max(1, ry), 0, 0, Math.PI * 2);
  ctx.fill();

  ctx.fillStyle = '#CBD4DE';
  ctx.beginPath();
  ctx.ellipse(cx, cy, Math.max(1, rx - 3), Math.max(1, ry - 2), 0, 0, Math.PI * 2);
  ctx.fill();

  ctx.fillStyle = '#EEF2F6';
  ctx.beginPath();
  ctx.ellipse(cx, cy - 2, Math.max(1, rx - 6), Math.max(1, ry - 4), 0, 0, Math.PI * 2);
  ctx.fill();

  ctx.fillStyle = '#FFFFFF';
  ctx.beginPath();
  ctx.ellipse(cx, cy - 4, Math.max(1, rx - 10), Math.max(1, ry - 6), 0, 0, Math.PI * 2);
  ctx.fill();
  ctx.restore();
}

